INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C1','math',3,2,'u5',2,'들이 비교하기 — 옮겨 담기·모양과 크기가 같은 그릇에 옮겨 담기·같은 컵으로 몇 번 들어가는지 세기로 들이를 견주고, 재는 그릇이 다르면 수가 달라져 같은 단위가 필요함을 알기',ARRAY['4수03-17']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C2','math',3,2,'u5',2,'들이의 단위 L와 mL — 1 L = 1000 mL를 알고 「몇 L 몇 mL」를 쓰고 읽으며, 몇 L 몇 mL ↔ 몇 mL로 바꾸어 크기를 견주기',ARRAY['4수03-18']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C3','math',3,2,'u5',3,'들이 어림하고 재기 — 아는 들이와 견주어 어림하고 「약」을 붙이며, 눈금 한 칸의 크기를 먼저 구해 비커를 읽고, 들이에 알맞은 단위(mL·L)를 고르기',ARRAY['4수03-17']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C4','math',3,2,'u5',4,'들이의 덧셈과 뺄셈 — L는 L끼리, mL는 mL끼리 같은 단위의 수끼리 더하고 빼기(받아올림·받아내림이 없는 계산), 실생활 상황에서 모두·남은·차를 구하는 식을 세워 해결하기',ARRAY['4수03-19']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C5','math',3,2,'u5',5,'무게 비교하기 — 양손·양팔저울로 견주고(내려간 쪽이 무거움), 바둑돌·공깃돌 같은 단위 물건의 개수로 얼마나 더 무거운지 재며, 단위 물건이 다르면 결과가 달라짐을 알기',ARRAY['4수03-20']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C6','math',3,2,'u5',6,'무게의 단위 kg과 g — 1 kg = 1000 g을 알고 「몇 kg 몇 g」을 쓰고 읽으며, 몇 kg 몇 g ↔ 몇 g으로 바꾸어 크기를 견주고 저울 눈금을 읽기',ARRAY['4수03-21']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C7','math',3,2,'u5',6,'무게의 단위 t — 아주 무거운 무게는 t으로 나타내고 1 t = 1000 kg임을 알아 t ↔ kg으로 바꾸기',ARRAY['4수03-22']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C8','math',3,2,'u5',7,'무게 어림하고 재기 — 아는 무게(클립 약 1 g, 밀가루 1 kg)와 견주어 어림하고 「약」을 붙이며, 저울 눈금 한 칸의 크기를 먼저 구해 읽고, 알맞은 단위(g·kg·t)를 고르기',ARRAY['4수03-20']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C9','math',3,2,'u5',8,'무게의 덧셈과 뺄셈 — kg은 kg끼리, g은 g끼리 같은 단위의 수끼리 더하고 빼기(받아올림·받아내림이 없는 계산), 실생활 상황에서 모두·남은·차를 구하는 식을 세워 해결하기',ARRAY['4수03-23']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C10','math',3,2,'u5',9,'남김없이 나누어 담기 — 예상하고 확인하며 여러 통·봉지에 남김없이 나누어 담는 방법을 찾고, 담은 양을 모두 더해 목표와 견주며 합의 일의 자리·표로 빠짐없이 찾기',ARRAY['4수03-19·4수03-23']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X01','math',3,'u5',ARRAY['M3-2-u5-C1']::text[],'모양과 크기가 다른 그릇인데 물의 높이(겉모양)만 보고 들이를 견준다','같은 그릇에 옮겨 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X02','math',3,'u5',ARRAY['M3-2-u5-C1']::text[],'옮겨 담은 결과를 거꾸로 읽는다(부었더니 넘쳤는데 받은 그릇의 들이가 더 많다고 한다)','넘치면 받은 그릇이 작아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X03','math',3,'u5',ARRAY['M3-2-u5-C1','M3-2-u5-C5']::text[],'재는 그릇(단위 물건)이 다른데 횟수·개수만 견주거나, 횟수가 많을수록 재는 그릇이 크다고 한다','같은 단위로 재기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X04','math',3,'u5',ARRAY['M3-2-u5-C2','M3-2-u5-C6']::text[],'1 L = 100 mL(1 kg = 100 g)처럼 바꾼다(3 L 150 mL → 450 mL)','1 L = 1000 mL') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X05','math',3,'u5',ARRAY['M3-2-u5-C2','M3-2-u5-C6']::text[],'몇 L 몇 mL를 몇 mL로 바꿀 때 자리의 0을 빠뜨리거나 수를 이어 쓴다(7 L 50 mL → 750 mL·7500 mL)','1000씩 + 나머지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X06','math',3,'u5',ARRAY['M3-2-u5-C2','M3-2-u5-C6','M3-2-u5-C7']::text[],'큰 단위와 작은 단위를 바꾸어 쓰거나 읽는다(3 L 300 mL → 3 밀리리터 300 리터)','앞이 큰 단위') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X07','math',3,'u5',ARRAY['M3-2-u5-C3','M3-2-u5-C6','M3-2-u5-C8']::text[],'눈금 한 칸의 크기를 구하지 않고 칸 수를 그대로 읽거나 칸을 하나 더·덜 센다(한 칸 200 g인 7칸 → 700 g)','한 칸의 크기부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X08','math',3,'u5',ARRAY['M3-2-u5-C3','M3-2-u5-C8']::text[],'아는 양과 견주지 않고 어림하거나 「약」을 빼거나 잘못 붙이고, 어림한 값과 잰 값이 다르면 틀렸다고 한다','어림은 약 ○○') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X09','math',3,'u5',ARRAY['M3-2-u5-C3','M3-2-u5-C7','M3-2-u5-C8']::text[],'물건에 알맞지 않은 크기의 단위를 고른다(어항 약 25 mL, 코끼리 약 3 kg)','작으면 작은 단위') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X10','math',3,'u5',ARRAY['M3-2-u5-C3','M3-2-u5-C8']::text[],'들이의 단위(L·mL)와 무게의 단위(kg·g·t)를 섞어 쓴다','들이 L·mL, 무게 kg·g') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X11','math',3,'u5',ARRAY['M3-2-u5-C4','M3-2-u5-C9']::text[],'다른 단위의 수끼리 더하거나 뺀다(L의 수와 mL의 수를 셈한다)','같은 단위끼리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X14','math',3,'u5',ARRAY['M3-2-u5-C4','M3-2-u5-C9','M3-2-u5-C10']::text[],'덧셈과 뺄셈을 바꾸어 한다(남은 양·더 필요한 양을 묻는데 더한다)','모두·남은·더 필요한') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X15','math',3,'u5',ARRAY['M3-2-u5-C5']::text[],'양팔저울에서 위로 올라간 쪽이 더 무겁다고 한다','내려간 쪽이 무거움') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X16','math',3,'u5',ARRAY['M3-2-u5-C5']::text[],'크기가 크면 더 무겁다고 하거나, 단위 물건의 종류는 보지 않고 개수만 같으면 무게가 같다고 한다','크기 ≠ 무게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X17','math',3,'u5',ARRAY['M3-2-u5-C7']::text[],'1 t = 100 kg(또는 10000 kg)처럼 바꾼다(6 t → 600 kg)','1 t = 1000 kg') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X18','math',3,'u5',ARRAY['M3-2-u5-C4','M3-2-u5-C9','M3-2-u5-C10']::text[],'남김없이 담기에서 담은 양을 모두 더해 목표와 견주지 않는다(통의 수만 맞추거나 합이 모자라거나 넘친다)','모두 더해 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X19','math',3,'u5',ARRAY['M3-2-u5-C10']::text[],'통의 개수와 통에 담는 양을 헷갈리거나, 있는 통보다 많이 쓴다','통 수 × 통 하나의 양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X20','math',3,'u5',ARRAY['M3-2-u5-C1','M3-2-u5-C2','M3-2-u5-C3','M3-2-u5-C4','M3-2-u5-C5','M3-2-u5-C6','M3-2-u5-C7','M3-2-u5-C8','M3-2-u5-C9','M3-2-u5-C10']::text[],'묻는 말을 거꾸로 읽는다 — 많은↔적은, 무거운↔가벼운, 남은↔쓴, 더↔덜','물음의 핵심 말에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X21','math',3,'u5',ARRAY['M3-2-u5-C1','M3-2-u5-C2','M3-2-u5-C3','M3-2-u5-C5','M3-2-u5-C6','M3-2-u5-C8','M3-2-u5-C10']::text[],'견줄 수 있는데도 「같다」·「알 수 없다」고 하거나, 차를 묻는데 한쪽의 양을 답한다','단위를 맞추어 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X22','math',3,'u5',ARRAY['M3-2-u5-C1','M3-2-u5-C5']::text[],'같은 단위로 잰 개수(횟수)와 양의 관계를 거꾸로 본다 — 공깃돌 10개인 지우개보다 8개인 연필이 더 무겁다고 하거나, 국자로 2번 들어간 컵의 들이가 더 많다고 한다','같은 단위로 재면 개수가 많을수록 더 무겁고 들이가 많아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X23','math',3,'u5',ARRAY['M3-2-u5-C2','M3-2-u5-C6','M3-2-u5-C7']::text[],'큰 단위가 붙은 양이 작은 단위로만 쓴 양보다 언제나 크다고 본다 — 1 t이 1300 kg보다, 1 L 100 mL가 1200 mL보다 많다고 한다','한 가지 단위로 바꾸어 수를 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X24','math',3,'u5',ARRAY['M3-2-u5-C4','M3-2-u5-C9']::text[],'식은 바르게 세우지만 같은 단위의 수끼리 따로 셈하지 않아 결과가 어긋난다 — 1 L 300 mL + 1 L 400 mL = 2 L 800 mL, 5 kg 800 g − 4 kg 100 g = 1 kg 900 g','L는 L끼리, mL는 mL끼리 따로 셈하고 다시 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_basic#1','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C1',1,'mc','auto','모양과 크기가 같은 컵 가, 나, 다에 우유가 들어 있어요. 우유가 많이 들어 있는 컵부터 차례대로 쓴 것은 어느 것인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X01','M3-2-u5-X21']::text[],true,'{"seq":1,"concept":"M3-2-u5-C1","difficulty":1,"kind":"mc","stem":"모양과 크기가 같은 컵 가, 나, 다에 우유가 들어 있어요. 우유가 많이 들어 있는 컵부터 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"가, 다, 나","correct":true},{"t":"나, 다, 가","mis":"M3-2-u5-X20"},{"t":"가, 나, 다","mis":"M3-2-u5-X01"},{"t":"세 컵 모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["모양과 크기가 같은 컵이라 우유의 높이로 견줄 수 있어요.","우유의 높이는 가 컵이 가장 높고, 그다음은 다 컵, 나 컵 차례예요.","많이 들어 있는 컵부터 — 가, 다, 나."],"asset":{"type":"cups","items":[{"label":"가","w":2,"h":4,"fill":0.85},{"label":"나","w":2,"h":4,"fill":0.3},{"label":"다","w":2,"h":4,"fill":0.55}],"same":true},"variant_rule":{"alt":[{"stem":"욕조, 주전자, 밥그릇 가운데 담을 수 있는 양이 가장 많은 것은 어느 것인가요?","options":[{"t":"욕조","correct":true},{"t":"주전자","mis":"M3-2-u5-X20"},{"t":"밥그릇","mis":"M3-2-u5-X20"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["담을 수 있는 양이 많을수록 그릇이 커요.","욕조에는 주전자나 밥그릇보다 훨씬 많은 물이 들어가요.","담을 수 있는 양이 가장 많은 것은 욕조예요."],"asset":null},{"stem":"양팔저울에 배와 귤을 올렸더니 배 쪽이 아래로 내려갔어요. 배와 귤 가운데 더 무거운 과일은 어느 것인가요?","options":[{"t":"배","correct":true},{"t":"귤","mis":"M3-2-u5-X15"},{"t":"두 과일의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","배 쪽이 내려갔어요.","더 무거운 과일은 배예요."],"asset":{"type":"balance","scales":[{"l":{"name":"배","icon":"📦"},"r":{"name":"귤","icon":"🍊"},"down":"l"}]}},{"stem":"돼지, 고양이, 다람쥐의 무게를 비교하여 무거운 동물부터 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"돼지, 고양이, 다람쥐","correct":true},{"t":"다람쥐, 고양이, 돼지","mis":"M3-2-u5-X20"},{"t":"고양이, 돼지, 다람쥐","mis":"M3-2-u5-X16"},{"t":"세 동물의 무게가 같아요","mis":"M3-2-u5-X21"}],"explanation":["세 동물을 무게로 견주어요.","돼지가 가장 무겁고, 고양이, 다람쥐 차례로 가벼워요.","무거운 동물부터 — 돼지, 고양이, 다람쥐."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_basic#2','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C2',1,'sa','auto','3 L 150 mL는 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C2","difficulty":1,"kind":"sa","stem":"3 L 150 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["3150"],"explanation":["1 L = 1000 mL — 3 L = 3000 mL.","3000 mL + 150 mL = 3150 mL.","3 L 150 mL = 3150 mL."],"variant_rule":{"alt":[{"stem":"1 L 800 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["1800"],"explanation":["1 L = 1000 mL예요.","1000 mL + 800 mL = 1800 mL.","1 L 800 mL = 1800 mL."]},{"stem":"3 L 300 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["3300"],"explanation":["1 L = 1000 mL — 3 L = 3000 mL.","3000 mL + 300 mL = 3300 mL.","3 L 300 mL = 3300 mL."]},{"stem":"3 L 400 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["3400"],"explanation":["1 L = 1000 mL — 3 L = 3000 mL.","3000 mL + 400 mL = 3400 mL.","3 L 400 mL = 3400 mL."]},{"stem":"3학년 1학기에 배운 길이의 단위를 떠올려요. 1 km 800 m는 몇 m인가요? 숫자로 쓰세요.","answer":["1800"],"explanation":["1 km = 1000 m예요 — 1 L = 1000 mL와 닮았어요.","1000 m + 800 m = 1800 m.","1 km 800 m = 1800 m."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_basic#3','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C1',1,'mc','auto','은비가 빨간색 컵에 물을 가득 채워 초록색 컵에 모두 부었더니 초록색 컵이 가득 차지 않았어요. 물을 더 많이 담을 수 있는 컵은 어느 것인가요?',ARRAY['M3-2-u5-X02','M3-2-u5-X21']::text[],true,'{"seq":3,"concept":"M3-2-u5-C1","difficulty":1,"kind":"mc","stem":"은비가 빨간색 컵에 물을 가득 채워 초록색 컵에 모두 부었더니 초록색 컵이 가득 차지 않았어요. 물을 더 많이 담을 수 있는 컵은 어느 것인가요?","options":[{"t":"초록색 컵","correct":true},{"t":"빨간색 컵","mis":"M3-2-u5-X02"},{"t":"두 컵의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["빨간색 컵에 가득 담은 물을 초록색 컵에 모두 부었어요.","초록색 컵에 빈 곳이 남았으니 초록색 컵에 더 많이 담을 수 있어요.","물을 더 많이 담을 수 있는 컵은 초록색 컵이에요."],"asset":{"type":"cups","items":[{"label":"초록색 컵","w":3,"h":5},{"label":"빨간색 컵","w":3,"h":4}],"pour":{"from":1,"to":0}},"variant_rule":{"alt":[{"stem":"주스병에 물을 가득 채운 후 물통에 모두 옮겨 담았더니 물이 넘쳤어요. 주스병과 물통 가운데 들이가 더 많은 것은 어느 것인가요?","options":[{"t":"주스병","correct":true},{"t":"물통","mis":"M3-2-u5-X02"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["주스병에 가득 담은 물을 물통에 부었어요.","물이 넘쳤으니 물통에 다 담기지 못했어요 — 주스병의 들이가 더 많아요.","들이가 더 많은 것은 주스병이에요."],"asset":{"type":"cups","items":[{"label":"주스병","w":3,"h":5},{"label":"물통","w":3,"h":4}],"pour":{"from":0,"to":1}}},{"stem":"㉮ 컵에 물을 가득 채워 ㉯ 컵에 부었더니 ㉯ 컵이 가득 차지 않았어요. 들이가 더 많은 컵은 어느 것인가요?","options":[{"t":"㉯ 컵","correct":true},{"t":"㉮ 컵","mis":"M3-2-u5-X02"},{"t":"두 컵의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["㉮ 컵에 가득 담은 물을 ㉯ 컵에 부었어요.","㉯ 컵에 빈 곳이 남았으니 ㉯ 컵에 더 많이 담을 수 있어요.","들이가 더 많은 컵은 ㉯ 컵이에요."],"asset":{"type":"cups","items":[{"label":"㉮ 컵","w":3,"h":4},{"label":"㉯ 컵","w":3,"h":5}],"pour":{"from":0,"to":1}}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_basic#4','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C1',1,'mc','auto','분무기와 주전자에 물을 가득 채운 후 모양과 크기가 같은 수조에 각각 모두 옮겨 담았어요. 들이가 더 많은 것은 어느 것인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X21']::text[],true,'{"seq":4,"concept":"M3-2-u5-C1","difficulty":1,"kind":"mc","stem":"분무기와 주전자에 물을 가득 채운 후 모양과 크기가 같은 수조에 각각 모두 옮겨 담았어요. 들이가 더 많은 것은 어느 것인가요?","options":[{"t":"주전자","correct":true},{"t":"분무기","mis":"M3-2-u5-X20"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["모양과 크기가 같은 수조라서 물의 높이로 견줄 수 있어요.","주전자의 물을 담은 수조의 물이 더 높아요.","들이가 더 많은 것은 주전자예요."],"asset":{"type":"cups","items":[{"label":"분무기 물","w":3,"h":5,"fill":0.35},{"label":"주전자 물","w":3,"h":5,"fill":0.75}],"same":true},"variant_rule":{"alt":[{"stem":"초록색 컵과 빨간색 컵에 물을 가득 채운 후 모양과 크기가 같은 수조에 각각 모두 옮겨 담았어요. 물을 더 많이 담을 수 있는 컵은 어느 것인가요?","options":[{"t":"초록색 컵","correct":true},{"t":"빨간색 컵","mis":"M3-2-u5-X20"},{"t":"두 컵의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["모양과 크기가 같은 수조라서 물의 높이로 견줄 수 있어요.","초록색 컵의 물을 담은 수조의 물이 더 높아요.","물을 더 많이 담을 수 있는 컵은 초록색 컵이에요."],"asset":{"type":"cups","items":[{"label":"초록색 컵 물","w":3,"h":5,"fill":0.7},{"label":"빨간색 컵 물","w":3,"h":5,"fill":0.55}],"same":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_basic#5','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C1',2,'sa','auto','㉮ 그릇과 ㉯ 그릇에 물을 가득 채운 후 모양과 크기가 같은 작은 컵에 모두 옮겨 담았더니 ㉮ 그릇의 물은 작은 컵 5개, ㉯ 그릇의 물은 작은 컵 3개를 채웠어요. ㉮ 그릇은 ㉯ 그릇보다 작은 컵 몇 개만큼 물을 더 많이 담을 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u5-C1","difficulty":2,"kind":"sa","stem":"㉮ 그릇과 ㉯ 그릇에 물을 가득 채운 후 모양과 크기가 같은 작은 컵에 모두 옮겨 담았더니 ㉮ 그릇의 물은 작은 컵 5개, ㉯ 그릇의 물은 작은 컵 3개를 채웠어요. ㉮ 그릇은 ㉯ 그릇보다 작은 컵 몇 개만큼 물을 더 많이 담을 수 있나요? 숫자로 쓰세요.","answer":["2"],"explanation":["같은 작은 컵으로 재었으니 컵의 수로 견줄 수 있어요.","㉮ 그릇 5개, ㉯ 그릇 3개 — 컵의 수가 많을수록 들이가 많아요.","5 − 3 = 2 — 작은 컵 2개만큼 더 많이 담을 수 있어요."],"variant_rule":{"alt":[{"stem":"가 컵과 나 컵에 가득 담긴 물을 같은 국자로 옮겨 담았더니 가 컵은 국자로 2번, 나 컵은 국자로 5번이었어요. 나 컵은 가 컵보다 국자로 몇 번만큼 물을 더 많이 담을 수 있나요? 숫자로 쓰세요.","answer":["3"],"explanation":["같은 국자로 재었으니 옮겨 담은 횟수로 견줄 수 있어요.","가 컵 2번, 나 컵 5번이에요.","5 − 2 = 3 — 국자로 3번만큼 더 많이 담을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_basic#6','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C1',2,'mc','auto','가 컵, 나 컵, 다 컵에 가득 담긴 물을 같은 국자로 몇 번에 옮겨 담을 수 있는지 재었어요. 가 컵은 국자로 2번, 나 컵은 5번, 다 컵은 4번이에요. 들이가 가장 많은 컵은 어느 것인가요?',ARRAY['M3-2-u5-X22','M3-2-u5-X20','M3-2-u5-X21']::text[],true,'{"seq":6,"concept":"M3-2-u5-C1","difficulty":2,"kind":"mc","stem":"가 컵, 나 컵, 다 컵에 가득 담긴 물을 같은 국자로 몇 번에 옮겨 담을 수 있는지 재었어요. 가 컵은 국자로 2번, 나 컵은 5번, 다 컵은 4번이에요. 들이가 가장 많은 컵은 어느 것인가요?","options":[{"t":"나 컵","correct":true},{"t":"가 컵","mis":"M3-2-u5-X22"},{"t":"다 컵","mis":"M3-2-u5-X20"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["같은 국자로 재었으니 옮겨 담은 횟수로 견줄 수 있어요.","국자로 옮긴 횟수가 많을수록 컵의 들이가 많아요 — 나 5번, 다 4번, 가 2번.","들이가 가장 많은 컵은 나 컵이에요."],"variant_rule":{"alt":[{"stem":"나의 물통과 친구의 물통의 들이를 같은 그릇으로 재었더니 나의 물통은 그릇으로 2개, 친구의 물통은 그릇으로 3개였어요. 들이가 더 많은 물통은 어느 것인가요?","options":[{"t":"친구의 물통","correct":true},{"t":"나의 물통","mis":"M3-2-u5-X22"},{"t":"두 물통의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["같은 그릇으로 재었으니 그릇의 수로 견줄 수 있어요.","나의 물통 2개, 친구의 물통 3개 — 수가 많을수록 들이가 많아요.","들이가 더 많은 물통은 친구의 물통이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_basic#7','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C1',2,'mc','auto','물통의 들이를 재었더니 나의 물통은 그릇으로 2개, 친구의 물통은 찻잔으로 6개였어요. 이것만 보고 바르게 말한 것은 어느 것인가요?',ARRAY['M3-2-u5-X03','M3-2-u5-X21']::text[],true,'{"seq":7,"concept":"M3-2-u5-C1","difficulty":2,"kind":"mc","stem":"물통의 들이를 재었더니 나의 물통은 그릇으로 2개, 친구의 물통은 찻잔으로 6개였어요. 이것만 보고 바르게 말한 것은 어느 것인가요?","options":[{"t":"재는 단위가 달라서 수만으로는 비교할 수 없어요","correct":true},{"t":"친구의 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"나의 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"두 물통의 들이가 같아요","mis":"M3-2-u5-X21"}],"explanation":["나의 물통은 그릇, 친구의 물통은 찻잔으로 재었어요 — 재는 단위가 달라요.","그릇 한 개와 찻잔 한 개의 들이가 다르니 수만으로는 견줄 수 없어요.","물통의 들이를 비교하려면 같은 단위를 사용해야 해요."],"variant_rule":{"alt":[{"stem":"물통의 들이를 재었더니 나의 물통은 찻잔으로 4개, 친구의 물통은 그릇으로 3개였어요. 이것만 보고 바르게 말한 것은 어느 것인가요?","options":[{"t":"재는 단위가 달라서 수만으로는 비교할 수 없어요","correct":true},{"t":"나의 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"친구의 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"두 물통의 들이가 같아요","mis":"M3-2-u5-X21"}],"explanation":["나의 물통은 찻잔, 친구의 물통은 그릇으로 재었어요 — 재는 단위가 달라요.","찻잔 한 개와 그릇 한 개의 들이가 다르니 수만으로는 견줄 수 없어요.","물통의 들이를 비교하려면 같은 단위를 사용해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_basic#8','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C2',2,'mc','auto','3 L 300 mL를 바르게 읽은 것은 어느 것인가요?',ARRAY['M3-2-u5-X06','M3-2-u5-X05']::text[],true,'{"seq":8,"concept":"M3-2-u5-C2","difficulty":2,"kind":"mc","stem":"3 L 300 mL를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"3 리터 300 밀리리터","correct":true},{"t":"3 밀리리터 300 리터","mis":"M3-2-u5-X06"},{"t":"3300 리터","mis":"M3-2-u5-X05"},{"t":"3 리터 300 리터","mis":"M3-2-u5-X06"}],"explanation":["1 L는 1 리터라고 읽어요.","3 L 300 mL의 앞은 리터, 뒤는 밀리리터예요.","3 L 300 mL — 3 리터 300 밀리리터."],"variant_rule":{"alt":[{"stem":"1 L 500 mL를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"1 리터 500 밀리리터","correct":true},{"t":"1 밀리리터 500 리터","mis":"M3-2-u5-X06"},{"t":"1500 리터","mis":"M3-2-u5-X05"},{"t":"1 리터 500 리터","mis":"M3-2-u5-X06"}],"explanation":["1 L는 1 리터라고 읽어요.","1 L 500 mL의 앞은 리터, 뒤는 밀리리터예요.","1 L 500 mL — 1 리터 500 밀리리터."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_basic#9','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C2',2,'mc','auto','4800 mL는 몇 L 몇 mL인가요?',ARRAY['M3-2-u5-X04','M3-2-u5-X05','M3-2-u5-X06']::text[],true,'{"seq":9,"concept":"M3-2-u5-C2","difficulty":2,"kind":"mc","stem":"4800 mL는 몇 L 몇 mL인가요?","options":[{"t":"4 L 800 mL","correct":true},{"t":"48 L","mis":"M3-2-u5-X04"},{"t":"4 L 80 mL","mis":"M3-2-u5-X05"},{"t":"4 mL 800 L","mis":"M3-2-u5-X06"}],"explanation":["1000 mL = 1 L예요.","4800 mL = 4000 mL + 800 mL.","4800 mL = 4 L 800 mL."],"variant_rule":{"alt":[{"stem":"5800 mL는 몇 L 몇 mL인가요?","options":[{"t":"5 L 800 mL","correct":true},{"t":"58 L","mis":"M3-2-u5-X04"},{"t":"5 L 80 mL","mis":"M3-2-u5-X05"},{"t":"5 mL 800 L","mis":"M3-2-u5-X06"}],"explanation":["1000 mL = 1 L예요.","5800 mL = 5000 mL + 800 mL.","5800 mL = 5 L 800 mL."]},{"stem":"6850 mL는 몇 L 몇 mL인가요?","options":[{"t":"6 L 850 mL","correct":true},{"t":"68 L 50 mL","mis":"M3-2-u5-X04"},{"t":"6 L 85 mL","mis":"M3-2-u5-X05"},{"t":"6 mL 850 L","mis":"M3-2-u5-X06"}],"explanation":["1000 mL = 1 L예요.","6850 mL = 6000 mL + 850 mL.","6850 mL = 6 L 850 mL."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_basic#10','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C2',3,'error','auto','들이의 단위를 바꾸며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u5-X05','M3-2-u5-X20']::text[],false,'{"seq":10,"concept":"M3-2-u5-C2","difficulty":3,"kind":"error","stem":"들이의 단위를 바꾸며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「7 L 50 mL는 750 mL야」","correct":true,"mis_target":"M3-2-u5-X05"},{"t":"민준 — 「7 L 500 mL는 7500 mL야」","mis":"M3-2-u5-X20"},{"t":"서윤 — 「5000 mL는 5 L야」","mis":"M3-2-u5-X20"},{"t":"은비 — 「1 L는 1000 mL야」","mis":"M3-2-u5-X20"}],"explanation":["1 L = 1000 mL — 7 L = 7000 mL.","7 L 50 mL = 7000 mL + 50 mL = 7050 mL.","지아는 자리의 0을 빠뜨렸어요 — 7 L 50 mL = 7050 mL."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_challenge#1','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C2',2,'match','auto','들이가 같은 것끼리 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"M3-2-u5-C2","difficulty":2,"kind":"match","stem":"들이가 같은 것끼리 알맞게 이으세요.","pairs":[{"l":"7 L 50 mL","r":"7050 mL"},{"l":"5000 mL","r":"5 L"},{"l":"7 L 500 mL","r":"7500 mL"}],"mis":"M3-2-u5-X05","explanation":["1 L = 1000 mL — 7 L = 7000 mL, 5 L = 5000 mL.","7 L 50 mL = 7050 mL, 7 L 500 mL = 7500 mL.","7 L 50 mL와 7 L 500 mL는 다른 들이예요 — 자리의 0을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_challenge#2','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C2',2,'sa','auto','유리병에 음료수를 1 L 넣은 후 500 mL를 더 넣었더니 유리병이 가득 찼어요. 유리병의 들이는 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C2","difficulty":2,"kind":"sa","stem":"유리병에 음료수를 1 L 넣은 후 500 mL를 더 넣었더니 유리병이 가득 찼어요. 유리병의 들이는 몇 mL인가요? 숫자로 쓰세요.","answer":["1500"],"explanation":["1 L보다 500 mL 더 많은 들이는 1 L 500 mL예요.","1 L = 1000 mL — 1000 mL + 500 mL = 1500 mL.","1 L 500 mL = 1500 mL."],"variant_rule":{"alt":[{"stem":"우유병의 들이는 1 L 100 mL예요. 우유병의 들이는 몇 mL인가요? 숫자로 쓰세요.","answer":["1100"],"explanation":["1 L = 1000 mL예요.","1000 mL + 100 mL = 1100 mL.","1 L 100 mL = 1100 mL."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_challenge#3','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C2',3,'mc','auto','우유병의 들이는 1 L 100 mL, 꽃병의 들이는 1200 mL, 대접의 들이는 1150 mL예요. 들이가 많은 것부터 차례대로 쓴 것은 어느 것인가요?',ARRAY['M3-2-u5-X23','M3-2-u5-X20','M3-2-u5-X05']::text[],false,'{"seq":3,"concept":"M3-2-u5-C2","difficulty":3,"kind":"mc","stem":"우유병의 들이는 1 L 100 mL, 꽃병의 들이는 1200 mL, 대접의 들이는 1150 mL예요. 들이가 많은 것부터 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"꽃병, 대접, 우유병","correct":true},{"t":"우유병, 꽃병, 대접","mis":"M3-2-u5-X23"},{"t":"우유병, 대접, 꽃병","mis":"M3-2-u5-X20"},{"t":"대접, 꽃병, 우유병","mis":"M3-2-u5-X05"}],"explanation":["한 가지 단위로 바꾸어 견주어요 — 1 L 100 mL = 1100 mL.","꽃병 1200 mL > 대접 1150 mL > 우유병 1100 mL.","들이가 많은 것부터 — 꽃병, 대접, 우유병. L가 붙었다고 더 많은 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_challenge#4','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C1',3,'ox','auto','같은 물통의 들이를 그릇으로 재면 2개, 찻잔으로 재면 4개예요. 친구가 「찻잔으로 잰 수가 더 크니까 찻잔 한 개의 들이가 그릇 한 개보다 더 많아.」라고 말했어요. 바르게 말했어요.',ARRAY['M3-2-u5-X03']::text[],true,'{"seq":4,"concept":"M3-2-u5-C1","difficulty":3,"kind":"ox","stem":"같은 물통의 들이를 그릇으로 재면 2개, 찻잔으로 재면 4개예요. 친구가 「찻잔으로 잰 수가 더 크니까 찻잔 한 개의 들이가 그릇 한 개보다 더 많아.」라고 말했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"들이가 적은 단위일수록 더 여러 번 들어가서","correct":true},{"t":"잰 수가 클수록 단위의 들이가 커서","mis":"M3-2-u5-X03"}],"mis":"M3-2-u5-X03","explanation":["같은 물통을 재었는데 그릇 2개, 찻잔 4개예요.","들이가 적은 찻잔이라서 더 여러 번 들어갔어요.","찻잔 한 개의 들이가 그릇 한 개보다 적어요 — 바르지 않아요."],"variant_rule":{"alt":[{"stem":"친구의 물통의 들이를 그릇으로 재면 3개, 찻잔으로 재면 6개예요. 친구가 「찻잔으로 잰 수가 더 크니까 찻잔 한 개의 들이가 그릇 한 개보다 더 많아.」라고 말했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"들이가 적은 단위일수록 더 여러 번 들어가서","correct":true},{"t":"잰 수가 클수록 단위의 들이가 커서","mis":"M3-2-u5-X03"}],"explanation":["같은 물통을 재었는데 그릇 3개, 찻잔 6개예요.","들이가 적은 찻잔이라서 더 여러 번 들어갔어요.","찻잔 한 개의 들이가 그릇 한 개보다 적어요 — 바르지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_challenge#5','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C1',3,'mc','auto','병에 가득 들어 있는 주스를 컵에 옮겨 담았더니 2컵보다 많고 3컵보다 적었어요. 주스병의 들이를 정확하게 나타내려면 어떻게 해야 하나요?',ARRAY['M3-2-u5-X08','M3-2-u5-X03','M3-2-u5-X21']::text[],false,'{"seq":5,"concept":"M3-2-u5-C1","difficulty":3,"kind":"mc","stem":"병에 가득 들어 있는 주스를 컵에 옮겨 담았더니 2컵보다 많고 3컵보다 적었어요. 주스병의 들이를 정확하게 나타내려면 어떻게 해야 하나요?","options":[{"t":"누구나 똑같이 약속한 들이의 단위로 재요","correct":true},{"t":"주스병의 들이는 3컵이라고 해요","mis":"M3-2-u5-X08"},{"t":"컵 대신 그릇으로 다시 재면 정확해요","mis":"M3-2-u5-X03"},{"t":"들이는 정확하게 나타낼 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["주스병의 들이는 컵 2개의 들이보다 많고 3개의 들이보다 적은 양이에요.","컵이나 그릇처럼 사람마다 다른 단위로는 정확하게 나타내기 어려워요.","들이를 정확하게 나타내는 약속된 단위(L, mL)가 필요해요."],"asset":{"type":"speech","turns":[{"who":"은비","text":"병에 가득 들어 있는 주스를 컵에 옮겨 담아 보자."},{"who":"서준","text":"주스는 2컵보다 많고 3컵보다 적어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_challenge#6','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C2',3,'sa','auto','5800 mL는 몇 L 몇 mL인가요? mL 앞에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u5-C2","difficulty":3,"kind":"sa","stem":"5800 mL는 몇 L 몇 mL인가요? mL 앞에 알맞은 수를 쓰세요.","answer":["800"],"explanation":["1000 mL = 1 L예요.","5800 mL = 5000 mL + 800 mL.","5800 mL = 5 L 800 mL — mL 앞의 수는 800이에요."],"variant_rule":{"alt":[{"stem":"4800 mL는 몇 L 몇 mL인가요? L 앞에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["1000 mL = 1 L예요.","4800 mL = 4000 mL + 800 mL.","4800 mL = 4 L 800 mL — L 앞의 수는 4예요."]},{"stem":"6850 mL는 몇 L 몇 mL인가요? mL 앞에 알맞은 수를 쓰세요.","answer":["850"],"explanation":["1000 mL = 1 L예요.","6850 mL = 6000 mL + 850 mL.","6850 mL = 6 L 850 mL — mL 앞의 수는 850이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_challenge#7','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C2',3,'sa','auto','「야드파운드법」에 따라 약속한 들이의 단위 1쿼트는 945 mL를 나타내요. 1 L는 1쿼트보다 몇 mL 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u5-C2","difficulty":3,"kind":"sa","stem":"「야드파운드법」에 따라 약속한 들이의 단위 1쿼트는 945 mL를 나타내요. 1 L는 1쿼트보다 몇 mL 더 많은가요? 숫자로 쓰세요.","answer":["55"],"explanation":["1 L = 1000 mL예요.","1000 mL − 945 mL = 55 mL.","1 L가 1쿼트보다 55 mL 더 많아요."],"variant_rule":{"alt":[{"stem":"「야드파운드법」에 따라 약속한 들이의 단위 1파인트는 473 mL를 나타내요. 1 L는 1파인트보다 몇 mL 더 많은가요? 숫자로 쓰세요.","answer":["527"],"explanation":["1 L = 1000 mL예요.","1000 mL − 473 mL = 527 mL.","1 L가 1파인트보다 527 mL 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_challenge#8','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C1',4,'essay','teacher','은비는 초록색 컵과 빨간색 컵 가운데 물을 더 많이 담을 수 있는 컵을 사려고 해요. 두 컵의 높이가 비슷해서 눈으로 비교하기 어려워요. 두 컵의 들이를 비교하는 방법 두 가지를 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u5-C1","difficulty":4,"kind":"essay","stem":"은비는 초록색 컵과 빨간색 컵 가운데 물을 더 많이 담을 수 있는 컵을 사려고 해요. 두 컵의 높이가 비슷해서 눈으로 비교하기 어려워요. 두 컵의 들이를 비교하는 방법 두 가지를 설명해 보세요.","answer_guide":{"answer":"예: ① 한 컵에 물을 가득 채워 다른 컵에 옮겨 담는다. 빨간색 컵의 물을 초록색 컵에 부었을 때 초록색 컵이 가득 차지 않으면 초록색 컵의 들이가 더 많다. ② 두 컵에 물을 가득 채워 모양과 크기가 같은 수조에 각각 옮겨 담고 물의 높이를 비교한다. 물이 더 높은 쪽 컵의 들이가 더 많다.","scoring_points":["한 컵의 물을 다른 컵에 옮겨 담는 방법을 썼는가","같은 수조에 각각 옮겨 높이를 비교하는 방법을 썼는가","어느 쪽이 들이가 더 많은지 판단하는 기준을 썼는가"]},"explanation":["직접 비교 — 한 컵의 물을 다른 컵에 옮겨 담아요.","간접 비교 — 모양과 크기가 같은 수조에 각각 옮겨 물의 높이를 견주어요.","높이가 비슷한 컵은 눈으로만 보고 정하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_challenge#9','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C2',4,'essay','teacher','친구가 4800 mL를 「48 L」라고 나타냈어요. 무엇이 잘못되었는지 쓰고, 4800 mL를 몇 L 몇 mL로 바르게 나타내 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u5-C2","difficulty":4,"kind":"essay","stem":"친구가 4800 mL를 「48 L」라고 나타냈어요. 무엇이 잘못되었는지 쓰고, 4800 mL를 몇 L 몇 mL로 바르게 나타내 보세요.","answer_guide":{"answer":"예: 1 L는 1000 mL인데 100 mL를 1 L로 생각하였다. 4800 mL는 4000 mL와 800 mL로 가를 수 있고 4000 mL는 4 L이므로 4800 mL = 4 L 800 mL이다. 거꾸로 4 L 800 mL = 4000 + 800 = 4800(mL)로 확인할 수 있다.","scoring_points":["1 L = 1000 mL를 이용해야 한다고 했는가","4800 mL = 4 L 800 mL로 나타냈는가","4000 + 800 = 4800으로 확인했는가"]},"explanation":["1 L = 1000 mL — 1000 mL씩 묶어요.","4800 mL = 4000 mL + 800 mL = 4 L 800 mL.","4 L 800 mL = 4800 mL로 거꾸로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L02_challenge#10','math',3,2,'u5','L02','tb_g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C1',4,'essay','teacher','나의 물통과 친구의 물통의 들이를 그릇과 찻잔으로 재었어요. 그릇으로는 나의 물통 2개, 친구의 물통 3개였고, 찻잔으로는 나의 물통 4개, 친구의 물통 6개였어요. 같은 물통인데 결과가 다른 까닭과, 들이를 비교하거나 나타낼 때 필요한 것을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u5-C1","difficulty":4,"kind":"essay","stem":"나의 물통과 친구의 물통의 들이를 그릇과 찻잔으로 재었어요. 그릇으로는 나의 물통 2개, 친구의 물통 3개였고, 찻잔으로는 나의 물통 4개, 친구의 물통 6개였어요. 같은 물통인데 결과가 다른 까닭과, 들이를 비교하거나 나타낼 때 필요한 것을 써 보세요.","answer_guide":{"answer":"예: 그릇 한 개와 찻잔 한 개의 들이가 다르기 때문에 같은 물통을 재어도 수가 다르다. 물통의 들이를 비교하려면 같은 단위를 사용해야 하고, 누구에게나 정확하게 나타내려면 L, mL처럼 약속된 단위가 필요하다.","scoring_points":["그릇과 찻잔의 들이가 달라서라고 썼는가","같은 단위를 사용해야 한다고 썼는가","약속된 단위(L, mL)가 필요하다고 썼는가"]},"explanation":["그릇으로 재면 2개와 3개, 찻잔으로 재면 4개와 6개예요.","재는 단위의 들이가 다르면 수가 달라져요.","같은 단위, 그리고 약속된 단위 L·mL가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_basic#1','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',1,'mc','auto','양치 컵의 들이가 200 mL쯤 될 것 같다고 어림했어요. 어림한 들이를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u5-X08','M3-2-u5-X09']::text[],true,'{"seq":1,"concept":"M3-2-u5-C3","difficulty":1,"kind":"mc","stem":"양치 컵의 들이가 200 mL쯤 될 것 같다고 어림했어요. 어림한 들이를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"약 200 mL","correct":true},{"t":"200 mL 약","mis":"M3-2-u5-X08"},{"t":"딱 200 mL","mis":"M3-2-u5-X08"},{"t":"약 200 L","mis":"M3-2-u5-X09"}],"explanation":["어림한 값은 앞에 「약」을 붙여 나타내요.","200 mL쯤 → 약 200 mL.","단위도 그대로 — 약 200 mL."],"variant_rule":{"alt":[{"stem":"국그릇의 들이가 400 mL쯤 될 것 같다고 어림했어요. 어림한 들이를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"약 400 mL","correct":true},{"t":"400 mL 약","mis":"M3-2-u5-X08"},{"t":"딱 400 mL","mis":"M3-2-u5-X08"},{"t":"약 400 L","mis":"M3-2-u5-X09"}],"explanation":["어림한 값은 앞에 「약」을 붙여 나타내요.","400 mL쯤 → 약 400 mL.","단위도 그대로 — 약 400 mL."]},{"stem":"찻잔의 들이가 200 mL쯤 될 것 같다고 어림했어요. 어림한 들이를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"약 200 mL","correct":true},{"t":"200 mL 약","mis":"M3-2-u5-X08"},{"t":"딱 200 mL","mis":"M3-2-u5-X08"},{"t":"약 200 L","mis":"M3-2-u5-X09"}],"explanation":["어림한 값은 앞에 「약」을 붙여 나타내요.","200 mL쯤 → 약 200 mL.","단위도 그대로 — 약 200 mL."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_basic#2','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',1,'mc','auto','요구르트병의 들이는 약 65 ○예요. ○에 알맞은 단위는 어느 것인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],true,'{"seq":2,"concept":"M3-2-u5-C3","difficulty":1,"kind":"mc","stem":"요구르트병의 들이는 약 65 ○예요. ○에 알맞은 단위는 어느 것인가요?","options":[{"t":"mL","correct":true},{"t":"L","mis":"M3-2-u5-X09"},{"t":"g","mis":"M3-2-u5-X10"},{"t":"kg","mis":"M3-2-u5-X10"}],"explanation":["요구르트병을 아는 들이와 견주어 보아요.","들이에 쓰는 단위는 mL·L이에요.","요구르트병의 들이는 약 65 mL예요."],"variant_rule":{"alt":[{"stem":"참기름병의 들이는 약 500 ○예요. ○에 알맞은 단위는 어느 것인가요?","options":[{"t":"mL","correct":true},{"t":"L","mis":"M3-2-u5-X09"},{"t":"g","mis":"M3-2-u5-X10"},{"t":"kg","mis":"M3-2-u5-X10"}],"explanation":["참기름병을 아는 들이와 견주어 보아요.","들이에 쓰는 단위는 mL·L이에요.","참기름병의 들이는 약 500 mL예요."]},{"stem":"어항의 들이는 약 25 ○예요. ○에 알맞은 단위는 어느 것인가요?","options":[{"t":"L","correct":true},{"t":"mL","mis":"M3-2-u5-X09"},{"t":"g","mis":"M3-2-u5-X10"},{"t":"kg","mis":"M3-2-u5-X10"}],"explanation":["어항을 아는 들이와 견주어 보아요.","들이에 쓰는 단위는 mL·L이에요.","어항의 들이는 약 25 L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_basic#3','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',1,'sa','auto','컵에 물을 가득 채운 후 비커에 모두 옮겨 담았어요. 비커의 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있고, 물이 0에서부터 3칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u5-C3","difficulty":1,"kind":"sa","stem":"컵에 물을 가득 채운 후 비커에 모두 옮겨 담았어요. 비커의 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있고, 물이 0에서부터 3칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["300"],"explanation":["한 칸의 크기부터: 0~1000 mL 사이 10칸 → 1000 ÷ 10 = 100, 한 칸은 100 mL예요.","3칸 → 100 × 3 = 300.","300 mL예요."],"variant_rule":{"alt":[{"stem":"물을 비커에 담았어요. 비커의 0과 500 mL 사이가 똑같이 5칸으로 나뉘어 있고, 물이 0에서부터 4칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["400"],"explanation":["한 칸의 크기부터: 0~500 mL 사이 5칸 → 500 ÷ 5 = 100, 한 칸은 100 mL예요.","4칸 → 100 × 4 = 400.","400 mL예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_basic#4','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',1,'ox','auto','우유갑(1 L)의 들이를 잴 때는 10 mL까지 잴 수 있는 약통보다 500 mL까지 잴 수 있는 비커가 더 좋아요.',ARRAY['M3-2-u5-X09']::text[],true,'{"seq":4,"concept":"M3-2-u5-C3","difficulty":1,"kind":"ox","stem":"우유갑(1 L)의 들이를 잴 때는 10 mL까지 잴 수 있는 약통보다 500 mL까지 잴 수 있는 비커가 더 좋아요.","answer":"O","reason_options":[{"t":"많은 들이는 많이 잴 수 있는 도구로 재야 편해서","correct":true},{"t":"작은 도구로 여러 번 재야 더 좋아서","mis":"M3-2-u5-X09"}],"mis":"M3-2-u5-X09","explanation":["우유갑의 들이는 1 L = 1000 mL예요.","10 mL 약통으로는 100번이나 재야 해요 — 500 mL 비커가 편해요.","많은 들이는 비커처럼 많이 재는 도구로 재요 — 맞아요."],"variant_rule":{"alt":[{"stem":"숟가락의 들이를 잴 때는 10 mL까지 잴 수 있는 약통보다 500 mL까지 잴 수 있는 비커가 더 좋아요.","answer":"X","reason_options":[{"t":"아주 적은 들이는 적은 들이를 재는 도구로 재야 정확해서","correct":true},{"t":"큰 도구로 재야 언제나 정확해서","mis":"M3-2-u5-X09"}],"explanation":["숟가락에는 아주 적은 양이 들어가요.","500 mL 비커로 재면 눈금을 읽기 어려워요.","아주 적은 들이는 약통으로 재요 — 바르지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_basic#5','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',2,'sa','auto','음료수가 500 mL 정도 들어가는 다회용 컵을 고르려고 해요. 약 500 mL는 약 100 mL인 물건 몇 개의 들이와 비슷한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u5-C3","difficulty":2,"kind":"sa","stem":"음료수가 500 mL 정도 들어가는 다회용 컵을 고르려고 해요. 약 500 mL는 약 100 mL인 물건 몇 개의 들이와 비슷한가요? 숫자로 쓰세요.","answer":["5"],"explanation":["약 100 mL인 물건이 몇 번 들어가는지 생각해요.","100 mL가 5번이면 100 + 100 + 100 + 100 + 100 = 500(mL)이에요.","약 500 mL는 약 100 mL인 물건 5개의 들이와 비슷해요."],"variant_rule":{"alt":[{"stem":"음료수가 500 mL 정도 들어가는 다회용 컵을 고르려고 해요. 약 500 mL는 약 200 mL인 물건 2개와 약 100 mL인 물건 몇 개를 합한 들이와 비슷한가요? 숫자로 쓰세요.","answer":["1"],"explanation":["약 200 mL인 물건 2개는 약 400 mL예요.","500 mL가 되려면 100 mL가 더 있어야 해요.","약 100 mL인 물건 1개를 더 합하면 약 500 mL예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_basic#6','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',2,'mc','auto','친구는 양치 컵에 65 mL 요구르트병을 가득 채운 물이 3번 정도 들어갈 것 같다고 어림했어요. 친구가 어림한 양치 컵의 들이로 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u5-X08','M3-2-u5-X03','M3-2-u5-X09']::text[],false,'{"seq":6,"concept":"M3-2-u5-C3","difficulty":2,"kind":"mc","stem":"친구는 양치 컵에 65 mL 요구르트병을 가득 채운 물이 3번 정도 들어갈 것 같다고 어림했어요. 친구가 어림한 양치 컵의 들이로 알맞은 것은 어느 것인가요?","options":[{"t":"약 200 mL","correct":true},{"t":"약 65 mL","mis":"M3-2-u5-X08"},{"t":"약 3 mL","mis":"M3-2-u5-X03"},{"t":"약 200 L","mis":"M3-2-u5-X09"}],"explanation":["들이를 알고 있는 요구르트병이 몇 번 들어가는지로 어림했어요.","65 mL가 3번이면 65 + 65 + 65 = 195(mL) — 약 200 mL예요.","어림한 값에는 「약」을 붙여요 — 약 200 mL."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_basic#7','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',2,'mc','auto','컵에 물을 가득 채운 후 비커에 모두 옮겨 담았더니 물이 1000 mL 눈금까지 찼어요. 컵의 들이를 L로 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u5-X04','M3-2-u5-X06']::text[],false,'{"seq":7,"concept":"M3-2-u5-C3","difficulty":2,"kind":"mc","stem":"컵에 물을 가득 채운 후 비커에 모두 옮겨 담았더니 물이 1000 mL 눈금까지 찼어요. 컵의 들이를 L로 나타낸 것은 어느 것인가요?","options":[{"t":"1 L","correct":true},{"t":"10 L","mis":"M3-2-u5-X04"},{"t":"100 L","mis":"M3-2-u5-X04"},{"t":"1000 L","mis":"M3-2-u5-X06"}],"explanation":["물이 1000 mL 눈금까지 찼어요 — 컵의 들이는 1000 mL예요.","1000 mL = 1 L예요.","컵의 들이는 1 L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_basic#8','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',2,'mc','auto','단위를 잘못 사용한 것은 어느 것인가요? ㉠ 참기름병의 들이는 약 330 mL입니다. ㉡ 요구르트병의 들이는 약 65 L입니다. ㉢ 간장병의 들이는 약 2 L입니다.',ARRAY['M3-2-u5-X09','M3-2-u5-X21']::text[],false,'{"seq":8,"concept":"M3-2-u5-C3","difficulty":2,"kind":"mc","stem":"단위를 잘못 사용한 것은 어느 것인가요? ㉠ 참기름병의 들이는 약 330 mL입니다. ㉡ 요구르트병의 들이는 약 65 L입니다. ㉢ 간장병의 들이는 약 2 L입니다.","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M3-2-u5-X09"},{"t":"㉢","mis":"M3-2-u5-X09"},{"t":"없어요","mis":"M3-2-u5-X21"}],"explanation":["요구르트병은 한 손에 쏙 들어가는 작은 병이에요.","65 L는 욕조에 가까운 많은 양이라 알맞지 않아요.","㉡이 잘못이에요 — 요구르트병의 들이는 약 65 mL예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_basic#9','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',2,'sa','auto','물통에 물을 가득 채운 후 1000 mL까지 잴 수 있는 비커에 모두 옮겨 담았더니 비커 2개가 가득 차고, 다른 비커에 300 mL가 담겼어요. 물통의 들이는 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u5-C3","difficulty":2,"kind":"sa","stem":"물통에 물을 가득 채운 후 1000 mL까지 잴 수 있는 비커에 모두 옮겨 담았더니 비커 2개가 가득 차고, 다른 비커에 300 mL가 담겼어요. 물통의 들이는 몇 mL인가요? 숫자로 쓰세요.","answer":["2300"],"explanation":["비커 2개가 가득 찼으니 1000 mL + 1000 mL = 2000 mL예요.","남은 비커에 300 mL — 2000 mL + 300 mL = 2300 mL.","물통의 들이는 2300 mL = 2 L 300 mL예요."],"variant_rule":{"alt":[{"stem":"물통에 물을 가득 채운 후 1000 mL까지 잴 수 있는 비커에 모두 옮겨 담았더니 비커 2개가 가득 차고, 다른 비커에 500 mL가 담겼어요. 물통의 들이는 몇 mL인가요? 숫자로 쓰세요.","answer":["2500"],"explanation":["비커 2개가 가득 찼으니 1000 mL + 1000 mL = 2000 mL예요.","남은 비커에 500 mL — 2000 mL + 500 mL = 2500 mL.","물통의 들이는 2500 mL = 2 L 500 mL예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_basic#10','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',3,'mc','auto','병에 가득 들어 있던 물을 500 mL까지 잴 수 있는 비커에 부었더니 500 mL까지 채우고 조금 남았어요. 남은 물의 양을 재기에 가장 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X08','M3-2-u5-X21']::text[],false,'{"seq":10,"concept":"M3-2-u5-C3","difficulty":3,"kind":"mc","stem":"병에 가득 들어 있던 물을 500 mL까지 잴 수 있는 비커에 부었더니 500 mL까지 채우고 조금 남았어요. 남은 물의 양을 재기에 가장 알맞은 것은 어느 것인가요?","options":[{"t":"약통처럼 적은 들이를 잴 수 있는 도구","correct":true},{"t":"더 큰 양동이","mis":"M3-2-u5-X09"},{"t":"눈으로 보고 어림하기","mis":"M3-2-u5-X08"},{"t":"남은 물은 재지 않아요","mis":"M3-2-u5-X21"}],"explanation":["남은 물은 아주 적은 양이에요.","아주 적은 들이는 약통처럼 적은 양을 재는 도구로 재요.","들이를 잴 수 있는 도구를 알맞게 섞어서 사용해요."],"asset":{"type":"speech","turns":[{"who":"서준","text":"500 mL까지 잴 수 있는 비커에 부었더니 500 mL까지 채우고 조금 남았어. 남은 물의 양은 어떻게 잴까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_challenge#1','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',2,'mc','auto','식초병의 들이는 약 330 ○예요. ○에 알맞은 단위는 어느 것인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],true,'{"seq":1,"concept":"M3-2-u5-C3","difficulty":2,"kind":"mc","stem":"식초병의 들이는 약 330 ○예요. ○에 알맞은 단위는 어느 것인가요?","options":[{"t":"mL","correct":true},{"t":"L","mis":"M3-2-u5-X09"},{"t":"g","mis":"M3-2-u5-X10"},{"t":"kg","mis":"M3-2-u5-X10"}],"explanation":["식초병을 아는 들이와 견주어 보아요.","들이에 쓰는 단위는 mL·L이에요.","식초병의 들이는 약 330 mL예요."],"variant_rule":{"alt":[{"stem":"욕조의 들이는 약 40 ○예요. ○에 알맞은 단위는 어느 것인가요?","options":[{"t":"L","correct":true},{"t":"mL","mis":"M3-2-u5-X09"},{"t":"g","mis":"M3-2-u5-X10"},{"t":"kg","mis":"M3-2-u5-X10"}],"explanation":["욕조를 아는 들이와 견주어 보아요.","들이에 쓰는 단위는 mL·L이에요.","욕조의 들이는 약 40 L예요."]},{"stem":"쓰레기통의 들이는 약 20 ○예요. ○에 알맞은 단위는 어느 것인가요?","options":[{"t":"L","correct":true},{"t":"mL","mis":"M3-2-u5-X09"},{"t":"g","mis":"M3-2-u5-X10"},{"t":"kg","mis":"M3-2-u5-X10"}],"explanation":["쓰레기통을 아는 들이와 견주어 보아요.","들이에 쓰는 단위는 mL·L이에요.","쓰레기통의 들이는 약 20 L예요."]},{"stem":"국자의 들이는 약 100 ○예요. ○에 알맞은 단위는 어느 것인가요?","options":[{"t":"mL","correct":true},{"t":"L","mis":"M3-2-u5-X09"},{"t":"g","mis":"M3-2-u5-X10"},{"t":"kg","mis":"M3-2-u5-X10"}],"explanation":["국자를 아는 들이와 견주어 보아요.","들이에 쓰는 단위는 mL·L이에요.","국자의 들이는 약 100 mL예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_challenge#2','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',2,'mc','auto','수조에 물을 담았어요. 수조의 눈금은 L로 되어 있어요. 수조의 2 L와 4 L 사이가 똑같이 2칸으로 나뉘어 있고, 물이 2 L에서 1칸 더 간 눈금까지 올라와 있어요. 얼마인가요?',ARRAY['M3-2-u5-X07']::text[],false,'{"seq":2,"concept":"M3-2-u5-C3","difficulty":2,"kind":"mc","stem":"수조에 물을 담았어요. 수조의 눈금은 L로 되어 있어요. 수조의 2 L와 4 L 사이가 똑같이 2칸으로 나뉘어 있고, 물이 2 L에서 1칸 더 간 눈금까지 올라와 있어요. 얼마인가요?","options":[{"t":"3 L","correct":true},{"t":"4 L","mis":"M3-2-u5-X07"},{"t":"2 L","mis":"M3-2-u5-X07"},{"t":"2 L 500 mL","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 2 L~4 L 사이 2칸 → 2000 ÷ 2 = 1000, 한 칸은 1000 mL예요.","2 L에서 1칸 더 → 2000 + 1000 × 1 = 3000.","3 L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_challenge#3','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',3,'mc','auto','주스병의 들이를 어림했어요. 가장 알맞게 어림한 친구는 누구인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X05','M3-2-u5-X21']::text[],false,'{"seq":3,"concept":"M3-2-u5-C3","difficulty":3,"kind":"mc","stem":"주스병의 들이를 어림했어요. 가장 알맞게 어림한 친구는 누구인가요?","options":[{"t":"민준","correct":true},{"t":"지아","mis":"M3-2-u5-X09"},{"t":"정후","mis":"M3-2-u5-X05"},{"t":"모두 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["지아 — 500 mL 우유갑 2개는 1000 mL = 1 L예요. 100 L는 단위가 맞지 않아요.","정후 — 500 mL와 1 L를 합하면 1 L 500 mL예요. 15 L가 아니에요.","민준 — 1 L보다 약간 적어 약 950 mL — 가장 알맞게 어림했어요."],"asset":{"type":"speech","turns":[{"who":"지아","text":"500 mL 우유갑이 2개 있는 들이와 비슷해서 약 100 L야."},{"who":"민준","text":"1 L 우유갑보다 약간 적을 것 같아서 약 950 mL야."},{"who":"정후","text":"500 mL 우유갑 1개와 1 L 우유갑 1개를 합한 들이와 비슷할 것 같아서 약 15 L야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_challenge#4','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',3,'ox','auto','양치 컵의 들이를 약 200 mL로 어림하고 재어 보니 180 mL였어요. 친구가 「어림한 값과 잰 값이 다르니까 어림을 잘못한 거야.」라고 말했어요. 바르게 말했어요.',ARRAY['M3-2-u5-X08']::text[],true,'{"seq":4,"concept":"M3-2-u5-C3","difficulty":3,"kind":"ox","stem":"양치 컵의 들이를 약 200 mL로 어림하고 재어 보니 180 mL였어요. 친구가 「어림한 값과 잰 값이 다르니까 어림을 잘못한 거야.」라고 말했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"어림은 아는 들이와 견주어 얼마쯤인지 나타낸 것이라 잰 값과 달라도 돼서","correct":true},{"t":"어림한 값은 잰 값과 꼭 같아야 해서","mis":"M3-2-u5-X08"}],"mis":"M3-2-u5-X08","explanation":["어림은 재기 전에 아는 들이와 견주어 얼마쯤인지 생각하는 거예요.","약 200 mL와 180 mL의 차는 20 mL예요.","달라도 괜찮아요 — 어림의 근거가 타당한지가 중요해요. 바르지 않아요."],"variant_rule":{"alt":[{"stem":"국그릇의 들이를 약 400 mL로 어림하고 재어 보니 500 mL였어요. 친구가 「어림한 값과 잰 값이 다르니까 어림을 잘못한 거야.」라고 말했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"어림은 아는 들이와 견주어 얼마쯤인지 나타낸 것이라 잰 값과 달라도 돼서","correct":true},{"t":"어림한 값은 잰 값과 꼭 같아야 해서","mis":"M3-2-u5-X08"}],"explanation":["어림은 재기 전에 아는 들이와 견주어 얼마쯤인지 생각하는 거예요.","약 400 mL와 500 mL의 차는 100 mL예요.","달라도 괜찮아요 — 어림의 근거가 타당한지가 중요해요. 바르지 않아요."]},{"stem":"찻잔의 들이를 약 200 mL로 어림하고 재어 보니 250 mL였어요. 친구가 「어림한 값과 잰 값이 다르니까 어림을 잘못한 거야.」라고 말했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"어림은 아는 들이와 견주어 얼마쯤인지 나타낸 것이라 잰 값과 달라도 돼서","correct":true},{"t":"어림한 값은 잰 값과 꼭 같아야 해서","mis":"M3-2-u5-X08"}],"explanation":["어림은 재기 전에 아는 들이와 견주어 얼마쯤인지 생각하는 거예요.","약 200 mL와 250 mL의 차는 50 mL예요.","달라도 괜찮아요 — 어림의 근거가 타당한지가 중요해요. 바르지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_challenge#5','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',3,'mc','auto','물건의 들이를 어림하고 재어 보았어요. 양치 컵은 약 200 mL로 어림하고 180 mL로 재었고, 찻잔은 약 200 mL로 어림하고 250 mL로 재었고, 국그릇은 약 400 mL로 어림하고 500 mL로 재었어요. 어림한 들이와 잰 들이의 차가 가장 작은 물건은 어느 것인가요?',ARRAY['M3-2-u5-X21']::text[],false,'{"seq":5,"concept":"M3-2-u5-C3","difficulty":3,"kind":"mc","stem":"물건의 들이를 어림하고 재어 보았어요. 양치 컵은 약 200 mL로 어림하고 180 mL로 재었고, 찻잔은 약 200 mL로 어림하고 250 mL로 재었고, 국그릇은 약 400 mL로 어림하고 500 mL로 재었어요. 어림한 들이와 잰 들이의 차가 가장 작은 물건은 어느 것인가요?","options":[{"t":"양치 컵","correct":true},{"t":"찻잔","mis":"M3-2-u5-X21"},{"t":"국그릇","mis":"M3-2-u5-X21"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["어림한 들이와 잰 들이의 차를 구해요.","양치 컵 200 − 180 = 20, 찻잔 250 − 200 = 50, 국그릇 500 − 400 = 100.","차가 가장 작은 양치 컵을 가장 가깝게 어림했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_challenge#6','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',3,'sa','auto','컵의 들이가 약 400 mL 정도 된다고 생각하여 물 100 mL를 어림하여 컵에 담았어요. 재어 보니 120 mL였어요. 100 mL보다 몇 mL 더 담았나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u5-C3","difficulty":3,"kind":"sa","stem":"컵의 들이가 약 400 mL 정도 된다고 생각하여 물 100 mL를 어림하여 컵에 담았어요. 재어 보니 120 mL였어요. 100 mL보다 몇 mL 더 담았나요? 숫자로 쓰세요.","answer":["20"],"explanation":["어림하여 담은 물을 측정도구로 재어 확인했어요.","120 mL − 100 mL = 20 mL.","100 mL보다 20 mL 더 담았어요 — 양감을 기르는 활동이에요."],"variant_rule":{"alt":[{"stem":"컵의 들이가 약 300 mL 정도 된다고 생각하여 물 300 mL를 어림하여 컵에 가득 담았어요. 재어 보니 330 mL였어요. 300 mL보다 몇 mL 더 담았나요? 숫자로 쓰세요.","answer":["30"],"explanation":["어림하여 담은 물을 측정도구로 재어 확인했어요.","330 mL − 300 mL = 30 mL.","300 mL보다 30 mL 더 담았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_challenge#7','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',3,'mc','auto','서준이가 다회용 컵의 들이를 어림해요. 들이를 알고 있는 물건 두 가지를 합하여 어림한 말은 어느 것인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X08']::text[],false,'{"seq":7,"concept":"M3-2-u5-C3","difficulty":3,"kind":"mc","stem":"서준이가 다회용 컵의 들이를 어림해요. 들이를 알고 있는 물건 두 가지를 합하여 어림한 말은 어느 것인가요?","options":[{"t":"「500 mL와 200 mL를 합한 양과 비슷할 것 같아.」","correct":true},{"t":"「1 L보다 적을 것 같아.」","mis":"M3-2-u5-X20"},{"t":"「200 mL로 몇 번쯤 들어갈까?」","mis":"M3-2-u5-X20"},{"t":"「눈으로 보니 아주 많을 것 같아.」","mis":"M3-2-u5-X08"}],"explanation":["「1 L보다 적을 것 같아」는 아는 들이 하나와 견주는 방법이에요.","「200 mL로 몇 번쯤」은 아는 들이가 몇 번 들어가는지 세는 방법이에요.","두 들이를 합하여 견준 말은 「500 mL와 200 mL를 합한 양과 비슷할 것 같아」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_challenge#8','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',4,'essay','teacher','두 친구가 주전자의 들이를 어림했어요. 한 친구는 「주전자에 물을 가득 채우려면 가득 찬 2 L짜리 우유갑이 1개 정도 필요하다고 생각해서 약 2 L라고 어림했어.」라고 했고, 다른 친구는 「눈으로 보기에 약 2 L일 것 같아.」라고 했어요. 어느 설명이 더 좋은지 고르고 까닭을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u5-C3","difficulty":4,"kind":"essay","stem":"두 친구가 주전자의 들이를 어림했어요. 한 친구는 「주전자에 물을 가득 채우려면 가득 찬 2 L짜리 우유갑이 1개 정도 필요하다고 생각해서 약 2 L라고 어림했어.」라고 했고, 다른 친구는 「눈으로 보기에 약 2 L일 것 같아.」라고 했어요. 어느 설명이 더 좋은지 고르고 까닭을 써 보세요.","answer_guide":{"answer":"예: 첫째 친구의 설명이 더 좋다. 들이를 알고 있는 2 L짜리 우유갑과 견주어 어림한 근거를 밝혔기 때문이다. 어림은 값이 정확한지보다 아는 들이와 견주는 등 근거가 타당한지가 중요하다.","scoring_points":["첫째 친구의 설명을 골랐는가","들이를 아는 물건(2 L 우유갑)과 견주었다는 근거를 들었는가","어림은 근거가 중요하다고 썼는가"]},"explanation":["두 친구 모두 약 2 L로 어림했어요.","첫째 친구는 2 L 우유갑이라는 기준과 견주었어요.","어림한 방법을 구체적으로 말하면 다른 사람도 믿을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_challenge#9','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',4,'essay','teacher','정후는 주스병의 들이를 「500 mL 우유갑 1개와 1 L 우유갑 1개를 합한 들이와 비슷할 것 같아서 약 15 L야.」라고 어림했어요. 잘못된 곳을 찾아 바르게 고쳐 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u5-C3","difficulty":4,"kind":"essay","stem":"정후는 주스병의 들이를 「500 mL 우유갑 1개와 1 L 우유갑 1개를 합한 들이와 비슷할 것 같아서 약 15 L야.」라고 어림했어요. 잘못된 곳을 찾아 바르게 고쳐 보세요.","answer_guide":{"answer":"예: 500 mL와 1 L를 합하면 1 L 500 mL인데 15 L라고 잘못 나타냈다. 1 L 500 mL는 1500 mL이므로 「약 1 L 500 mL야」 또는 「약 1500 mL야」라고 고쳐야 한다.","scoring_points":["500 mL와 1 L의 합을 1 L 500 mL로 구했는가","15 L가 잘못이라고 썼는가","약 1 L 500 mL(약 1500 mL)로 고쳤는가"]},"explanation":["1 L + 500 mL = 1 L 500 mL.","1 L 500 mL = 1500 mL — 15 L가 아니에요.","「약 1 L 500 mL」로 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L03_challenge#10','math',3,2,'u5','L03','tb_g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',4,'essay','teacher','서준이는 다회용 컵의 들이가 궁금해졌어요. 컵의 들이를 어림하는 방법 세 가지를 들이를 알고 있는 물건을 이용하여 설명하고, 어림한 들이는 어떻게 나타내는지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u5-C3","difficulty":4,"kind":"essay","stem":"서준이는 다회용 컵의 들이가 궁금해졌어요. 컵의 들이를 어림하는 방법 세 가지를 들이를 알고 있는 물건을 이용하여 설명하고, 어림한 들이는 어떻게 나타내는지 써 보세요.","answer_guide":{"answer":"예: ① 들이가 1 L인 우유갑과 견주어 1 L보다 적을 것 같다고 어림한다. ② 들이가 200 mL인 우유갑으로 몇 번쯤 들어갈지 생각하여 어림한다. ③ 500 mL와 200 mL 우유갑을 합한 양과 비슷한지 생각하여 어림한다. 어림한 들이는 앞에 「약」을 붙여 나타낸다.","scoring_points":["아는 들이와 견주는 방법을 썼는가","아는 들이가 몇 번 들어가는지로 어림하는 방법을 썼는가","두 들이를 합하여 어림하는 방법과 「약」을 붙이는 것을 썼는가"]},"explanation":["견주기 — 1 L보다 적을 것 같아.","몇 번 — 200 mL로 몇 번쯤 들어갈까?","합하기 — 500 mL와 200 mL를 합한 양과 비슷할 것 같아. 어림한 값에는 「약」을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_basic#1','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',1,'sa','auto','1 L 300 mL + 2 L 500 mL의 세로셈이에요. mL 자리의 ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u5-C4","difficulty":1,"kind":"sa","stem":"1 L 300 mL + 2 L 500 mL의 세로셈이에요. mL 자리의 ?에 알맞은 수를 쓰세요.","answer":["800"],"explanation":["같은 단위의 수끼리 계산해요.","mL끼리 300 + 500 = 800, L끼리 1 + 2 = 3.","1 L 300 mL + 2 L 500 mL = 3 L 800 mL."],"asset":{"type":"expr_grid","rows":[["","1","L","300","mL"],["+","2","L","500","mL"],["","3","L",null,"mL"]]},"variant_rule":{"alt":[{"stem":"3 L 200 mL + 2 L 500 mL의 세로셈이에요. mL 자리의 ?에 알맞은 수를 쓰세요.","answer":["700"],"explanation":["같은 단위의 수끼리 계산해요.","mL끼리 200 + 500 = 700, L끼리 3 + 2 = 5.","3 L 200 mL + 2 L 500 mL = 5 L 700 mL."],"asset":{"type":"expr_grid","rows":[["","3","L","200","mL"],["+","2","L","500","mL"],["","5","L",null,"mL"]]}},{"stem":"4 L 200 mL + 2 L 500 mL의 세로셈이에요. mL 자리의 ?에 알맞은 수를 쓰세요.","answer":["700"],"explanation":["같은 단위의 수끼리 계산해요.","mL끼리 200 + 500 = 700, L끼리 4 + 2 = 6.","4 L 200 mL + 2 L 500 mL = 6 L 700 mL."],"asset":{"type":"expr_grid","rows":[["","4","L","200","mL"],["+","2","L","500","mL"],["","6","L",null,"mL"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_basic#2','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',1,'sa','auto','2 L 700 mL − 1 L 100 mL의 세로셈이에요. L 자리의 ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C4","difficulty":1,"kind":"sa","stem":"2 L 700 mL − 1 L 100 mL의 세로셈이에요. L 자리의 ?에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["같은 단위의 수끼리 계산해요.","mL끼리 700 − 100 = 600, L끼리 2 − 1 = 1.","2 L 700 mL − 1 L 100 mL = 1 L 600 mL."],"asset":{"type":"expr_grid","rows":[["","2","L","700","mL"],["−","1","L","100","mL"],["",null,"L","600","mL"]]},"variant_rule":{"alt":[{"stem":"8 L 900 mL − 4 L 400 mL의 세로셈이에요. L 자리의 ?에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["같은 단위의 수끼리 계산해요.","mL끼리 900 − 400 = 500, L끼리 8 − 4 = 4.","8 L 900 mL − 4 L 400 mL = 4 L 500 mL."],"asset":{"type":"expr_grid","rows":[["","8","L","900","mL"],["−","4","L","400","mL"],["",null,"L","500","mL"]]}},{"stem":"8 L 600 mL − 3 L 200 mL의 세로셈이에요. L 자리의 ?에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["같은 단위의 수끼리 계산해요.","mL끼리 600 − 200 = 400, L끼리 8 − 3 = 5.","8 L 600 mL − 3 L 200 mL = 5 L 400 mL."],"asset":{"type":"expr_grid","rows":[["","8","L","600","mL"],["−","3","L","200","mL"],["",null,"L","400","mL"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_basic#3','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',1,'mc','auto','계산해 보세요. 3 L 100 mL + 4 L 800 mL',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],true,'{"seq":3,"concept":"M3-2-u5-C4","difficulty":1,"kind":"mc","stem":"계산해 보세요. 3 L 100 mL + 4 L 800 mL","options":[{"t":"7 L 900 mL","correct":true},{"t":"1 L 700 mL","mis":"M3-2-u5-X14"},{"t":"8 L","mis":"M3-2-u5-X24"},{"t":"7 L 800 mL","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","mL끼리 100 + 800 = 900, L끼리 3 + 4 = 7.","3 L 100 mL + 4 L 800 mL = 7 L 900 mL."],"variant_rule":{"alt":[{"stem":"계산해 보세요. 7 L 100 mL + 1 L 600 mL","options":[{"t":"8 L 700 mL","correct":true},{"t":"5 L 500 mL","mis":"M3-2-u5-X14"},{"t":"8 L 800 mL","mis":"M3-2-u5-X24"},{"t":"8 L 600 mL","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","mL끼리 100 + 600 = 700, L끼리 7 + 1 = 8.","7 L 100 mL + 1 L 600 mL = 8 L 700 mL."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_basic#4','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',1,'mc','auto','계산해 보세요. 5 L 900 mL − 3 L 300 mL',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],true,'{"seq":4,"concept":"M3-2-u5-C4","difficulty":1,"kind":"mc","stem":"계산해 보세요. 5 L 900 mL − 3 L 300 mL","options":[{"t":"2 L 600 mL","correct":true},{"t":"9 L 200 mL","mis":"M3-2-u5-X14"},{"t":"2 L 700 mL","mis":"M3-2-u5-X24"},{"t":"2 L 500 mL","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","mL끼리 900 − 300 = 600, L끼리 5 − 3 = 2.","5 L 900 mL − 3 L 300 mL = 2 L 600 mL."],"variant_rule":{"alt":[{"stem":"계산해 보세요. 6 L 800 mL − 3 L 300 mL","options":[{"t":"3 L 500 mL","correct":true},{"t":"10 L 100 mL","mis":"M3-2-u5-X14"},{"t":"3 L 600 mL","mis":"M3-2-u5-X24"},{"t":"3 L 400 mL","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","mL끼리 800 − 300 = 500, L끼리 6 − 3 = 3.","6 L 800 mL − 3 L 300 mL = 3 L 500 mL."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_basic#5','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',2,'mc','auto','친환경 세제가 1 L 300 mL 들어 있는 통에 친환경 세제를 2 L 500 mL 더 넣었더니 가득 찼어요. 친환경 세제 통의 들이는 얼마인가요?',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],true,'{"seq":5,"concept":"M3-2-u5-C4","difficulty":2,"kind":"mc","stem":"친환경 세제가 1 L 300 mL 들어 있는 통에 친환경 세제를 2 L 500 mL 더 넣었더니 가득 찼어요. 친환경 세제 통의 들이는 얼마인가요?","options":[{"t":"3 L 800 mL","correct":true},{"t":"1 L 200 mL","mis":"M3-2-u5-X14"},{"t":"3 L 900 mL","mis":"M3-2-u5-X24"},{"t":"3 L 700 mL","mis":"M3-2-u5-X24"}],"explanation":["원래 들어 있던 양에 더 넣은 양을 더해요 — 식은 1 L 300 mL + 2 L 500 mL.","mL끼리 300 + 500 = 800, L끼리 1 + 2 = 3.","1 L 300 mL + 2 L 500 mL = 3 L 800 mL — 세제 통의 들이는 3 L 800 mL예요."],"variant_rule":{"alt":[{"stem":"친환경 세제가 500 mL 들어 있는 통에 세제를 1 L 400 mL 더 넣었더니 통이 가득 찼어요. 세제 통의 들이는 얼마인가요?","options":[{"t":"1 L 900 mL","correct":true},{"t":"6 L 400 mL","mis":"M3-2-u5-X11"},{"t":"900 mL","mis":"M3-2-u5-X14"},{"t":"2 L","mis":"M3-2-u5-X24"}],"explanation":["원래 들어 있던 양에 더 넣은 양을 더해요 — 식은 500 mL + 1 L 400 mL.","mL끼리 500 + 400 = 900, L끼리 0 + 1 = 1.","500 mL + 1 L 400 mL = 1 L 900 mL — 세제 통의 들이는 1 L 900 mL예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_basic#6','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',2,'mc','auto','동연이는 주전자에 가득 담긴 물 2 L 700 mL 중에서 1 L 100 mL를 사용했어요. 남은 물의 양은 얼마인가요?',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],true,'{"seq":6,"concept":"M3-2-u5-C4","difficulty":2,"kind":"mc","stem":"동연이는 주전자에 가득 담긴 물 2 L 700 mL 중에서 1 L 100 mL를 사용했어요. 남은 물의 양은 얼마인가요?","options":[{"t":"1 L 600 mL","correct":true},{"t":"3 L 800 mL","mis":"M3-2-u5-X14"},{"t":"1 L 700 mL","mis":"M3-2-u5-X24"},{"t":"1 L 500 mL","mis":"M3-2-u5-X24"}],"explanation":["처음에 있던 물의 양에서 사용한 물의 양을 빼요 — 식은 2 L 700 mL − 1 L 100 mL.","mL끼리 700 − 100 = 600, L끼리 2 − 1 = 1.","2 L 700 mL − 1 L 100 mL = 1 L 600 mL — 남은 물은 1 L 600 mL예요."],"variant_rule":{"alt":[{"stem":"지아는 우유 2 L 550 mL 중에서 300 mL를 마셨어요. 지아가 마시고 남은 우유의 양은 얼마인가요?","options":[{"t":"2 L 250 mL","correct":true},{"t":"2 L 520 mL","mis":"M3-2-u5-X11"},{"t":"2 L 850 mL","mis":"M3-2-u5-X14"},{"t":"2 L 350 mL","mis":"M3-2-u5-X24"}],"explanation":["처음 우유의 양에서 마신 양을 빼요 — 식은 2 L 550 mL − 300 mL.","mL끼리 550 − 300 = 250, L끼리 2 − 0 = 2.","2 L 550 mL − 300 mL = 2 L 250 mL — 남은 우유는 2 L 250 mL예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_basic#7','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',2,'mc','auto','동연이는 주전자에 가득 담긴 물 2 L 700 mL 중에서 1 L 100 mL를 사용했어요. 남은 물의 양을 구하는 식은 어느 것인가요?',ARRAY['M3-2-u5-X14','M3-2-u5-X11']::text[],false,'{"seq":7,"concept":"M3-2-u5-C4","difficulty":2,"kind":"mc","stem":"동연이는 주전자에 가득 담긴 물 2 L 700 mL 중에서 1 L 100 mL를 사용했어요. 남은 물의 양을 구하는 식은 어느 것인가요?","options":[{"t":"2 L 700 mL − 1 L 100 mL","correct":true},{"t":"2 L 700 mL + 1 L 100 mL","mis":"M3-2-u5-X14"},{"t":"1 L 100 mL + 2 L 700 mL","mis":"M3-2-u5-X14"},{"t":"2 L − 1 L","mis":"M3-2-u5-X11"}],"explanation":["처음에 있던 물의 양에서 사용한 물의 양을 빼요.","식은 2 L 700 mL − 1 L 100 mL.","2 L 700 mL − 1 L 100 mL = 1 L 600 mL — 남은 물은 1 L 600 mL예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_basic#8','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',2,'sa','auto','민준이는 식혜를 1 L 300 mL 샀고, 서윤이는 식혜를 1 L 150 mL 샀어요. 민준이와 서윤이가 산 식혜의 양은 모두 2 L □ mL예요. □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u5-C4","difficulty":2,"kind":"sa","stem":"민준이는 식혜를 1 L 300 mL 샀고, 서윤이는 식혜를 1 L 150 mL 샀어요. 민준이와 서윤이가 산 식혜의 양은 모두 2 L □ mL예요. □ 안에 알맞은 수를 쓰세요.","answer":["450"],"explanation":["두 사람이 산 양을 더해요 — 식은 1 L 300 mL + 1 L 150 mL.","mL끼리 300 + 150 = 450, L끼리 1 + 1 = 2.","1 L 300 mL + 1 L 150 mL = 2 L 450 mL — 식혜는 모두 2 L 450 mL예요."],"variant_rule":{"alt":[{"stem":"수지가 가지고 있는 병의 들이는 1 L 500 mL, 남주가 가지고 있는 병의 들이는 1 L 300 mL예요. 두 병에 주스가 가득 담겨 있어요. 수지와 남주가 가지고 있는 주스의 양은 모두 2 L □ mL예요. □ 안에 알맞은 수를 쓰세요.","answer":["800"],"explanation":["두 병의 주스 양을 더해요 — 식은 1 L 500 mL + 1 L 300 mL.","mL끼리 500 + 300 = 800, L끼리 1 + 1 = 2.","1 L 500 mL + 1 L 300 mL = 2 L 800 mL — 주스는 모두 2 L 800 mL예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_basic#9','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',2,'sa','auto','은비가 심부름으로 사 온 간장병의 들이는 1 L 300 mL, 주스병의 들이는 1 L 400 mL예요. 간장병과 주스병의 들이의 차는 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u5-C4","difficulty":2,"kind":"sa","stem":"은비가 심부름으로 사 온 간장병의 들이는 1 L 300 mL, 주스병의 들이는 1 L 400 mL예요. 간장병과 주스병의 들이의 차는 몇 mL인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["큰 들이에서 작은 들이를 빼요 — 식은 1 L 400 mL − 1 L 300 mL.","mL끼리 400 − 300 = 100, L끼리 1 − 1 = 0.","1 L 400 mL − 1 L 300 mL = 100 mL — 들이의 차는 100 mL예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_basic#10','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',3,'error','auto','은비가 사 온 간장병(1 L 300 mL)과 주스병(1 L 400 mL)의 들이의 합을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u5-X24','M3-2-u5-X20']::text[],false,'{"seq":10,"concept":"M3-2-u5-C4","difficulty":3,"kind":"error","stem":"은비가 사 온 간장병(1 L 300 mL)과 주스병(1 L 400 mL)의 들이의 합을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"동연 — 「1 L 300 mL + 1 L 400 mL = 2 L 800 mL야」","correct":true,"mis_target":"M3-2-u5-X24"},{"t":"민준 — 「mL끼리 300 + 400 = 700이야」","mis":"M3-2-u5-X20"},{"t":"서윤 — 「L끼리 1 + 1 = 2야」","mis":"M3-2-u5-X20"},{"t":"지아 — 「들이의 합은 2 L 700 mL야」","mis":"M3-2-u5-X20"}],"explanation":["mL끼리 300 + 400 = 700, L끼리 1 + 1 = 2.","1 L 300 mL + 1 L 400 mL = 2 L 700 mL.","동연이는 식은 바르게 세웠지만 mL끼리의 셈이 틀렸어요 — 같은 단위의 수끼리 따로 셈해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_challenge#1','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',2,'sa','auto','친환경 세제가 500 mL 들어 있는 통에 세제를 1 L 400 mL만큼 더 넣어 통을 가득 채우려고 해요. 세제 통의 들이는 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M3-2-u5-C4","difficulty":2,"kind":"sa","stem":"친환경 세제가 500 mL 들어 있는 통에 세제를 1 L 400 mL만큼 더 넣어 통을 가득 채우려고 해요. 세제 통의 들이는 몇 mL인가요? 숫자로 쓰세요.","answer":["1900"],"explanation":["세제 통의 들이를 구하는 식은 500 mL + 1 L 400 mL예요.","mL끼리 500 + 400 = 900, L끼리 0 + 1 = 1.","500 mL + 1 L 400 mL = 1 L 900 mL = 1900 mL."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_challenge#2','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',2,'mc','auto','계산해 보세요. 8 L 600 mL − 3 L 200 mL',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],true,'{"seq":2,"concept":"M3-2-u5-C4","difficulty":2,"kind":"mc","stem":"계산해 보세요. 8 L 600 mL − 3 L 200 mL","options":[{"t":"5 L 400 mL","correct":true},{"t":"11 L 800 mL","mis":"M3-2-u5-X14"},{"t":"5 L 500 mL","mis":"M3-2-u5-X24"},{"t":"5 L 300 mL","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","mL끼리 600 − 200 = 400, L끼리 8 − 3 = 5.","8 L 600 mL − 3 L 200 mL = 5 L 400 mL."],"variant_rule":{"alt":[{"stem":"계산해 보세요. 4 L 200 mL + 2 L 500 mL","options":[{"t":"6 L 700 mL","correct":true},{"t":"1 L 700 mL","mis":"M3-2-u5-X14"},{"t":"6 L 800 mL","mis":"M3-2-u5-X24"},{"t":"6 L 600 mL","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","mL끼리 200 + 500 = 700, L끼리 4 + 2 = 6.","4 L 200 mL + 2 L 500 mL = 6 L 700 mL."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_challenge#3','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',3,'sa','auto','들이가 1 L 200 mL인 물병과 250 mL인 컵에 물이 가득 담겨 있었어요. 이 물을 빈 주전자에 모두 부었더니 400 mL가 넘쳤어요. 주전자의 들이는 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u5-C4","difficulty":3,"kind":"sa","stem":"들이가 1 L 200 mL인 물병과 250 mL인 컵에 물이 가득 담겨 있었어요. 이 물을 빈 주전자에 모두 부었더니 400 mL가 넘쳤어요. 주전자의 들이는 몇 mL인가요? 숫자로 쓰세요.","answer":["1050"],"explanation":["물병과 컵의 들이는 1 L 200 mL + 250 mL = 1 L 450 mL예요.","400 mL가 넘쳤으니 주전자에는 1 L 450 mL − 400 mL = 1 L 50 mL가 담겼어요.","주전자의 들이는 1 L 50 mL = 1050 mL예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_challenge#4','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',3,'mc','auto','물통의 들이는 1 L 900 mL예요. 병 가는 1 L 300 mL, 나는 500 mL, 다는 300 mL, 라는 400 mL예요. 서로 다른 병 2개에 물을 가득 채워 빈 물통에 모두 부었더니, 물통에 물을 100 mL 더 채울 수 있었어요. 고른 병 2개는 어느 것인가요?',ARRAY['M3-2-u5-X24','M3-2-u5-X18']::text[],false,'{"seq":4,"concept":"M3-2-u5-C4","difficulty":3,"kind":"mc","stem":"물통의 들이는 1 L 900 mL예요. 병 가는 1 L 300 mL, 나는 500 mL, 다는 300 mL, 라는 400 mL예요. 서로 다른 병 2개에 물을 가득 채워 빈 물통에 모두 부었더니, 물통에 물을 100 mL 더 채울 수 있었어요. 고른 병 2개는 어느 것인가요?","options":[{"t":"가, 나","correct":true},{"t":"가, 라","mis":"M3-2-u5-X24"},{"t":"가, 다","mis":"M3-2-u5-X24"},{"t":"나, 라","mis":"M3-2-u5-X18"}],"explanation":["두 병의 들이를 더하고, 1 L 900 mL에서 빼 보아요.","가와 나: 1 L 300 mL + 500 mL = 1 L 800 mL, 1 L 900 mL − 1 L 800 mL = 100 mL.","가와 라는 200 mL, 가와 다는 300 mL가 남아요 — 고른 병은 가, 나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_challenge#5','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',3,'sa','auto','은비가 심부름으로 사 온 간장병의 들이는 1 L 300 mL, 주스병의 들이는 1 L 400 mL예요. 간장병과 주스병의 들이의 합은 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u5-C4","difficulty":3,"kind":"sa","stem":"은비가 심부름으로 사 온 간장병의 들이는 1 L 300 mL, 주스병의 들이는 1 L 400 mL예요. 간장병과 주스병의 들이의 합은 몇 mL인가요? 숫자로 쓰세요.","answer":["2700"],"explanation":["두 병의 들이를 더해요 — 식은 1 L 300 mL + 1 L 400 mL.","mL끼리 300 + 400 = 700, L끼리 1 + 1 = 2.","1 L 300 mL + 1 L 400 mL = 2 L 700 mL — 들이의 합은 2 L 700 mL예요."],"variant_rule":{"alt":[{"stem":"민준이는 식혜를 1 L 300 mL 샀고, 서윤이는 식혜를 1 L 150 mL 샀어요. 민준이와 서윤이가 산 식혜의 양은 모두 몇 mL인가요? 숫자로 쓰세요.","answer":["2450"],"explanation":["두 사람이 산 양을 더해요 — 식은 1 L 300 mL + 1 L 150 mL.","mL끼리 300 + 150 = 450, L끼리 1 + 1 = 2.","1 L 300 mL + 1 L 150 mL = 2 L 450 mL — 식혜는 모두 2 L 450 mL예요."]},{"stem":"수지가 가지고 있는 병의 들이는 1 L 500 mL, 남주가 가지고 있는 병의 들이는 1 L 300 mL예요. 두 병에 주스가 가득 담겨 있어요. 수지와 남주가 가지고 있는 주스의 양은 모두 몇 mL인가요? 숫자로 쓰세요.","answer":["2800"],"explanation":["두 병의 주스 양을 더해요 — 식은 1 L 500 mL + 1 L 300 mL.","mL끼리 500 + 300 = 800, L끼리 1 + 1 = 2.","1 L 500 mL + 1 L 300 mL = 2 L 800 mL — 주스는 모두 2 L 800 mL예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_challenge#6','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',3,'ox','auto','1 L 300 mL + 2 L 500 mL를 계산할 때 L 단위의 수끼리, mL 단위의 수끼리 더해요.',ARRAY['M3-2-u5-X11']::text[],true,'{"seq":6,"concept":"M3-2-u5-C4","difficulty":3,"kind":"ox","stem":"1 L 300 mL + 2 L 500 mL를 계산할 때 L 단위의 수끼리, mL 단위의 수끼리 더해요.","answer":"O","reason_options":[{"t":"같은 단위의 수끼리 계산해야 해서","correct":true},{"t":"단위와 상관없이 앞의 수부터 모두 더하면 되어서","mis":"M3-2-u5-X11"}],"mis":"M3-2-u5-X11","explanation":["L는 L끼리, mL는 mL끼리 더해요.","mL끼리 300 + 500 = 800, L끼리 1 + 2 = 3.","1 L 300 mL + 2 L 500 mL = 3 L 800 mL — 맞아요."],"variant_rule":{"alt":[{"stem":"2 L 700 mL − 1 L 100 mL를 계산할 때 mL 단위의 수끼리 빼고, L 단위의 수끼리 빼요.","answer":"O","reason_options":[{"t":"같은 단위의 수끼리 계산해야 해서","correct":true},{"t":"단위와 상관없이 앞의 수부터 모두 빼면 되어서","mis":"M3-2-u5-X11"}],"explanation":["mL는 mL끼리, L는 L끼리 빼요.","mL끼리 700 − 100 = 600, L끼리 2 − 1 = 1.","2 L 700 mL − 1 L 100 mL = 1 L 600 mL — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_challenge#7','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',3,'mc','auto','들이의 뺄셈으로 구해야 하는 것은 어느 것인가요?',ARRAY['M3-2-u5-X14']::text[],false,'{"seq":7,"concept":"M3-2-u5-C4","difficulty":3,"kind":"mc","stem":"들이의 뺄셈으로 구해야 하는 것은 어느 것인가요?","options":[{"t":"동연이가 주전자의 물 2 L 700 mL 중에서 1 L 100 mL를 사용하고 남은 물의 양","correct":true},{"t":"세제 1 L 300 mL가 든 통에 2 L 500 mL를 더 넣은 세제의 양","mis":"M3-2-u5-X14"},{"t":"민준이와 서윤이가 산 식혜를 모두 합한 양","mis":"M3-2-u5-X14"},{"t":"수지와 남주가 가지고 있는 주스를 모두 합한 양","mis":"M3-2-u5-X14"}],"explanation":["「남은 양」은 처음 양에서 쓴 양을 빼서 구해요.","「더 넣은 양」·「모두 합한 양」은 덧셈으로 구해요.","뺄셈 — 2 L 700 mL − 1 L 100 mL = 1 L 600 mL."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_challenge#8','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',4,'essay','teacher','들이가 1 L 200 mL인 물병과 250 mL인 컵에 물이 가득 담겨 있었어요. 이 물을 빈 주전자에 모두 부었더니 400 mL가 넘쳤어요. 주전자의 들이는 몇 L 몇 mL인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u5-C4","difficulty":4,"kind":"essay","stem":"들이가 1 L 200 mL인 물병과 250 mL인 컵에 물이 가득 담겨 있었어요. 이 물을 빈 주전자에 모두 부었더니 400 mL가 넘쳤어요. 주전자의 들이는 몇 L 몇 mL인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 물병과 컵의 들이는 1 L 200 mL + 250 mL = 1 L 450 mL이다. 400 mL가 넘쳤으므로 주전자의 들이는 1 L 450 mL − 400 mL = 1 L 50 mL이다. 답: 1 L 50 mL","scoring_points":["1 L 200 mL + 250 mL = 1 L 450 mL를 구했는가","넘친 400 mL를 빼야 한다고 했는가","1 L 50 mL를 구했는가"]},"explanation":["부은 물: 1 L 200 mL + 250 mL = 1 L 450 mL.","넘친 400 mL는 주전자에 담기지 못했어요.","1 L 450 mL − 400 mL = 1 L 50 mL."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_challenge#9','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',4,'essay','teacher','친구가 은비의 간장병(1 L 300 mL)과 주스병(1 L 400 mL)의 들이의 합을 「1 L 300 mL + 1 L 400 mL = 2 L 800 mL」라고 구했어요. 무엇이 잘못되었는지 찾아 바르게 계산하고, 계산이 맞는지 확인하는 방법도 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u5-C4","difficulty":4,"kind":"essay","stem":"친구가 은비의 간장병(1 L 300 mL)과 주스병(1 L 400 mL)의 들이의 합을 「1 L 300 mL + 1 L 400 mL = 2 L 800 mL」라고 구했어요. 무엇이 잘못되었는지 찾아 바르게 계산하고, 계산이 맞는지 확인하는 방법도 써 보세요.","answer_guide":{"answer":"예: 식은 바르게 세웠지만 mL끼리 300 + 400 = 700인데 800으로 잘못 계산했다. 바르게 계산하면 L끼리 1 + 1 = 2, mL끼리 300 + 400 = 700이므로 2 L 700 mL이다. 같은 단위의 수끼리 따로 다시 계산하거나, 2 L 700 mL − 1 L 400 mL = 1 L 300 mL로 확인할 수 있다.","scoring_points":["mL끼리의 셈이 틀렸다고 찾았는가","2 L 700 mL를 구했는가","같은 단위끼리 다시 계산하거나 뺄셈으로 확인했는가"]},"explanation":["mL끼리 300 + 400 = 700, L끼리 1 + 1 = 2.","1 L 300 mL + 1 L 400 mL = 2 L 700 mL.","2 L 700 mL − 1 L 400 mL = 1 L 300 mL로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L04_challenge#10','math',3,2,'u5','L04','tb_g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',4,'essay','teacher','물통의 들이는 1 L 900 mL예요. 병 가(1 L 300 mL), 나(500 mL), 다(300 mL), 라(400 mL) 가운데 서로 다른 2개를 골라 물을 가득 채워 빈 물통에 부으려고 해요. 병 2개를 골라 물을 모두 붓고 난 후 더 채울 수 있는 물의 양을 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u5-C4","difficulty":4,"kind":"essay","stem":"물통의 들이는 1 L 900 mL예요. 병 가(1 L 300 mL), 나(500 mL), 다(300 mL), 라(400 mL) 가운데 서로 다른 2개를 골라 물을 가득 채워 빈 물통에 부으려고 해요. 병 2개를 골라 물을 모두 붓고 난 후 더 채울 수 있는 물의 양을 구해 보세요.","answer_guide":{"answer":"예: 가와 나를 고르면 1 L 300 mL + 500 mL = 1 L 800 mL이고, 1 L 900 mL − 1 L 800 mL = 100 mL를 더 채울 수 있다. (가와 다 → 300 mL, 가와 라 → 200 mL, 나와 다 → 1 L 100 mL, 나와 라 → 1 L, 다와 라 → 1 L 200 mL)","scoring_points":["고른 두 병의 들이를 더했는가","1 L 900 mL에서 합을 뺐는가","고른 병에 맞는 더 채울 수 있는 양을 구했는가"]},"explanation":["두 병의 들이의 합을 덧셈으로 구해요.","물통의 들이에서 합을 빼요.","예: 가와 나 → 1 L 900 mL − 1 L 800 mL = 100 mL."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_basic#1','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',1,'mc','auto','빈 우유갑과 빈 페트병 가운데 더 무거운 것을 저금통으로 재활용하려고 해요. 양팔저울에 우유갑과 페트병을 올렸어요. 더 무거운 것은 어느 것인가요?',ARRAY['M3-2-u5-X15','M3-2-u5-X21']::text[],true,'{"seq":1,"concept":"M3-2-u5-C5","difficulty":1,"kind":"mc","stem":"빈 우유갑과 빈 페트병 가운데 더 무거운 것을 저금통으로 재활용하려고 해요. 양팔저울에 우유갑과 페트병을 올렸어요. 더 무거운 것은 어느 것인가요?","options":[{"t":"우유갑","correct":true},{"t":"페트병","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","우유갑 쪽이 내려갔어요 — 우유갑이 더 무거워요.","더 무거운 것은 우유갑이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"우유갑","icon":"🥛"},"r":{"name":"페트병","icon":"🍶"},"down":"l"}]},"variant_rule":{"alt":[{"stem":"양팔저울에 사과와 오렌지를 올렸어요. 더 무거운 것은 어느 것인가요?","options":[{"t":"사과","correct":true},{"t":"오렌지","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","사과 쪽이 내려갔어요 — 사과가 더 무거워요.","더 무거운 것은 사과예요."],"asset":{"type":"balance","scales":[{"l":{"name":"사과","icon":"🍎"},"r":{"name":"오렌지","icon":"🍊"},"down":"l"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_basic#2','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',1,'mc','auto','양팔저울에 당근과 고구마를 올렸어요. 더 가벼운 것은 어느 것인가요?',ARRAY['M3-2-u5-X15','M3-2-u5-X21']::text[],false,'{"seq":2,"concept":"M3-2-u5-C5","difficulty":1,"kind":"mc","stem":"양팔저울에 당근과 고구마를 올렸어요. 더 가벼운 것은 어느 것인가요?","options":[{"t":"당근","correct":true},{"t":"고구마","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","고구마 쪽이 내려갔어요 — 고구마가 더 무거워요.","더 가벼운 것은 당근이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"당근","icon":"🥕"},"r":{"name":"고구마","icon":"🍠"},"down":"r"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_basic#3','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',1,'mc','auto','양팔저울에 물건을 올려놓았을 때 더 무거운 물건은 어느 쪽에 있나요?',ARRAY['M3-2-u5-X15','M3-2-u5-X16','M3-2-u5-X21']::text[],false,'{"seq":3,"concept":"M3-2-u5-C5","difficulty":1,"kind":"mc","stem":"양팔저울에 물건을 올려놓았을 때 더 무거운 물건은 어느 쪽에 있나요?","options":[{"t":"아래로 내려간 쪽","correct":true},{"t":"위로 올라간 쪽","mis":"M3-2-u5-X15"},{"t":"크기가 더 큰 물건 쪽","mis":"M3-2-u5-X16"},{"t":"저울이 수평일 때만 알 수 있어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 무게를 견주는 도구예요.","무거운 쪽은 아래로 내려가고 가벼운 쪽은 위로 올라가요.","더 무거운 물건은 내려간 쪽에 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_basic#4','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',1,'sa','auto','양팔저울과 바둑돌을 사용하여 무게를 비교했어요. 키위의 무게는 바둑돌 20개, 감의 무게는 바둑돌 30개의 무게와 같아요. 감은 키위보다 바둑돌 몇 개만큼 더 무거운가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u5-C5","difficulty":1,"kind":"sa","stem":"양팔저울과 바둑돌을 사용하여 무게를 비교했어요. 키위의 무게는 바둑돌 20개, 감의 무게는 바둑돌 30개의 무게와 같아요. 감은 키위보다 바둑돌 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["10"],"explanation":["같은 바둑돌로 재었으니 개수로 견줄 수 있어요.","키위 20개, 감 30개 — 개수가 많을수록 더 무거워요.","30 − 20 = 10 — 바둑돌 10개만큼 더 무거워요."],"asset":{"type":"balance","scales":[{"l":{"name":"키위","icon":"🥝"},"r":{"name":"바둑돌 20개","icon":"⚫"},"down":"eq"},{"l":{"name":"감","icon":"🟠"},"r":{"name":"바둑돌 30개","icon":"⚫"},"down":"eq"}]},"variant_rule":{"alt":[{"stem":"양팔저울과 쌓기나무를 사용하여 무게를 비교했어요. 가위의 무게는 쌓기나무 10개, 풀의 무게는 쌓기나무 5개의 무게와 같아요. 가위는 풀보다 쌓기나무 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["5"],"explanation":["같은 쌓기나무로 재었으니 개수로 견줄 수 있어요.","가위 10개, 풀 5개 — 개수가 많을수록 더 무거워요.","10 − 5 = 5 — 쌓기나무 5개만큼 더 무거워요."],"asset":{"type":"balance","scales":[{"l":{"name":"가위","icon":"✂️"},"r":{"name":"쌓기나무 10개","icon":"🟫"},"down":"eq"},{"l":{"name":"풀","icon":"🧴"},"r":{"name":"쌓기나무 5개","icon":"🟫"},"down":"eq"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_basic#5','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',2,'mc','auto','양팔저울과 쌓기나무를 사용하여 지우개와 풀의 무게를 비교했어요. 지우개는 쌓기나무 7개, 풀은 쌓기나무 11개의 무게와 같아요. 바르게 말한 것은 어느 것인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X21','M3-2-u5-X14']::text[],false,'{"seq":5,"concept":"M3-2-u5-C5","difficulty":2,"kind":"mc","stem":"양팔저울과 쌓기나무를 사용하여 지우개와 풀의 무게를 비교했어요. 지우개는 쌓기나무 7개, 풀은 쌓기나무 11개의 무게와 같아요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"지우개는 풀보다 쌓기나무 4개만큼 더 가벼워요","correct":true},{"t":"지우개는 풀보다 쌓기나무 4개만큼 더 무거워요","mis":"M3-2-u5-X20"},{"t":"지우개는 풀보다 쌓기나무 11개만큼 더 가벼워요","mis":"M3-2-u5-X21"},{"t":"지우개는 풀보다 쌓기나무 18개만큼 더 가벼워요","mis":"M3-2-u5-X14"}],"explanation":["같은 쌓기나무로 재었으니 개수로 견줄 수 있어요.","지우개 7개, 풀 11개 — 개수가 적은 지우개가 더 가벼워요.","11 − 7 = 4 — 지우개는 풀보다 쌓기나무 4개만큼 더 가벼워요."],"asset":{"type":"balance","scales":[{"l":{"name":"지우개","icon":"🧽"},"r":{"name":"쌓기나무 7개","icon":"🟫"},"down":"eq"},{"l":{"name":"풀","icon":"🧴"},"r":{"name":"쌓기나무 11개","icon":"🟫"},"down":"eq"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_basic#6','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',2,'mc','auto','필통의 무게를 재었더니 나의 필통은 바둑돌 18개, 친구의 필통은 쌓기나무 21개와 무게가 같았어요. 이것만 보고 바르게 말한 것은 어느 것인가요?',ARRAY['M3-2-u5-X03','M3-2-u5-X21']::text[],true,'{"seq":6,"concept":"M3-2-u5-C5","difficulty":2,"kind":"mc","stem":"필통의 무게를 재었더니 나의 필통은 바둑돌 18개, 친구의 필통은 쌓기나무 21개와 무게가 같았어요. 이것만 보고 바르게 말한 것은 어느 것인가요?","options":[{"t":"재는 단위가 달라서 개수만으로는 비교할 수 없어요","correct":true},{"t":"친구의 필통이 더 무거워요","mis":"M3-2-u5-X03"},{"t":"나의 필통이 더 무거워요","mis":"M3-2-u5-X03"},{"t":"두 필통의 무게가 같아요","mis":"M3-2-u5-X21"}],"explanation":["나의 필통은 바둑돌, 친구의 필통은 쌓기나무로 재었어요.","바둑돌 한 개와 쌓기나무 한 개의 무게가 달라요.","필통의 무게를 비교하려면 같은 단위를 사용해야 해요."],"variant_rule":{"alt":[{"stem":"필통의 무게를 재었더니 나의 필통은 쌓기나무 17개, 친구의 필통은 바둑돌 20개와 무게가 같았어요. 이것만 보고 바르게 말한 것은 어느 것인가요?","options":[{"t":"재는 단위가 달라서 개수만으로는 비교할 수 없어요","correct":true},{"t":"친구의 필통이 더 무거워요","mis":"M3-2-u5-X03"},{"t":"나의 필통이 더 무거워요","mis":"M3-2-u5-X03"},{"t":"두 필통의 무게가 같아요","mis":"M3-2-u5-X21"}],"explanation":["나의 필통은 쌓기나무, 친구의 필통은 바둑돌로 재었어요.","쌓기나무 한 개와 바둑돌 한 개의 무게가 달라요.","필통의 무게를 비교하려면 같은 단위를 사용해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_basic#7','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',2,'mc','auto','양팔저울과 공깃돌로 학용품의 무게를 재었더니 연필은 공깃돌 7개, 자는 9개, 지우개는 8개와 무게가 같았어요. 무거운 것부터 차례대로 쓴 것은 어느 것인가요?',ARRAY['M3-2-u5-X22','M3-2-u5-X20','M3-2-u5-X21']::text[],false,'{"seq":7,"concept":"M3-2-u5-C5","difficulty":2,"kind":"mc","stem":"양팔저울과 공깃돌로 학용품의 무게를 재었더니 연필은 공깃돌 7개, 자는 9개, 지우개는 8개와 무게가 같았어요. 무거운 것부터 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"자, 지우개, 연필","correct":true},{"t":"연필, 지우개, 자","mis":"M3-2-u5-X22"},{"t":"연필, 자, 지우개","mis":"M3-2-u5-X20"},{"t":"지우개, 자, 연필","mis":"M3-2-u5-X21"}],"explanation":["같은 공깃돌로 재었으니 개수가 많을수록 더 무거워요.","자 9개 > 지우개 8개 > 연필 7개.","무거운 것부터 — 자, 지우개, 연필."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_basic#8','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',2,'mc','auto','양팔저울과 동전을 사용하여 양파와 감자의 무게를 비교했어요. 양파는 500원짜리 동전 20개, 감자는 100원짜리 동전 20개와 무게가 같았어요. 양파와 감자의 무게는 어떤가요?',ARRAY['M3-2-u5-X16','M3-2-u5-X21']::text[],false,'{"seq":8,"concept":"M3-2-u5-C5","difficulty":2,"kind":"mc","stem":"양팔저울과 동전을 사용하여 양파와 감자의 무게를 비교했어요. 양파는 500원짜리 동전 20개, 감자는 100원짜리 동전 20개와 무게가 같았어요. 양파와 감자의 무게는 어떤가요?","options":[{"t":"서로 달라요","correct":true},{"t":"서로 같아요","mis":"M3-2-u5-X16"},{"t":"동전 개수가 같으니 비교할 수 없어요","mis":"M3-2-u5-X21"},{"t":"감자가 더 무거워요","mis":"M3-2-u5-X16"}],"explanation":["양파와 감자 모두 동전 20개의 무게와 같아요.","그런데 500원짜리와 100원짜리 동전 한 개의 무게가 달라요.","그래서 양파와 감자의 무게는 서로 달라요."],"asset":{"type":"balance","scales":[{"l":{"name":"양파","icon":"🧅"},"r":{"name":"500원짜리 동전 20개","icon":"🪙"},"down":"eq"},{"l":{"name":"감자","icon":"🥔"},"r":{"name":"100원짜리 동전 20개","icon":"🪙"},"down":"eq"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_basic#9','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',2,'ox','auto','같은 필통의 무게를 바둑돌로 재면 18개, 쌓기나무로 재면 17개예요. 친구가 「둘 중 하나는 잘못 잰 거야.」라고 말했어요. 바르게 말했어요.',ARRAY['M3-2-u5-X03']::text[],true,'{"seq":9,"concept":"M3-2-u5-C5","difficulty":2,"kind":"ox","stem":"같은 필통의 무게를 바둑돌로 재면 18개, 쌓기나무로 재면 17개예요. 친구가 「둘 중 하나는 잘못 잰 거야.」라고 말했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"바둑돌 한 개와 쌓기나무 한 개의 무게가 달라서","correct":true},{"t":"같은 물건은 무엇으로 재어도 개수가 같아서","mis":"M3-2-u5-X03"}],"mis":"M3-2-u5-X03","explanation":["같은 필통이라도 재는 물건이 다르면 개수가 달라져요.","바둑돌 한 개와 쌓기나무 한 개의 무게가 다르기 때문이에요.","잘못 잰 것이 아니에요 — 바르지 않아요."],"variant_rule":{"alt":[{"stem":"친구의 필통의 무게를 바둑돌로 재면 20개, 쌓기나무로 재면 21개예요. 친구가 「둘 중 하나는 잘못 잰 거야.」라고 말했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"바둑돌 한 개와 쌓기나무 한 개의 무게가 달라서","correct":true},{"t":"같은 물건은 무엇으로 재어도 개수가 같아서","mis":"M3-2-u5-X03"}],"explanation":["같은 필통이라도 재는 물건이 다르면 개수가 달라져요.","바둑돌 한 개와 쌓기나무 한 개의 무게가 다르기 때문이에요.","잘못 잰 것이 아니에요 — 바르지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_basic#10','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',3,'mc','auto','공깃돌로 지우개, 자, 연필의 무게를 재었더니 지우개는 공깃돌 10개, 자는 9개, 연필은 8개와 무게가 같았어요. 친구가 「연필이 가장 무겁고 지우개가 가장 가벼워.」라고 말했어요. 친구의 말을 바르게 고친 것은 어느 것인가요?',ARRAY['M3-2-u5-X22','M3-2-u5-X21']::text[],false,'{"seq":10,"concept":"M3-2-u5-C5","difficulty":3,"kind":"mc","stem":"공깃돌로 지우개, 자, 연필의 무게를 재었더니 지우개는 공깃돌 10개, 자는 9개, 연필은 8개와 무게가 같았어요. 친구가 「연필이 가장 무겁고 지우개가 가장 가벼워.」라고 말했어요. 친구의 말을 바르게 고친 것은 어느 것인가요?","options":[{"t":"지우개가 가장 무겁고 연필이 가장 가벼워요","correct":true},{"t":"친구의 말이 맞아요 — 개수가 적을수록 무거워요","mis":"M3-2-u5-X22"},{"t":"자가 가장 무거워요","mis":"M3-2-u5-X21"},{"t":"공깃돌로는 알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["같은 공깃돌로 재면 공깃돌이 많이 필요할수록 더 무거워요.","지우개 10개 > 자 9개 > 연필 8개.","지우개가 가장 무겁고 연필이 가장 가벼워요 — 개수와 무게의 관계를 거꾸로 보면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_challenge#1','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',2,'mc','auto','무게가 비슷해 보이는 빈 우유갑과 빈 페트병 가운데 어느 것이 더 무거운지 알아보려고 해요. 가장 알맞은 방법은 어느 것인가요?',ARRAY['M3-2-u5-X16','M3-2-u5-X15']::text[],false,'{"seq":1,"concept":"M3-2-u5-C5","difficulty":2,"kind":"mc","stem":"무게가 비슷해 보이는 빈 우유갑과 빈 페트병 가운데 어느 것이 더 무거운지 알아보려고 해요. 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"양팔저울에 올려 아래로 내려가는 쪽을 봐요","correct":true},{"t":"크기가 더 큰 쪽을 골라요","mis":"M3-2-u5-X16"},{"t":"눈으로 보고 정해요","mis":"M3-2-u5-X16"},{"t":"위로 올라가는 쪽을 골라요","mis":"M3-2-u5-X15"}],"explanation":["양손에 들어 보면 무게가 비슷할 때 알기 어려워요.","양팔저울에 올리면 더 무거운 쪽으로 기울어요.","아래로 내려간 쪽이 더 무거워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_challenge#2','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',2,'sa','auto','바둑돌로 필통의 무게를 재었더니 나의 필통은 바둑돌 18개, 친구의 필통은 바둑돌 20개와 무게가 같았어요. 친구의 필통은 나의 필통보다 바둑돌 몇 개만큼 더 무거운가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C5","difficulty":2,"kind":"sa","stem":"바둑돌로 필통의 무게를 재었더니 나의 필통은 바둑돌 18개, 친구의 필통은 바둑돌 20개와 무게가 같았어요. 친구의 필통은 나의 필통보다 바둑돌 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["2"],"explanation":["같은 바둑돌로 재었으니 개수로 견줄 수 있어요.","나의 필통 18개, 친구의 필통 20개.","20 − 18 = 2 — 바둑돌 2개만큼 더 무거워요."],"variant_rule":{"alt":[{"stem":"쌓기나무로 필통의 무게를 재었더니 나의 필통은 쌓기나무 17개, 친구의 필통은 쌓기나무 21개와 무게가 같았어요. 친구의 필통은 나의 필통보다 쌓기나무 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["4"],"explanation":["같은 쌓기나무로 재었으니 개수로 견줄 수 있어요.","나의 필통 17개, 친구의 필통 21개.","21 − 17 = 4 — 쌓기나무 4개만큼 더 무거워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_challenge#3','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',3,'mc','auto','모양과 크기가 같은 구슬 6개에 1부터 6까지의 번호가 써 있어요. 5개의 무게는 같고, 1개만 다른 것보다 가벼워요. 구슬을 2개씩 묶어 양팔저울로 무게를 비교했어요. 가벼운 구슬이 있는 묶음의 번호는 어느 것인가요?',ARRAY['M3-2-u5-X15','M3-2-u5-X21']::text[],false,'{"seq":3,"concept":"M3-2-u5-C5","difficulty":3,"kind":"mc","stem":"모양과 크기가 같은 구슬 6개에 1부터 6까지의 번호가 써 있어요. 5개의 무게는 같고, 1개만 다른 것보다 가벼워요. 구슬을 2개씩 묶어 양팔저울로 무게를 비교했어요. 가벼운 구슬이 있는 묶음의 번호는 어느 것인가요?","options":[{"t":"5번, 6번","correct":true},{"t":"1번, 2번","mis":"M3-2-u5-X15"},{"t":"3번, 4번","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["첫째 저울은 수평 — 1·2번과 3·4번의 무게가 같아요.","둘째 저울은 5·6번 쪽이 올라갔어요 — 5·6번이 더 가벼워요.","가벼운 구슬은 5번, 6번 묶음에 있어요."],"asset":{"type":"balance","scales":[{"l":{"name":"1·2번 구슬","icon":"🔮"},"r":{"name":"3·4번 구슬","icon":"🔮"},"down":"eq"},{"l":{"name":"3·4번 구슬","icon":"🔮"},"r":{"name":"5·6번 구슬","icon":"🔮"},"down":"l"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_challenge#4','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',3,'mc','auto','5번 구슬과 6번 구슬 가운데 하나가 가벼워요. 더 가벼운 구슬을 찾는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u5-X15','M3-2-u5-X16','M3-2-u5-X21']::text[],false,'{"seq":4,"concept":"M3-2-u5-C5","difficulty":3,"kind":"mc","stem":"5번 구슬과 6번 구슬 가운데 하나가 가벼워요. 더 가벼운 구슬을 찾는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"양팔저울에 5번과 6번 구슬을 하나씩 올려 위로 올라간 쪽을 찾아요","correct":true},{"t":"양팔저울에서 아래로 내려간 쪽을 찾아요","mis":"M3-2-u5-X15"},{"t":"두 구슬의 크기를 눈으로 견주어요","mis":"M3-2-u5-X16"},{"t":"두 구슬은 무게가 같아서 찾을 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울은 무거운 쪽으로 기울어요.","5번과 6번을 한쪽에 하나씩 올려요.","위로 올라간 쪽의 구슬이 더 가벼워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_challenge#5','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',3,'sa','auto','양팔저울과 공깃돌로 재었더니 연필은 공깃돌 7개, 자는 9개, 지우개는 8개와 무게가 같았어요. 자는 연필보다 공깃돌 몇 개만큼 더 무거운가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u5-C5","difficulty":3,"kind":"sa","stem":"양팔저울과 공깃돌로 재었더니 연필은 공깃돌 7개, 자는 9개, 지우개는 8개와 무게가 같았어요. 자는 연필보다 공깃돌 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["2"],"explanation":["같은 공깃돌로 재었으니 개수로 견줄 수 있어요.","자 9개, 연필 7개.","9 − 7 = 2 — 공깃돌 2개만큼 더 무거워요."],"variant_rule":{"alt":[{"stem":"양팔저울과 공깃돌로 재었더니 연필은 공깃돌 7개, 자는 9개, 지우개는 8개와 무게가 같았어요. 지우개는 연필보다 공깃돌 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["1"],"explanation":["같은 공깃돌로 재었으니 개수로 견줄 수 있어요.","지우개 8개, 연필 7개.","8 − 7 = 1 — 공깃돌 1개만큼 더 무거워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_challenge#6','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',3,'ox','auto','양파는 500원짜리 동전 20개, 감자는 100원짜리 동전 20개와 무게가 같아요. 친구가 「둘 다 동전 20개와 같으니 양파와 감자의 무게는 같아.」라고 말했어요. 바르게 말했어요.',ARRAY['M3-2-u5-X16']::text[],false,'{"seq":6,"concept":"M3-2-u5-C5","difficulty":3,"kind":"ox","stem":"양파는 500원짜리 동전 20개, 감자는 100원짜리 동전 20개와 무게가 같아요. 친구가 「둘 다 동전 20개와 같으니 양파와 감자의 무게는 같아.」라고 말했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"500원짜리와 100원짜리 동전 한 개의 무게가 달라서","correct":true},{"t":"동전의 개수만 같으면 무게가 같아서","mis":"M3-2-u5-X16"}],"mis":"M3-2-u5-X16","explanation":["개수는 20개로 같아요.","그러나 500원짜리와 100원짜리 동전 한 개의 무게가 달라요.","양파와 감자의 무게는 달라요 — 바르지 않아요."],"asset":{"type":"balance","scales":[{"l":{"name":"양파","icon":"🧅"},"r":{"name":"500원짜리 동전 20개","icon":"🪙"},"down":"eq"},{"l":{"name":"감자","icon":"🥔"},"r":{"name":"100원짜리 동전 20개","icon":"🪙"},"down":"eq"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_challenge#7','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',3,'mc','auto','양팔저울과 쌓기나무를 사용하여 가위와 풀의 무게를 비교했어요. 가위는 쌓기나무 10개, 풀은 쌓기나무 5개의 무게와 같아요. 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X14','M3-2-u5-X21']::text[],false,'{"seq":7,"concept":"M3-2-u5-C5","difficulty":3,"kind":"mc","stem":"양팔저울과 쌓기나무를 사용하여 가위와 풀의 무게를 비교했어요. 가위는 쌓기나무 10개, 풀은 쌓기나무 5개의 무게와 같아요. 알맞은 것은 어느 것인가요?","options":[{"t":"풀의 무게가 가위의 무게보다 쌓기나무 5개만큼 더 가벼워요","correct":true},{"t":"가위의 무게가 풀의 무게보다 쌓기나무 5개만큼 더 가벼워요","mis":"M3-2-u5-X20"},{"t":"풀의 무게가 가위의 무게보다 쌓기나무 15개만큼 더 가벼워요","mis":"M3-2-u5-X14"},{"t":"풀의 무게가 가위의 무게보다 쌓기나무 10개만큼 더 가벼워요","mis":"M3-2-u5-X21"}],"explanation":["같은 쌓기나무로 재었으니 개수로 견줄 수 있어요.","가위 10개, 풀 5개 — 개수가 적은 풀이 더 가벼워요.","10 − 5 = 5 — 풀이 가위보다 쌓기나무 5개만큼 더 가벼워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_challenge#8','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',4,'essay','teacher','빈 우유갑과 빈 페트병 가운데 더 무거운 것을 저금통으로 재활용하려고 해요. 무게를 비교하는 방법 두 가지를 쓰고, 우유갑이 페트병보다 얼마나 더 무거운지 알려면 어떻게 해야 하는지 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u5-C5","difficulty":4,"kind":"essay","stem":"빈 우유갑과 빈 페트병 가운데 더 무거운 것을 저금통으로 재활용하려고 해요. 무게를 비교하는 방법 두 가지를 쓰고, 우유갑이 페트병보다 얼마나 더 무거운지 알려면 어떻게 해야 하는지 써 보세요.","answer_guide":{"answer":"예: ① 양손에 하나씩 들어 본다. ② 양팔저울에 올려 아래로 내려가는 쪽이 더 무겁다. 우유갑 쪽으로 기울었다면 우유갑이 더 무겁다. 얼마나 더 무거운지 알려면 바둑돌이나 공깃돌처럼 같은 단위 물건을 사용하여 각각 몇 개와 무게가 같은지 재어 개수의 차를 구한다.","scoring_points":["양손에 들어 보는 방법을 썼는가","양팔저울로 비교하는 방법과 내려간 쪽이 무겁다는 것을 썼는가","같은 단위 물건의 개수로 얼마나 더 무거운지 안다고 썼는가"]},"explanation":["양손에 들어 보기 — 무게가 비슷하면 알기 어려워요.","양팔저울 — 무거운 쪽이 내려가요.","얼마나 더 무거운지는 같은 단위 물건의 개수로 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_challenge#9','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',4,'essay','teacher','공깃돌로 지우개, 자, 연필의 무게를 재었더니 지우개는 10개, 자는 9개, 연필은 8개와 무게가 같았어요. 친구가 「연필이 가장 무겁고 지우개가 가장 가벼워.」라고 했어요. 친구의 생각이 잘못된 까닭을 쓰고 바르게 고쳐 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u5-C5","difficulty":4,"kind":"essay","stem":"공깃돌로 지우개, 자, 연필의 무게를 재었더니 지우개는 10개, 자는 9개, 연필은 8개와 무게가 같았어요. 친구가 「연필이 가장 무겁고 지우개가 가장 가벼워.」라고 했어요. 친구의 생각이 잘못된 까닭을 쓰고 바르게 고쳐 보세요.","answer_guide":{"answer":"예: 같은 공깃돌로 재면 공깃돌이 많이 필요할수록 더 무거운데, 친구는 개수가 적을수록 무겁다고 거꾸로 생각했다. 지우개 10개 > 자 9개 > 연필 8개이므로 지우개가 가장 무겁고 연필이 가장 가볍다.","scoring_points":["개수와 무게의 관계를 거꾸로 생각했다고 썼는가","공깃돌이 많을수록 무겁다고 썼는가","지우개가 가장 무겁고 연필이 가장 가볍다고 고쳤는가"]},"explanation":["같은 단위로 재면 개수가 많을수록 무거워요.","지우개 10개, 자 9개, 연필 8개.","가장 무거운 것은 지우개, 가장 가벼운 것은 연필이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L05_challenge#10','math',3,2,'u5','L05','tb_g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',4,'essay','teacher','나의 필통은 바둑돌 18개 또는 쌓기나무 17개, 친구의 필통은 바둑돌 20개 또는 쌓기나무 21개와 무게가 같았어요. 같은 필통인데 결과가 다른 까닭과, 필통의 무게를 비교할 때 무엇을 지켜야 하는지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u5-C5","difficulty":4,"kind":"essay","stem":"나의 필통은 바둑돌 18개 또는 쌓기나무 17개, 친구의 필통은 바둑돌 20개 또는 쌓기나무 21개와 무게가 같았어요. 같은 필통인데 결과가 다른 까닭과, 필통의 무게를 비교할 때 무엇을 지켜야 하는지 써 보세요.","answer_guide":{"answer":"예: 바둑돌 한 개와 쌓기나무 한 개의 무게가 다르기 때문에 같은 필통을 재어도 개수가 다르다. 필통의 무게를 비교할 때는 같은 단위를 사용해야 한다. 바둑돌로 재면 친구의 필통이 2개만큼, 쌓기나무로 재면 4개만큼 더 무겁다.","scoring_points":["단위 물건 한 개의 무게가 달라서라고 썼는가","같은 단위를 사용해야 한다고 썼는가","같은 단위로 견주어 친구의 필통이 더 무겁다고 했는가"]},"explanation":["바둑돌 18개와 20개, 쌓기나무 17개와 21개.","재는 물건이 다르면 개수가 달라요.","같은 단위로 견주어야 해요 — 어느 단위로 재도 친구의 필통이 더 무거워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_basic#1','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C6',1,'sa','auto','1 kg 300 g은 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u5-C6","difficulty":1,"kind":"sa","stem":"1 kg 300 g은 몇 g인가요? 숫자로 쓰세요.","answer":["1300"],"explanation":["1 kg = 1000 g이에요.","1000 g + 300 g = 1300 g.","1 kg 300 g = 1300 g."],"variant_rule":{"alt":[{"stem":"2 kg 300 g은 몇 g인가요? 숫자로 쓰세요.","answer":["2300"],"explanation":["1 kg = 1000 g — 2 kg = 2000 g.","2000 g + 300 g = 2300 g.","2 kg 300 g = 2300 g."]},{"stem":"3 kg 600 g은 몇 g인가요? 숫자로 쓰세요.","answer":["3600"],"explanation":["1 kg = 1000 g — 3 kg = 3000 g.","3000 g + 600 g = 3600 g.","3 kg 600 g = 3600 g."]},{"stem":"1 kg 500 g은 몇 g인가요? 숫자로 쓰세요.","answer":["1500"],"explanation":["1 kg = 1000 g이에요.","1000 g + 500 g = 1500 g.","1 kg 500 g = 1500 g."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_basic#2','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C7',1,'sa','auto','4 t은 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C7","difficulty":1,"kind":"sa","stem":"4 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["4000"],"explanation":["1 t = 1000 kg이에요.","4 t은 1000 kg이 4번이에요.","4 t = 4000 kg."],"variant_rule":{"alt":[{"stem":"5 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["5000"],"explanation":["1 t = 1000 kg이에요.","5 t은 1000 kg이 5번이에요.","5 t = 5000 kg."]},{"stem":"6 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["6000"],"explanation":["1 t = 1000 kg이에요.","6 t은 1000 kg이 6번이에요.","6 t = 6000 kg."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_basic#3','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C6',1,'mc','auto','3400 g은 몇 kg 몇 g인가요?',ARRAY['M3-2-u5-X04','M3-2-u5-X05','M3-2-u5-X06']::text[],true,'{"seq":3,"concept":"M3-2-u5-C6","difficulty":1,"kind":"mc","stem":"3400 g은 몇 kg 몇 g인가요?","options":[{"t":"3 kg 400 g","correct":true},{"t":"34 kg","mis":"M3-2-u5-X04"},{"t":"3 kg 40 g","mis":"M3-2-u5-X05"},{"t":"3 g 400 kg","mis":"M3-2-u5-X06"}],"explanation":["1000 g = 1 kg이에요.","3400 g = 3000 g + 400 g.","3400 g = 3 kg 400 g."],"variant_rule":{"alt":[{"stem":"4900 g은 몇 kg 몇 g인가요?","options":[{"t":"4 kg 900 g","correct":true},{"t":"49 kg","mis":"M3-2-u5-X04"},{"t":"4 kg 90 g","mis":"M3-2-u5-X05"},{"t":"4 g 900 kg","mis":"M3-2-u5-X06"}],"explanation":["1000 g = 1 kg이에요.","4900 g = 4000 g + 900 g.","4900 g = 4 kg 900 g."]},{"stem":"7200 g은 몇 kg 몇 g인가요?","options":[{"t":"7 kg 200 g","correct":true},{"t":"72 kg","mis":"M3-2-u5-X04"},{"t":"7 kg 20 g","mis":"M3-2-u5-X05"},{"t":"7 g 200 kg","mis":"M3-2-u5-X06"}],"explanation":["1000 g = 1 kg이에요.","7200 g = 7000 g + 200 g.","7200 g = 7 kg 200 g."]},{"stem":"2200 g은 몇 kg 몇 g인가요?","options":[{"t":"2 kg 200 g","correct":true},{"t":"22 kg","mis":"M3-2-u5-X04"},{"t":"2 kg 20 g","mis":"M3-2-u5-X05"},{"t":"2 g 200 kg","mis":"M3-2-u5-X06"}],"explanation":["1000 g = 1 kg이에요.","2200 g = 2000 g + 200 g.","2200 g = 2 kg 200 g."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_basic#4','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C6',1,'mc','auto','8 kg 400 g을 바르게 읽은 것은 어느 것인가요?',ARRAY['M3-2-u5-X06','M3-2-u5-X05']::text[],true,'{"seq":4,"concept":"M3-2-u5-C6","difficulty":1,"kind":"mc","stem":"8 kg 400 g을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"8 킬로그램 400 그램","correct":true},{"t":"8 그램 400 킬로그램","mis":"M3-2-u5-X06"},{"t":"8400 킬로그램","mis":"M3-2-u5-X05"},{"t":"8 킬로그램 400 킬로그램","mis":"M3-2-u5-X06"}],"explanation":["1 kg은 1 킬로그램이라고 읽어요.","8 kg 400 g의 앞은 킬로그램, 뒤는 그램이에요.","8 kg 400 g — 8 킬로그램 400 그램."],"variant_rule":{"alt":[{"stem":"1 kg 300 g을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"1 킬로그램 300 그램","correct":true},{"t":"1 그램 300 킬로그램","mis":"M3-2-u5-X06"},{"t":"1300 킬로그램","mis":"M3-2-u5-X05"},{"t":"1 킬로그램 300 킬로그램","mis":"M3-2-u5-X06"}],"explanation":["1 kg은 1 킬로그램이라고 읽어요.","1 kg 300 g의 앞은 킬로그램, 뒤는 그램이에요.","1 kg 300 g — 1 킬로그램 300 그램."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_basic#5','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C6',2,'sa','auto','저울에 설탕 1 kg을 올려놓고 설탕 300 g을 더 올렸어요. 저울의 1 kg과 2 kg 사이가 똑같이 10칸으로 나뉘어 있고, 바늘이 1 kg에서 3칸 더 간 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u5-C6","difficulty":2,"kind":"sa","stem":"저울에 설탕 1 kg을 올려놓고 설탕 300 g을 더 올렸어요. 저울의 1 kg과 2 kg 사이가 똑같이 10칸으로 나뉘어 있고, 바늘이 1 kg에서 3칸 더 간 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["1300"],"explanation":["한 칸의 크기부터: 1 kg~2 kg 사이 10칸 → 1000 ÷ 10 = 100, 한 칸은 100 g이에요.","1 kg에서 3칸 더 → 1000 + 100 × 3 = 1300.","1300 g = 1 kg 300 g."],"variant_rule":{"alt":[{"stem":"저울에 콩을 올렸어요. 저울의 2 kg과 3 kg 사이가 똑같이 10칸으로 나뉘어 있고, 바늘이 2 kg에서 2칸 더 간 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["2200"],"explanation":["한 칸의 크기부터: 2 kg~3 kg 사이 10칸 → 1000 ÷ 10 = 100, 한 칸은 100 g이에요.","2 kg에서 2칸 더 → 2000 + 100 × 2 = 2200.","2200 g = 2 kg 200 g."]},{"stem":"서준이가 모은 재활용품을 저울에 올렸어요. 저울의 2 kg과 3 kg 사이가 똑같이 10칸으로 나뉘어 있고, 바늘이 2 kg에서 3칸 더 간 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["2300"],"explanation":["한 칸의 크기부터: 2 kg~3 kg 사이 10칸 → 1000 ÷ 10 = 100, 한 칸은 100 g이에요.","2 kg에서 3칸 더 → 2000 + 100 × 3 = 2300.","2300 g = 2 kg 300 g."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_basic#6','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C7',2,'mc','auto','3000 kg은 몇 t인가요?',ARRAY['M3-2-u5-X17','M3-2-u5-X06']::text[],true,'{"seq":6,"concept":"M3-2-u5-C7","difficulty":2,"kind":"mc","stem":"3000 kg은 몇 t인가요?","options":[{"t":"3 t","correct":true},{"t":"30 t","mis":"M3-2-u5-X17"},{"t":"300 t","mis":"M3-2-u5-X17"},{"t":"3000 t","mis":"M3-2-u5-X06"}],"explanation":["1000 kg = 1 t이에요.","3000 kg은 1000 kg이 3번이에요.","3000 kg = 3 t."],"variant_rule":{"alt":[{"stem":"7000 kg은 몇 t인가요?","options":[{"t":"7 t","correct":true},{"t":"70 t","mis":"M3-2-u5-X17"},{"t":"700 t","mis":"M3-2-u5-X17"},{"t":"7000 t","mis":"M3-2-u5-X06"}],"explanation":["1000 kg = 1 t이에요.","7000 kg은 1000 kg이 7번이에요.","7000 kg = 7 t."]},{"stem":"8000 kg은 몇 t인가요?","options":[{"t":"8 t","correct":true},{"t":"80 t","mis":"M3-2-u5-X17"},{"t":"800 t","mis":"M3-2-u5-X17"},{"t":"8000 t","mis":"M3-2-u5-X06"}],"explanation":["1000 kg = 1 t이에요.","8000 kg은 1000 kg이 8번이에요.","8000 kg = 8 t."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_basic#7','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C7',2,'sa','auto','10 kg인 쌀이 몇 포대 있어야 1 t이 될까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u5-C7","difficulty":2,"kind":"sa","stem":"10 kg인 쌀이 몇 포대 있어야 1 t이 될까요? 숫자로 쓰세요.","answer":["100"],"explanation":["1 t = 1000 kg이에요.","10 kg씩 몇 번이면 1000 kg인지 생각해요 — 10 × 100 = 1000.","10 kg인 쌀 100포대가 있어야 1 t이에요."],"variant_rule":{"alt":[{"stem":"1 kg인 밀가루가 몇 봉지 있어야 1 t이 될까요? 숫자로 쓰세요.","answer":["1000"],"explanation":["1 t = 1000 kg이에요.","1 kg씩 1000번이면 1000 kg — 1 × 1000 = 1000.","1 kg인 밀가루 1000봉지가 있어야 1 t이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_basic#8','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C6',2,'match','auto','무게가 같은 것끼리 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u5-C6","difficulty":2,"kind":"match","stem":"무게가 같은 것끼리 알맞게 이으세요.","pairs":[{"l":"5 t","r":"5000 kg"},{"l":"5700 g","r":"5 kg 700 g"},{"l":"5 kg 850 g","r":"5850 g"}],"mis":"M3-2-u5-X05","explanation":["1 t = 1000 kg, 1 kg = 1000 g이에요.","5 t = 5000 kg, 5700 g = 5 kg 700 g, 5 kg 850 g = 5850 g.","숫자가 비슷해 보여도 단위를 살펴 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_basic#9','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C7',2,'mc','auto','잘못된 것은 어느 것인가요? ㉠ 1 kg 600 g = 1600 g ㉡ 7200 g = 7 kg 200 g ㉢ 6 t = 600 kg',ARRAY['M3-2-u5-X20','M3-2-u5-X17']::text[],false,'{"seq":9,"concept":"M3-2-u5-C7","difficulty":2,"kind":"mc","stem":"잘못된 것은 어느 것인가요? ㉠ 1 kg 600 g = 1600 g ㉡ 7200 g = 7 kg 200 g ㉢ 6 t = 600 kg","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M3-2-u5-X20"},{"t":"㉡","mis":"M3-2-u5-X20"},{"t":"잘못된 것이 없어요","mis":"M3-2-u5-X17"}],"explanation":["1 kg = 1000 g, 1 t = 1000 kg이에요.","㉠ 1600 g, ㉡ 7 kg 200 g은 바르게 나타냈어요.","㉢ 6 t = 6000 kg이에요 — 600 kg은 1 t을 100 kg으로 본 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_basic#10','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C6',3,'mc','auto','정후는 감자를 3 kg 40 g 캤고, 지아는 감자를 3400 g 캤어요. 캔 감자의 무게가 더 무거운 사람은 누구인가요?',ARRAY['M3-2-u5-X23','M3-2-u5-X05','M3-2-u5-X21']::text[],false,'{"seq":10,"concept":"M3-2-u5-C6","difficulty":3,"kind":"mc","stem":"정후는 감자를 3 kg 40 g 캤고, 지아는 감자를 3400 g 캤어요. 캔 감자의 무게가 더 무거운 사람은 누구인가요?","options":[{"t":"지아","correct":true},{"t":"정후","mis":"M3-2-u5-X23"},{"t":"두 사람이 같아요","mis":"M3-2-u5-X05"},{"t":"단위가 달라서 비교할 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","3400 g = 3 kg 400 g — 3 kg 40 g과 견주면 400 g > 40 g.","지아가 캔 감자가 더 무거워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_challenge#1','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C6',2,'mc','auto','샴푸 통의 무게를 재었더니 쌓기나무 20개 또는 바둑돌 35개의 무게와 같았어요. 샴푸 통의 무게를 정확하게 나타내려면 어떻게 해야 하나요?',ARRAY['M3-2-u5-X03','M3-2-u5-X21']::text[],false,'{"seq":1,"concept":"M3-2-u5-C6","difficulty":2,"kind":"mc","stem":"샴푸 통의 무게를 재었더니 쌓기나무 20개 또는 바둑돌 35개의 무게와 같았어요. 샴푸 통의 무게를 정확하게 나타내려면 어떻게 해야 하나요?","options":[{"t":"누구나 똑같이 약속한 무게의 단위로 나타내요","correct":true},{"t":"쌓기나무 20개라고만 해요","mis":"M3-2-u5-X03"},{"t":"바둑돌 35개가 더 정확하니 바둑돌로 나타내요","mis":"M3-2-u5-X03"},{"t":"무게는 정확하게 나타낼 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["같은 샴푸 통인데 쌓기나무로는 20개, 바둑돌로는 35개예요.","재는 물건에 따라 수가 달라져서 정확하게 알리기 어려워요.","무게를 정확하게 나타내는 단위(kg, g)가 필요해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"샴푸 통의 무게를 재어 보자."},{"who":"친구 2","text":"샴푸 통의 무게는 쌓기나무 20개 또는 바둑돌 35개의 무게와 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_challenge#2','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C6',2,'mc','auto','수박의 무게는 5000 g이에요. 수박의 무게를 kg으로 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u5-X04','M3-2-u5-X06']::text[],true,'{"seq":2,"concept":"M3-2-u5-C6","difficulty":2,"kind":"mc","stem":"수박의 무게는 5000 g이에요. 수박의 무게를 kg으로 나타낸 것은 어느 것인가요?","options":[{"t":"5 kg","correct":true},{"t":"50 kg","mis":"M3-2-u5-X04"},{"t":"500 kg","mis":"M3-2-u5-X04"},{"t":"5 t","mis":"M3-2-u5-X06"}],"explanation":["1000 g = 1 kg이에요.","5000 g은 1000 g이 5번이에요.","5000 g = 5 kg."],"variant_rule":{"alt":[{"stem":"감자의 무게는 1 kg 500 g이에요. 감자의 무게를 g으로 나타낸 것은 어느 것인가요?","options":[{"t":"1500 g","correct":true},{"t":"150 g","mis":"M3-2-u5-X05"},{"t":"600 g","mis":"M3-2-u5-X04"},{"t":"15000 g","mis":"M3-2-u5-X05"}],"explanation":["1 kg = 1000 g이에요.","1000 g + 500 g = 1500 g.","1 kg 500 g = 1500 g."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_challenge#3','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C7',3,'mc','auto','트럭에 실을 수 있는 무게는 1000 kg까지예요. 이 무게를 간단하게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u5-X17','M3-2-u5-X06']::text[],false,'{"seq":3,"concept":"M3-2-u5-C7","difficulty":3,"kind":"mc","stem":"트럭에 실을 수 있는 무게는 1000 kg까지예요. 이 무게를 간단하게 나타낸 것은 어느 것인가요?","options":[{"t":"1 t","correct":true},{"t":"10 t","mis":"M3-2-u5-X17"},{"t":"100 t","mis":"M3-2-u5-X17"},{"t":"1 kg","mis":"M3-2-u5-X06"}],"explanation":["kg 앞의 수가 커지면 무게가 어느 정도인지 한번에 알아보기 힘들어요.","kg보다 더 큰 무게의 단위 t을 써요 — 1000 kg = 1 t.","트럭에 실을 수 있는 무게는 1 t이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_challenge#4','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C7',3,'mc','auto','1300 kg인 물건과 1 t인 물건이 있어요. 더 무거운 것은 어느 것인가요?',ARRAY['M3-2-u5-X23','M3-2-u5-X21']::text[],false,'{"seq":4,"concept":"M3-2-u5-C7","difficulty":3,"kind":"mc","stem":"1300 kg인 물건과 1 t인 물건이 있어요. 더 무거운 것은 어느 것인가요?","options":[{"t":"1300 kg인 물건","correct":true},{"t":"1 t인 물건 — t은 kg보다 큰 단위라서","mis":"M3-2-u5-X23"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 비교할 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["1 t = 1000 kg이에요.","1000 kg < 1300 kg.","1300 kg인 물건이 더 무거워요 — t이 붙었다고 항상 더 무거운 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_challenge#5','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C6',3,'sa','auto','정후는 감자를 3 kg 40 g 캤어요. 정후가 캔 감자는 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u5-C6","difficulty":3,"kind":"sa","stem":"정후는 감자를 3 kg 40 g 캤어요. 정후가 캔 감자는 몇 g인가요? 숫자로 쓰세요.","answer":["3040"],"explanation":["1 kg = 1000 g — 3 kg = 3000 g.","3000 g + 40 g = 3040 g.","3 kg 40 g = 3040 g — 3400 g과 헷갈리지 않아요."],"variant_rule":{"alt":[{"stem":"무게가 5 kg 850 g인 물건이 있어요. 이 물건은 몇 g인가요? 숫자로 쓰세요.","answer":["5850"],"explanation":["1 kg = 1000 g — 5 kg = 5000 g.","5000 g + 850 g = 5850 g.","5 kg 850 g = 5850 g."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_challenge#6','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C6',3,'ox','auto','1 kg 600 g은 1700 g보다 무거워요.',ARRAY['M3-2-u5-X23']::text[],false,'{"seq":6,"concept":"M3-2-u5-C6","difficulty":3,"kind":"ox","stem":"1 kg 600 g은 1700 g보다 무거워요.","answer":"X","reason_options":[{"t":"1 kg 600 g = 1600 g이라서 1700 g보다 가벼워서","correct":true},{"t":"kg이 붙은 무게는 g으로만 쓴 무게보다 언제나 무거워서","mis":"M3-2-u5-X23"}],"mis":"M3-2-u5-X23","explanation":["한 가지 단위로 바꾸어 견주어요.","1 kg 600 g = 1600 g이에요.","1600 g < 1700 g — 1 kg 600 g이 더 가벼워요. 바르지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_challenge#7','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C6',3,'sa','auto','우리나라 고유의 무게 단위 「근」은 고기와 채소의 무게를 잴 때 써요. 고기 1근은 600 g, 채소 1근은 375 g이에요. 고기 1근은 채소 1근보다 몇 g 더 무거운가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M3-2-u5-C6","difficulty":3,"kind":"sa","stem":"우리나라 고유의 무게 단위 「근」은 고기와 채소의 무게를 잴 때 써요. 고기 1근은 600 g, 채소 1근은 375 g이에요. 고기 1근은 채소 1근보다 몇 g 더 무거운가요? 숫자로 쓰세요.","answer":["225"],"explanation":["고기 1근과 채소 1근은 무게가 달라요.","600 g − 375 g = 225 g.","고기 1근이 225 g 더 무거워요 — 같은 「1근」이라도 무게가 달라 약속된 단위 g, kg이 편리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_challenge#8','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C6',4,'essay','teacher','정후는 감자를 3 kg 40 g 캤고, 지아는 감자를 3400 g 캤어요. 캔 감자의 무게가 더 무거운 사람은 누구인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u5-C6","difficulty":4,"kind":"essay","stem":"정후는 감자를 3 kg 40 g 캤고, 지아는 감자를 3400 g 캤어요. 캔 감자의 무게가 더 무거운 사람은 누구인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 3400 g = 3 kg 400 g이다. 3 kg 40 g과 3 kg 400 g을 비교하면 kg은 같고 g이 400 g > 40 g이므로 지아가 캔 감자의 무게가 더 무겁다. (또는 3 kg 40 g = 3040 g < 3400 g) 답: 지아","scoring_points":["한 가지 단위로 바꾸었는가","3 kg 40 g과 3 kg 400 g(또는 3040 g과 3400 g)을 바르게 견주었는가","지아라고 답했는가"]},"explanation":["3400 g = 3 kg 400 g.","3 kg 40 g < 3 kg 400 g.","지아가 캔 감자가 더 무거워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_challenge#9','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C6',4,'essay','teacher','친구가 1 kg 500 g을 「150 g」이라고 나타냈어요. 무엇이 잘못되었는지 쓰고 바르게 나타내 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u5-C6","difficulty":4,"kind":"essay","stem":"친구가 1 kg 500 g을 「150 g」이라고 나타냈어요. 무엇이 잘못되었는지 쓰고 바르게 나타내 보세요.","answer_guide":{"answer":"예: 1 kg은 1000 g인데 1과 500을 이어 쓰면서 0을 빠뜨렸다. 1 kg 500 g = 1000 g + 500 g = 1500 g이다.","scoring_points":["1 kg = 1000 g을 이용해야 한다고 썼는가","수를 이어 쓰거나 0을 빠뜨린 잘못을 찾았는가","1500 g으로 바르게 나타냈는가"]},"explanation":["1 kg = 1000 g이에요.","1000 g + 500 g = 1500 g.","1 kg 500 g = 1500 g — 150 g이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L06_challenge#10','math',3,2,'u5','L06','tb_g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C7',4,'essay','teacher','트럭에 실을 수 있는 무게는 1000 kg, 코끼리의 무게는 3000 kg이에요. 이런 무게를 나타낼 때 kg보다 더 큰 단위가 필요한 까닭을 쓰고, 1 t이 얼마만큼인지 쌀이나 밀가루를 이용하여 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u5-C7","difficulty":4,"kind":"essay","stem":"트럭에 실을 수 있는 무게는 1000 kg, 코끼리의 무게는 3000 kg이에요. 이런 무게를 나타낼 때 kg보다 더 큰 단위가 필요한 까닭을 쓰고, 1 t이 얼마만큼인지 쌀이나 밀가루를 이용하여 설명해 보세요.","answer_guide":{"answer":"예: kg 앞의 수가 커지면 무게가 어느 정도인지 한번에 알아보기 힘들어서 1000 kg을 1 t으로 간단하게 나타낸다. 트럭은 1 t, 코끼리는 3 t이다. 1 t은 10 kg인 쌀 100포대, 1 kg인 밀가루 1000봉지와 같은 무게이다.","scoring_points":["kg 앞의 수가 커지면 불편하다고 썼는가","1000 kg = 1 t(트럭 1 t, 코끼리 3 t)을 썼는가","쌀 100포대 또는 밀가루 1000봉지로 1 t을 설명했는가"]},"explanation":["1000 kg = 1 t, 3000 kg = 3 t.","10 kg × 100 = 1000 kg = 1 t.","1 kg × 1000 = 1000 kg = 1 t."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_basic#1','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',1,'mc','auto','강아지의 무게는 약 10 ○예요. ○에 알맞은 단위는 어느 것인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],true,'{"seq":1,"concept":"M3-2-u5-C8","difficulty":1,"kind":"mc","stem":"강아지의 무게는 약 10 ○예요. ○에 알맞은 단위는 어느 것인가요?","options":[{"t":"kg","correct":true},{"t":"g","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["강아지를 아는 무게와 견주어 보아요.","무게에 쓰는 단위는 g·kg·t이에요.","강아지의 무게는 약 10 kg이에요."],"variant_rule":{"alt":[{"stem":"김치 반 포기의 무게는 약 500 ○예요. ○에 알맞은 단위는 어느 것인가요?","options":[{"t":"g","correct":true},{"t":"kg","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["김치 반 포기를 아는 무게와 견주어 보아요.","무게에 쓰는 단위는 g·kg·t이에요.","김치 반 포기의 무게는 약 500 g이에요."]},{"stem":"자동차의 무게는 약 1 ○예요. ○에 알맞은 단위는 어느 것인가요?","options":[{"t":"t","correct":true},{"t":"g","mis":"M3-2-u5-X09"},{"t":"kg","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["자동차를 아는 무게와 견주어 보아요.","무게에 쓰는 단위는 g·kg·t이에요.","자동차의 무게는 약 1 t이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_basic#2','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',1,'sa','auto','은비는 폐식용유를 재활용하여 만든 빨랫비누를 사려고 해요. 한 봉지에 약 100 g인 비누가 10개 들어 있어요. 빨랫비누 한 봉지의 무게는 약 몇 g으로 어림할 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C8","difficulty":1,"kind":"sa","stem":"은비는 폐식용유를 재활용하여 만든 빨랫비누를 사려고 해요. 한 봉지에 약 100 g인 비누가 10개 들어 있어요. 빨랫비누 한 봉지의 무게는 약 몇 g으로 어림할 수 있나요? 숫자로 쓰세요.","answer":["1000"],"explanation":["무게를 알고 있는 비누가 몇 개 들어 있는지로 어림해요.","100 g이 10개 — 100 × 10 = 1000.","약 1000 g — 약 1 kg인 밀가루의 무게와 비슷해요."],"variant_rule":{"alt":[{"stem":"약 100 g인 물건 5개의 무게는 약 몇 g인가요? 숫자로 쓰세요.","answer":["500"],"explanation":["약 100 g인 물건이 5개예요.","100 × 5 = 500.","약 500 g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_basic#3','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',1,'mc','auto','무게가 약 1 g인 물건은 어느 것인가요?',ARRAY['M3-2-u5-X09']::text[],false,'{"seq":3,"concept":"M3-2-u5-C8","difficulty":1,"kind":"mc","stem":"무게가 약 1 g인 물건은 어느 것인가요?","options":[{"t":"클립 1개","correct":true},{"t":"강아지","mis":"M3-2-u5-X09"},{"t":"책가방","mis":"M3-2-u5-X09"},{"t":"김치 반 포기","mis":"M3-2-u5-X09"}],"explanation":["1 g은 아주 가벼운 무게예요.","클립 1개를 전자저울로 재면 1 g쯤이에요.","무게가 약 1 g인 물건은 클립 1개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_basic#4','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',1,'sa','auto','사과를 저울에 올렸어요. 저울의 0과 500 g 사이가 똑같이 5칸으로 나뉘어 있고, 바늘이 0에서부터 4칸째 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u5-C8","difficulty":1,"kind":"sa","stem":"사과를 저울에 올렸어요. 저울의 0과 500 g 사이가 똑같이 5칸으로 나뉘어 있고, 바늘이 0에서부터 4칸째 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["400"],"explanation":["한 칸의 크기부터: 0~500 g 사이 5칸 → 500 ÷ 5 = 100, 한 칸은 100 g이에요.","4칸 → 100 × 4 = 400.","400 g이에요."],"variant_rule":{"alt":[{"stem":"필통을 저울에 올렸어요. 저울의 300 g과 400 g 사이가 똑같이 2칸으로 나뉘어 있고, 바늘이 300 g에서 1칸 더 간 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["350"],"explanation":["한 칸의 크기부터: 300 g~400 g 사이 2칸 → 100 ÷ 2 = 50, 한 칸은 50 g이에요.","300 g에서 1칸 더 → 300 + 50 × 1 = 350.","350 g이에요."]},{"stem":"가방을 저울에 올렸어요. 저울의 0과 9 kg 사이가 똑같이 9칸으로 나뉘어 있고, 바늘이 0에서부터 5칸째 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["5000"],"explanation":["한 칸의 크기부터: 0~9 kg 사이 9칸 → 9000 ÷ 9 = 1000, 한 칸은 1000 g이에요.","5칸 → 1000 × 5 = 5000.","5 kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_basic#5','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',2,'ox','auto','양파의 무게를 잴 때는 1 kg 추보다 100 g 추가 더 알맞아요.',ARRAY['M3-2-u5-X09']::text[],true,'{"seq":5,"concept":"M3-2-u5-C8","difficulty":2,"kind":"ox","stem":"양파의 무게를 잴 때는 1 kg 추보다 100 g 추가 더 알맞아요.","answer":"O","reason_options":[{"t":"가벼운 물건은 작은 무게의 추로 재야 알맞아서","correct":true},{"t":"무거운 추로 재야 언제나 정확해서","mis":"M3-2-u5-X09"}],"mis":"M3-2-u5-X09","explanation":["양파는 1 kg보다 가벼워요.","1 kg 추로는 무게를 알맞게 잴 수 없어요.","가벼운 양파는 100 g 추로 재요 — 맞아요."],"variant_rule":{"alt":[{"stem":"수박의 무게를 잴 때는 1 kg 추보다 100 g 추가 더 알맞아요.","answer":"X","reason_options":[{"t":"무거운 물건은 큰 무게의 추로 재야 알맞아서","correct":true},{"t":"작은 추로 여러 번 재야 언제나 좋아서","mis":"M3-2-u5-X09"}],"explanation":["수박은 1 kg보다 무거워요.","100 g 추로 재면 추가 아주 많이 필요해요.","무거운 수박은 1 kg 추로 재요 — 바르지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_basic#6','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',2,'sa','auto','빨랫비누가 2 kg 정도 들어 있는 봉지를 고르려고 해요. 약 2 kg은 약 1 kg인 물건 몇 개의 무게와 비슷한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u5-C8","difficulty":2,"kind":"sa","stem":"빨랫비누가 2 kg 정도 들어 있는 봉지를 고르려고 해요. 약 2 kg은 약 1 kg인 물건 몇 개의 무게와 비슷한가요? 숫자로 쓰세요.","answer":["2"],"explanation":["약 1 kg인 물건이 몇 번이면 약 2 kg인지 생각해요.","1 kg + 1 kg = 2 kg.","약 1 kg인 물건 2개의 무게와 비슷해요."],"variant_rule":{"alt":[{"stem":"빨랫비누가 2 kg 정도 들어 있는 봉지를 고르려고 해요. 약 2 kg은 약 1 kg인 물건 1개와 약 500 g인 물건 몇 개를 합한 무게와 비슷한가요? 숫자로 쓰세요.","answer":["2"],"explanation":["약 1 kg인 물건 1개를 빼면 1 kg이 더 필요해요.","500 g + 500 g = 1000 g = 1 kg.","약 500 g인 물건 2개를 더 합하면 약 2 kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_basic#7','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',2,'mc','auto','배, 버스, 유모차, 자전거 가운데 무게가 1 t보다 더 무거운 것을 모두 고른 것은 어느 것인가요?',ARRAY['M3-2-u5-X09']::text[],false,'{"seq":7,"concept":"M3-2-u5-C8","difficulty":2,"kind":"mc","stem":"배, 버스, 유모차, 자전거 가운데 무게가 1 t보다 더 무거운 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"배, 버스","correct":true},{"t":"유모차, 자전거","mis":"M3-2-u5-X09"},{"t":"배, 자전거","mis":"M3-2-u5-X09"},{"t":"버스, 유모차","mis":"M3-2-u5-X09"}],"explanation":["1 t = 1000 kg — 아주 무거운 무게예요.","배와 버스는 1000 kg보다 훨씬 무거워요.","유모차와 자전거는 1 t보다 훨씬 가벼워요 — 답은 배, 버스."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_basic#8','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',2,'mc','auto','트럭의 무게는 약 12 ○예요. ○에 알맞은 단위는 어느 것인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],true,'{"seq":8,"concept":"M3-2-u5-C8","difficulty":2,"kind":"mc","stem":"트럭의 무게는 약 12 ○예요. ○에 알맞은 단위는 어느 것인가요?","options":[{"t":"t","correct":true},{"t":"g","mis":"M3-2-u5-X09"},{"t":"kg","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["트럭을 아는 무게와 견주어 보아요.","무게에 쓰는 단위는 g·kg·t이에요.","트럭의 무게는 약 12 t이에요."],"variant_rule":{"alt":[{"stem":"농구공의 무게는 약 650 ○예요. ○에 알맞은 단위는 어느 것인가요?","options":[{"t":"g","correct":true},{"t":"kg","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["농구공을 아는 무게와 견주어 보아요.","무게에 쓰는 단위는 g·kg·t이에요.","농구공의 무게는 약 650 g이에요."]},{"stem":"책상의 무게는 약 15 ○예요. ○에 알맞은 단위는 어느 것인가요?","options":[{"t":"kg","correct":true},{"t":"g","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["책상을 아는 무게와 견주어 보아요.","무게에 쓰는 단위는 g·kg·t이에요.","책상의 무게는 약 15 kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_basic#9','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',2,'sa','auto','감자를 저울에 올렸어요. 저울의 2 kg과 3 kg 사이가 똑같이 10칸으로 나뉘어 있고, 바늘이 2 kg에서 8칸 더 간 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u5-C8","difficulty":2,"kind":"sa","stem":"감자를 저울에 올렸어요. 저울의 2 kg과 3 kg 사이가 똑같이 10칸으로 나뉘어 있고, 바늘이 2 kg에서 8칸 더 간 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["2800"],"explanation":["한 칸의 크기부터: 2 kg~3 kg 사이 10칸 → 1000 ÷ 10 = 100, 한 칸은 100 g이에요.","2 kg에서 8칸 더 → 2000 + 100 × 8 = 2800.","2800 g = 2 kg 800 g."],"variant_rule":{"alt":[{"stem":"물건을 저울에 올렸어요. 저울의 1 kg과 2 kg 사이가 똑같이 10칸으로 나뉘어 있고, 바늘이 1 kg에서 5칸 더 간 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["1500"],"explanation":["한 칸의 크기부터: 1 kg~2 kg 사이 10칸 → 1000 ÷ 10 = 100, 한 칸은 100 g이에요.","1 kg에서 5칸 더 → 1000 + 100 × 5 = 1500.","1500 g = 1 kg 500 g."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_basic#10','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',3,'mc','auto','무게를 잘못 어림한 사람은 누구인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X08']::text[],false,'{"seq":10,"concept":"M3-2-u5-C8","difficulty":3,"kind":"mc","stem":"무게를 잘못 어림한 사람은 누구인가요?","options":[{"t":"정후","correct":true},{"t":"민준","mis":"M3-2-u5-X20"},{"t":"서윤","mis":"M3-2-u5-X20"},{"t":"모두 바르게 어림했어요","mis":"M3-2-u5-X08"}],"explanation":["정후 — 50 g인 공책 10권은 50 × 10 = 500, 약 500 g이에요. 약 5 kg이 아니에요.","민준 — 밀가루 1 kg과 비슷하니 약 1 kg — 알맞아요.","서윤 — 200 g 사과 2개와 100 g 귤 1개는 200 + 200 + 100 = 500, 약 500 g — 알맞아요."],"asset":{"type":"speech","turns":[{"who":"정후","text":"위인전의 무게는 50 g인 공책 10권의 무게와 비슷해서 약 5 kg이야."},{"who":"민준","text":"설탕의 무게는 밀가루 1 kg의 무게와 비슷해서 약 1 kg이야."},{"who":"서윤","text":"배의 무게는 200 g인 사과 2개와 100 g인 귤 1개를 합한 무게와 비슷해서 약 500 g이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_challenge#1','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',2,'mc','auto','친구는 필통의 무게가 약 100 g인 컵과 약 300 g인 물통을 합한 무게와 비슷할 것 같다고 어림했어요. 친구가 어림한 필통의 무게는 어느 것인가요?',ARRAY['M3-2-u5-X08','M3-2-u5-X14','M3-2-u5-X09']::text[],false,'{"seq":1,"concept":"M3-2-u5-C8","difficulty":2,"kind":"mc","stem":"친구는 필통의 무게가 약 100 g인 컵과 약 300 g인 물통을 합한 무게와 비슷할 것 같다고 어림했어요. 친구가 어림한 필통의 무게는 어느 것인가요?","options":[{"t":"약 400 g","correct":true},{"t":"약 300 g","mis":"M3-2-u5-X08"},{"t":"약 200 g","mis":"M3-2-u5-X14"},{"t":"약 400 kg","mis":"M3-2-u5-X09"}],"explanation":["무게를 알고 있는 두 물건을 합하여 어림했어요.","100 g + 300 g = 400 g.","어림한 무게는 약 400 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_challenge#2','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',2,'sa','auto','빨랫비누 한 봉지에 약 100 g인 비누가 들어 있어요. 비누 6개가 든 묶음과 4개가 든 묶음을 합한 무게와 비슷하다고 어림하면, 빨랫비누 한 봉지는 약 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C8","difficulty":2,"kind":"sa","stem":"빨랫비누 한 봉지에 약 100 g인 비누가 들어 있어요. 비누 6개가 든 묶음과 4개가 든 묶음을 합한 무게와 비슷하다고 어림하면, 빨랫비누 한 봉지는 약 몇 g인가요? 숫자로 쓰세요.","answer":["1000"],"explanation":["비누는 6개와 4개 — 모두 10개예요.","100 g이 10개 — 100 × 10 = 1000.","약 1000 g이에요."],"variant_rule":{"alt":[{"stem":"서윤이는 배의 무게가 200 g인 사과 2개와 100 g인 귤 1개를 합한 무게와 비슷하다고 어림했어요. 서윤이가 어림한 배의 무게는 약 몇 g인가요? 숫자로 쓰세요.","answer":["500"],"explanation":["사과 2개는 200 + 200 = 400(g)이에요.","귤 1개를 더하면 400 + 100 = 500.","약 500 g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_challenge#3','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',3,'sa','auto','공책의 무게를 약 120 g으로 어림하고 재어 보니 80 g이었어요. 어림한 무게와 잰 무게의 차는 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u5-C8","difficulty":3,"kind":"sa","stem":"공책의 무게를 약 120 g으로 어림하고 재어 보니 80 g이었어요. 어림한 무게와 잰 무게의 차는 몇 g인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["어림한 무게 약 120 g, 잰 무게 80 g.","120 − 80 = 40.","차는 40 g이에요."],"variant_rule":{"alt":[{"stem":"필통의 무게를 약 400 g으로 어림하고 재어 보니 360 g이었어요. 어림한 무게와 잰 무게의 차는 몇 g인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["어림한 무게 약 400 g, 잰 무게 360 g.","400 − 360 = 40.","차는 40 g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_challenge#4','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',3,'ox','auto','필통의 무게를 약 400 g으로 어림했는데 재어 보니 360 g이었어요. 친구가 「어림한 무게와 잰 무게가 다르니까 어림을 잘못한 거야.」라고 했어요. 바르게 말했어요.',ARRAY['M3-2-u5-X08']::text[],true,'{"seq":4,"concept":"M3-2-u5-C8","difficulty":3,"kind":"ox","stem":"필통의 무게를 약 400 g으로 어림했는데 재어 보니 360 g이었어요. 친구가 「어림한 무게와 잰 무게가 다르니까 어림을 잘못한 거야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"어림은 아는 무게와 견주어 얼마쯤인지 나타낸 것이라 잰 무게와 달라도 돼서","correct":true},{"t":"어림한 무게는 잰 무게와 꼭 같아야 해서","mis":"M3-2-u5-X08"}],"mis":"M3-2-u5-X08","explanation":["어림은 저울 없이 아는 무게와 견주어 얼마쯤인지 생각하는 거예요.","400 g과 360 g의 차는 40 g이에요.","근거가 타당하면 잘 어림한 거예요 — 바르지 않아요."],"variant_rule":{"alt":[{"stem":"책가방의 무게를 약 3 kg으로 어림하고 재어 보니 3 kg이었어요. 친구가 「어림한 무게와 잰 무게가 같을 때만 어림을 잘한 거야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"어림은 근거가 타당한지가 중요해서","correct":true},{"t":"어림한 무게는 잰 무게와 꼭 같아야 해서","mis":"M3-2-u5-X08"}],"explanation":["이번에는 어림한 무게와 잰 무게가 같았어요.","하지만 다르더라도 근거가 타당하면 잘 어림한 거예요.","같을 때만 잘한 것은 아니에요 — 바르지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_challenge#5','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',3,'mc','auto','무게의 단위가 g인 것끼리 모은 것은 어느 것인가요? (기린: 2 ?, 연필: 8 ?, 강아지: 2 ?, 쥐: 150 ?, 자동차: 1 ?, 지우개: 20 ?, 하마: 3 ?)',ARRAY['M3-2-u5-X09']::text[],false,'{"seq":5,"concept":"M3-2-u5-C8","difficulty":3,"kind":"mc","stem":"무게의 단위가 g인 것끼리 모은 것은 어느 것인가요? (기린: 2 ?, 연필: 8 ?, 강아지: 2 ?, 쥐: 150 ?, 자동차: 1 ?, 지우개: 20 ?, 하마: 3 ?)","options":[{"t":"연필, 쥐, 지우개","correct":true},{"t":"기린, 자동차, 하마","mis":"M3-2-u5-X09"},{"t":"강아지, 연필, 쥐","mis":"M3-2-u5-X09"},{"t":"연필, 하마, 지우개","mis":"M3-2-u5-X09"}],"explanation":["가벼운 연필 8 g, 쥐 150 g, 지우개 20 g은 g이 알맞아요.","강아지 2 kg은 kg이 알맞아요.","기린 2 t, 자동차 1 t, 하마 3 t은 t이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_challenge#6','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',3,'mc','auto','두 친구가 책의 무게를 어림했어요. 어림한 방법을 더 알맞게 설명한 것은 어느 것인가요?',ARRAY['M3-2-u5-X08','M3-2-u5-X09']::text[],false,'{"seq":6,"concept":"M3-2-u5-C8","difficulty":3,"kind":"mc","stem":"두 친구가 책의 무게를 어림했어요. 어림한 방법을 더 알맞게 설명한 것은 어느 것인가요?","options":[{"t":"「책의 무게는 300 g인 내 물통과 비슷한 것 같아서 약 300 g이라고 어림했어.」","correct":true},{"t":"「책의 무게는 들어 보았을 때 약 300 g인 것 같아.」","mis":"M3-2-u5-X08"},{"t":"「책의 무게는 300 g이야.」","mis":"M3-2-u5-X08"},{"t":"「책의 무게는 약 300 kg이야.」","mis":"M3-2-u5-X09"}],"explanation":["두 친구 모두 약 300 g으로 어림했어요.","첫째 설명은 무게를 알고 있는 300 g 물통과 견주었다는 근거가 있어요.","어림은 근거가 타당한지가 중요해요 — 어림한 값에는 「약」을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_challenge#7','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',3,'mc','auto','알맞은 단위를 바르게 쓴 것은 어느 것인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],false,'{"seq":7,"concept":"M3-2-u5-C8","difficulty":3,"kind":"mc","stem":"알맞은 단위를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"축구공의 무게: 약 450 g","correct":true},{"t":"코끼리의 무게: 약 3 kg","mis":"M3-2-u5-X09"},{"t":"고양이의 무게: 약 2 t","mis":"M3-2-u5-X09"},{"t":"축구공의 무게: 약 450 mL","mis":"M3-2-u5-X10"}],"explanation":["축구공은 한 손으로 들 수 있어요 — 약 450 g.","코끼리는 아주 무거워요 — 약 3 t, 고양이는 약 2 kg이에요.","mL는 들이의 단위라 무게에 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_challenge#8','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',4,'essay','teacher','은비는 빨랫비누가 10개 들어 있는 봉지의 무게를 어림하려고 해요. 비누 한 개는 약 100 g이에요. 봉지의 무게를 어림하는 방법 세 가지를 쓰고, 어림한 무게를 나타내 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u5-C8","difficulty":4,"kind":"essay","stem":"은비는 빨랫비누가 10개 들어 있는 봉지의 무게를 어림하려고 해요. 비누 한 개는 약 100 g이에요. 봉지의 무게를 어림하는 방법 세 가지를 쓰고, 어림한 무게를 나타내 보세요.","answer_guide":{"answer":"예: ① 약 100 g인 비누가 10개 들어 있으니 1000 g 정도 된다. ② 밀가루 1 kg의 무게와 비슷할 것 같다. ③ 비누 6개 묶음과 4개 묶음을 합한 무게와 비슷하다. 어림한 무게는 약 1000 g(약 1 kg)이다.","scoring_points":["100 g이 10개라 1000 g 정도라고 썼는가","아는 무게(밀가루 1 kg)와 견주는 방법을 썼는가","「약」을 붙여 약 1000 g(약 1 kg)으로 나타냈는가"]},"explanation":["몇 개 — 100 g이 10개면 1000 g.","견주기 — 밀가루 1 kg과 비슷해요.","묶기 — 6개와 4개를 합해요. 어림한 무게는 약 1 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_challenge#9','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',4,'essay','teacher','정후는 「위인전의 무게는 50 g인 공책 10권의 무게와 비슷해서 약 5 kg이야.」라고 어림했어요. 잘못된 곳을 찾아 바르게 고쳐 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u5-C8","difficulty":4,"kind":"essay","stem":"정후는 「위인전의 무게는 50 g인 공책 10권의 무게와 비슷해서 약 5 kg이야.」라고 어림했어요. 잘못된 곳을 찾아 바르게 고쳐 보세요.","answer_guide":{"answer":"예: 50 g인 공책 10권의 무게는 50 × 10 = 500(g)이므로 약 5 kg이 아니라 약 500 g이다. 「위인전의 무게는 50 g인 공책 10권의 무게와 비슷해서 약 500 g이야.」라고 고친다.","scoring_points":["50 g이 10개면 500 g이라고 구했는가","약 5 kg이 잘못이라고 썼는가","약 500 g으로 고쳤는가"]},"explanation":["50 × 10 = 500.","500 g은 1 kg보다 가벼워요 — 5 kg이 아니에요.","「약 500 g이야」로 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L07_challenge#10','math',3,2,'u5','L07','tb_g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',4,'essay','teacher','서준이네 동네 행정복지센터에서는 재활용품을 정해진 무게만큼 모아 오면 알뜰 시장 교환권으로 바꾸어 줘요. 은비는 빨랫비누가 2 kg 정도 들어 있는 봉지를 고르려고 해요. 두 상황 가운데 무게를 어림해도 되는 상황과 정확하게 재어야 하는 상황을 고르고 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u5-C8","difficulty":4,"kind":"essay","stem":"서준이네 동네 행정복지센터에서는 재활용품을 정해진 무게만큼 모아 오면 알뜰 시장 교환권으로 바꾸어 줘요. 은비는 빨랫비누가 2 kg 정도 들어 있는 봉지를 고르려고 해요. 두 상황 가운데 무게를 어림해도 되는 상황과 정확하게 재어야 하는 상황을 고르고 까닭을 써 보세요.","answer_guide":{"answer":"예: 빨랫비누 봉지를 고를 때는 2 kg 정도면 되므로 약 1 kg인 물건 2개와 견주어 어림해도 된다. 재활용품을 교환권으로 바꿀 때는 정해진 무게가 되는지 알아야 하므로 저울로 정확하게 재어야 한다.","scoring_points":["빨랫비누 봉지 고르기는 어림해도 된다고 했는가","재활용품 교환은 정확히 재야 한다고 했는가","각각의 까닭을 썼는가"]},"explanation":["「정도」면 되는 상황 — 어림해요.","정해진 무게를 넘는지 따져야 하는 상황 — 저울로 정확히 재요.","상황에 따라 어림과 측정을 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_basic#1','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',1,'sa','auto','1 kg 500 g + 2 kg 300 g의 세로셈이에요. g 자리의 ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u5-C9","difficulty":1,"kind":"sa","stem":"1 kg 500 g + 2 kg 300 g의 세로셈이에요. g 자리의 ?에 알맞은 수를 쓰세요.","answer":["800"],"explanation":["같은 단위의 수끼리 계산해요.","g끼리 500 + 300 = 800, kg끼리 1 + 2 = 3.","1 kg 500 g + 2 kg 300 g = 3 kg 800 g."],"asset":{"type":"expr_grid","rows":[["","1","kg","500","g"],["+","2","kg","300","g"],["","3","kg",null,"g"]]},"variant_rule":{"alt":[{"stem":"2 kg 500 g + 1 kg 200 g의 세로셈이에요. g 자리의 ?에 알맞은 수를 쓰세요.","answer":["700"],"explanation":["같은 단위의 수끼리 계산해요.","g끼리 500 + 200 = 700, kg끼리 2 + 1 = 3.","2 kg 500 g + 1 kg 200 g = 3 kg 700 g."],"asset":{"type":"expr_grid","rows":[["","2","kg","500","g"],["+","1","kg","200","g"],["","3","kg",null,"g"]]}},{"stem":"1 kg 300 g + 6 kg 100 g의 세로셈이에요. g 자리의 ?에 알맞은 수를 쓰세요.","answer":["400"],"explanation":["같은 단위의 수끼리 계산해요.","g끼리 300 + 100 = 400, kg끼리 1 + 6 = 7.","1 kg 300 g + 6 kg 100 g = 7 kg 400 g."],"asset":{"type":"expr_grid","rows":[["","1","kg","300","g"],["+","6","kg","100","g"],["","7","kg",null,"g"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_basic#2','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',1,'sa','auto','3 kg 800 g − 1 kg 400 g의 세로셈이에요. kg 자리의 ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C9","difficulty":1,"kind":"sa","stem":"3 kg 800 g − 1 kg 400 g의 세로셈이에요. kg 자리의 ?에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["같은 단위의 수끼리 계산해요.","g끼리 800 − 400 = 400, kg끼리 3 − 1 = 2.","3 kg 800 g − 1 kg 400 g = 2 kg 400 g."],"asset":{"type":"expr_grid","rows":[["","3","kg","800","g"],["−","1","kg","400","g"],["",null,"kg","400","g"]]},"variant_rule":{"alt":[{"stem":"4 kg 700 g − 3 kg 600 g의 세로셈이에요. kg 자리의 ?에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["같은 단위의 수끼리 계산해요.","g끼리 700 − 600 = 100, kg끼리 4 − 3 = 1.","4 kg 700 g − 3 kg 600 g = 1 kg 100 g."],"asset":{"type":"expr_grid","rows":[["","4","kg","700","g"],["−","3","kg","600","g"],["",null,"kg","100","g"]]}},{"stem":"9 kg 700 g − 2 kg 400 g의 세로셈이에요. kg 자리의 ?에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["같은 단위의 수끼리 계산해요.","g끼리 700 − 400 = 300, kg끼리 9 − 2 = 7.","9 kg 700 g − 2 kg 400 g = 7 kg 300 g."],"asset":{"type":"expr_grid","rows":[["","9","kg","700","g"],["−","2","kg","400","g"],["",null,"kg","300","g"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_basic#3','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',1,'mc','auto','계산해 보세요. 5 kg 200 g + 3 kg 400 g',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],true,'{"seq":3,"concept":"M3-2-u5-C9","difficulty":1,"kind":"mc","stem":"계산해 보세요. 5 kg 200 g + 3 kg 400 g","options":[{"t":"8 kg 600 g","correct":true},{"t":"1 kg 800 g","mis":"M3-2-u5-X14"},{"t":"8 kg 700 g","mis":"M3-2-u5-X24"},{"t":"8 kg 500 g","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","g끼리 200 + 400 = 600, kg끼리 5 + 3 = 8.","5 kg 200 g + 3 kg 400 g = 8 kg 600 g."],"variant_rule":{"alt":[{"stem":"계산해 보세요. 7 kg 100 g + 2 kg 200 g","options":[{"t":"9 kg 300 g","correct":true},{"t":"4 kg 900 g","mis":"M3-2-u5-X14"},{"t":"9 kg 400 g","mis":"M3-2-u5-X24"},{"t":"9 kg 200 g","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","g끼리 100 + 200 = 300, kg끼리 7 + 2 = 9.","7 kg 100 g + 2 kg 200 g = 9 kg 300 g."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_basic#4','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',1,'mc','auto','계산해 보세요. 8 kg 700 g − 5 kg 300 g',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],true,'{"seq":4,"concept":"M3-2-u5-C9","difficulty":1,"kind":"mc","stem":"계산해 보세요. 8 kg 700 g − 5 kg 300 g","options":[{"t":"3 kg 400 g","correct":true},{"t":"14 kg","mis":"M3-2-u5-X14"},{"t":"3 kg 500 g","mis":"M3-2-u5-X24"},{"t":"3 kg 300 g","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","g끼리 700 − 300 = 400, kg끼리 8 − 5 = 3.","8 kg 700 g − 5 kg 300 g = 3 kg 400 g."],"variant_rule":{"alt":[{"stem":"계산해 보세요. 6 kg 800 g − 4 kg 500 g","options":[{"t":"2 kg 300 g","correct":true},{"t":"11 kg 300 g","mis":"M3-2-u5-X14"},{"t":"2 kg 400 g","mis":"M3-2-u5-X24"},{"t":"2 kg 200 g","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","g끼리 800 − 500 = 300, kg끼리 6 − 4 = 2.","6 kg 800 g − 4 kg 500 g = 2 kg 300 g."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_basic#5','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',2,'mc','auto','채원이와 도윤이는 작아진 옷을 모아 함께 기부하려고 해요. 채원이는 1 kg 500 g, 도윤이는 2 kg 300 g의 옷을 모았어요. 모은 옷의 무게는 모두 얼마인가요?',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],true,'{"seq":5,"concept":"M3-2-u5-C9","difficulty":2,"kind":"mc","stem":"채원이와 도윤이는 작아진 옷을 모아 함께 기부하려고 해요. 채원이는 1 kg 500 g, 도윤이는 2 kg 300 g의 옷을 모았어요. 모은 옷의 무게는 모두 얼마인가요?","options":[{"t":"3 kg 800 g","correct":true},{"t":"800 g","mis":"M3-2-u5-X14"},{"t":"3 kg 900 g","mis":"M3-2-u5-X24"},{"t":"3 kg 700 g","mis":"M3-2-u5-X24"}],"explanation":["채원이가 모은 옷의 무게와 도윤이가 모은 옷의 무게를 더해요 — 식은 1 kg 500 g + 2 kg 300 g.","g끼리 500 + 300 = 800, kg끼리 1 + 2 = 3.","1 kg 500 g + 2 kg 300 g = 3 kg 800 g — 모은 옷은 모두 3 kg 800 g이에요."],"variant_rule":{"alt":[{"stem":"옷을 기부하기 위해 민서는 3 kg 500 g, 도윤이는 2 kg 300 g의 옷을 모았어요. 모은 옷의 무게는 모두 얼마인가요?","options":[{"t":"5 kg 800 g","correct":true},{"t":"1 kg 200 g","mis":"M3-2-u5-X14"},{"t":"5 kg 900 g","mis":"M3-2-u5-X24"},{"t":"5 kg 700 g","mis":"M3-2-u5-X24"}],"explanation":["두 사람이 모은 옷의 무게를 더해요 — 식은 3 kg 500 g + 2 kg 300 g.","g끼리 500 + 300 = 800, kg끼리 3 + 2 = 5.","3 kg 500 g + 2 kg 300 g = 5 kg 800 g — 모은 옷은 모두 5 kg 800 g이에요."]},{"stem":"도아는 재활용품을 2 kg 600 g 모았고, 세희는 재활용품을 3 kg 200 g 모았어요. 도아와 세희가 모은 재활용품의 무게는 모두 얼마인가요?","options":[{"t":"5 kg 800 g","correct":true},{"t":"600 g","mis":"M3-2-u5-X14"},{"t":"5 kg 900 g","mis":"M3-2-u5-X24"},{"t":"5 kg 700 g","mis":"M3-2-u5-X24"}],"explanation":["두 사람이 모은 무게를 더해요 — 식은 2 kg 600 g + 3 kg 200 g.","g끼리 600 + 200 = 800, kg끼리 2 + 3 = 5.","2 kg 600 g + 3 kg 200 g = 5 kg 800 g — 재활용품은 모두 5 kg 800 g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_basic#6','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',2,'mc','auto','쌀 3 kg 800 g 중에서 1 kg 400 g을 사용하여 떡을 만들었어요. 떡을 만들고 남은 쌀의 무게는 얼마인가요?',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],true,'{"seq":6,"concept":"M3-2-u5-C9","difficulty":2,"kind":"mc","stem":"쌀 3 kg 800 g 중에서 1 kg 400 g을 사용하여 떡을 만들었어요. 떡을 만들고 남은 쌀의 무게는 얼마인가요?","options":[{"t":"2 kg 400 g","correct":true},{"t":"5 kg 200 g","mis":"M3-2-u5-X14"},{"t":"2 kg 500 g","mis":"M3-2-u5-X24"},{"t":"2 kg 300 g","mis":"M3-2-u5-X24"}],"explanation":["처음에 있던 쌀의 무게에서 사용한 쌀의 무게를 빼요 — 식은 3 kg 800 g − 1 kg 400 g.","g끼리 800 − 400 = 400, kg끼리 3 − 1 = 2.","3 kg 800 g − 1 kg 400 g = 2 kg 400 g — 남은 쌀은 2 kg 400 g이에요."],"variant_rule":{"alt":[{"stem":"민준이는 화분에 나무를 심기 위해 흙 8 kg 650 g 중에서 4 kg 300 g을 사용했어요. 남은 흙의 무게는 얼마인가요?","options":[{"t":"4 kg 350 g","correct":true},{"t":"12 kg 950 g","mis":"M3-2-u5-X14"},{"t":"4 kg 450 g","mis":"M3-2-u5-X24"},{"t":"4 kg 250 g","mis":"M3-2-u5-X24"}],"explanation":["처음 흙의 무게에서 사용한 흙의 무게를 빼요 — 식은 8 kg 650 g − 4 kg 300 g.","g끼리 650 − 300 = 350, kg끼리 8 − 4 = 4.","8 kg 650 g − 4 kg 300 g = 4 kg 350 g — 남은 흙은 4 kg 350 g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_basic#7','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',2,'sa','auto','채원이와 도윤이가 모은 옷의 무게만큼 저울에 추를 놓았더니 1 kg짜리 추 3개와 100 g짜리 추 8개와 무게가 같았어요. 모은 옷의 무게는 몇 g인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M3-2-u5-C9","difficulty":2,"kind":"sa","stem":"채원이와 도윤이가 모은 옷의 무게만큼 저울에 추를 놓았더니 1 kg짜리 추 3개와 100 g짜리 추 8개와 무게가 같았어요. 모은 옷의 무게는 몇 g인가요? 숫자로 쓰세요.","answer":["3800"],"explanation":["1 kg짜리 추 3개는 3 kg = 3000 g이에요.","100 g짜리 추 8개는 800 g이에요.","3000 g + 800 g = 3800 g — 3 kg 800 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_basic#8','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',2,'sa','auto','텃밭에서 준우는 당근을 4 kg 100 g 캤고, 소율이는 당근을 5 kg 800 g 캤어요. 준우와 소율이가 캔 당근의 무게의 합은 9 kg □ g이에요. □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u5-C9","difficulty":2,"kind":"sa","stem":"텃밭에서 준우는 당근을 4 kg 100 g 캤고, 소율이는 당근을 5 kg 800 g 캤어요. 준우와 소율이가 캔 당근의 무게의 합은 9 kg □ g이에요. □ 안에 알맞은 수를 쓰세요.","answer":["900"],"explanation":["두 사람이 캔 당근의 무게를 더해요 — 식은 4 kg 100 g + 5 kg 800 g.","g끼리 100 + 800 = 900, kg끼리 4 + 5 = 9.","4 kg 100 g + 5 kg 800 g = 9 kg 900 g — 당근의 무게의 합은 9 kg 900 g이에요."],"variant_rule":{"alt":[{"stem":"여행 가방이 2개 있어요. 한 가방은 5 kg 450 g, 다른 가방은 4 kg 200 g이에요. 여행 가방의 무게는 모두 9 kg □ g이에요. □ 안에 알맞은 수를 쓰세요.","answer":["650"],"explanation":["두 가방의 무게를 더해요 — 식은 5 kg 450 g + 4 kg 200 g.","g끼리 450 + 200 = 650, kg끼리 5 + 4 = 9.","5 kg 450 g + 4 kg 200 g = 9 kg 650 g — 여행 가방은 모두 9 kg 650 g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_basic#9','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',2,'sa','auto','텃밭에서 준우는 당근을 4 kg 100 g 캤고, 소율이는 당근을 5 kg 800 g 캤어요. 준우와 소율이가 캔 당근의 무게의 차는 몇 g인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u5-C9","difficulty":2,"kind":"sa","stem":"텃밭에서 준우는 당근을 4 kg 100 g 캤고, 소율이는 당근을 5 kg 800 g 캤어요. 준우와 소율이가 캔 당근의 무게의 차는 몇 g인가요? 숫자로 쓰세요.","answer":["1700"],"explanation":["무거운 쪽에서 가벼운 쪽을 빼요 — 식은 5 kg 800 g − 4 kg 100 g.","g끼리 800 − 100 = 700, kg끼리 5 − 4 = 1.","5 kg 800 g − 4 kg 100 g = 1 kg 700 g — 1700 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_basic#10','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',3,'error','auto','준우(4 kg 100 g)와 소율이(5 kg 800 g)가 캔 당근의 무게의 차를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u5-X24','M3-2-u5-X20']::text[],false,'{"seq":10,"concept":"M3-2-u5-C9","difficulty":3,"kind":"error","stem":"준우(4 kg 100 g)와 소율이(5 kg 800 g)가 캔 당근의 무게의 차를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「5 kg 800 g − 4 kg 100 g = 1 kg 900 g이야」","correct":true,"mis_target":"M3-2-u5-X24"},{"t":"채원 — 「g끼리 800 − 100 = 700이야」","mis":"M3-2-u5-X20"},{"t":"민서 — 「kg끼리 5 − 4 = 1이야」","mis":"M3-2-u5-X20"},{"t":"소율 — 「무게의 차는 1 kg 700 g이야」","mis":"M3-2-u5-X20"}],"explanation":["g끼리 800 − 100 = 700, kg끼리 5 − 4 = 1.","5 kg 800 g − 4 kg 100 g = 1 kg 700 g.","도윤이는 식은 바르게 세웠지만 g끼리의 셈이 틀렸어요 — 같은 단위의 수끼리 따로 셈해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_challenge#1','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',2,'mc','auto','계산해 보세요. 9 kg 700 g − 2 kg 400 g',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],true,'{"seq":1,"concept":"M3-2-u5-C9","difficulty":2,"kind":"mc","stem":"계산해 보세요. 9 kg 700 g − 2 kg 400 g","options":[{"t":"7 kg 300 g","correct":true},{"t":"12 kg 100 g","mis":"M3-2-u5-X14"},{"t":"7 kg 400 g","mis":"M3-2-u5-X24"},{"t":"7 kg 200 g","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","g끼리 700 − 400 = 300, kg끼리 9 − 2 = 7.","9 kg 700 g − 2 kg 400 g = 7 kg 300 g."],"variant_rule":{"alt":[{"stem":"계산해 보세요. 1 kg 300 g + 6 kg 100 g","options":[{"t":"7 kg 400 g","correct":true},{"t":"4 kg 800 g","mis":"M3-2-u5-X14"},{"t":"7 kg 500 g","mis":"M3-2-u5-X24"},{"t":"7 kg 300 g","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","g끼리 300 + 100 = 400, kg끼리 1 + 6 = 7.","1 kg 300 g + 6 kg 100 g = 7 kg 400 g."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_challenge#2','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',2,'sa','auto','친구 3명의 가방 무게를 저울로 재었더니 각각 4 kg 100 g, 1 kg 500 g, 3 kg 200 g이었어요. 세 가방의 무게를 모두 더하면 몇 g인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M3-2-u5-C9","difficulty":2,"kind":"sa","stem":"친구 3명의 가방 무게를 저울로 재었더니 각각 4 kg 100 g, 1 kg 500 g, 3 kg 200 g이었어요. 세 가방의 무게를 모두 더하면 몇 g인가요? 숫자로 쓰세요.","answer":["8800"],"explanation":["g끼리 100 + 500 + 200 = 800.","kg끼리 4 + 1 + 3 = 8.","4 kg 100 g + 1 kg 500 g + 3 kg 200 g = 8 kg 800 g = 8800 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_challenge#3','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',3,'sa','auto','채소 상자가 3개 있어요. 오이 상자는 5 kg 650 g, 양파 상자는 5 kg 605 g, 당근 상자는 3 kg 120 g이에요. 가장 무거운 상자와 가장 가벼운 상자의 무게의 차는 몇 g인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u5-C9","difficulty":3,"kind":"sa","stem":"채소 상자가 3개 있어요. 오이 상자는 5 kg 650 g, 양파 상자는 5 kg 605 g, 당근 상자는 3 kg 120 g이에요. 가장 무거운 상자와 가장 가벼운 상자의 무게의 차는 몇 g인가요? 숫자로 쓰세요.","answer":["2530"],"explanation":["가장 무거운 상자는 오이(5 kg 650 g), 가장 가벼운 상자는 당근(3 kg 120 g)이에요 — 650 g > 605 g.","g끼리 650 − 120 = 530, kg끼리 5 − 3 = 2.","5 kg 650 g − 3 kg 120 g = 2 kg 530 g = 2530 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_challenge#4','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',3,'sa','auto','9 kg 500 g까지 담을 수 있는 상자에 6 kg짜리 수박 1통과 200 g짜리 사과 2개가 들어 있어요. 상자에 더 담을 수 있는 과일의 무게는 몇 g인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u5-C9","difficulty":3,"kind":"sa","stem":"9 kg 500 g까지 담을 수 있는 상자에 6 kg짜리 수박 1통과 200 g짜리 사과 2개가 들어 있어요. 상자에 더 담을 수 있는 과일의 무게는 몇 g인가요? 숫자로 쓰세요.","answer":["3100"],"explanation":["상자에 담은 과일은 6 kg + 200 g + 200 g = 6 kg 400 g이에요.","9 kg 500 g − 6 kg 400 g = 3 kg 100 g.","3 kg 100 g = 3100 g을 더 담을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_challenge#5','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',3,'error','auto','지아는 밀가루 1 kg 200 g과 쌀가루 1050 g을 섞어서 빵을 만들었어요. 무게의 합을 구하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u5-X05','M3-2-u5-X20']::text[],false,'{"seq":5,"concept":"M3-2-u5-C9","difficulty":3,"kind":"error","stem":"지아는 밀가루 1 kg 200 g과 쌀가루 1050 g을 섞어서 빵을 만들었어요. 무게의 합을 구하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준우 — 「1050 g은 1 kg 500 g이야」","correct":true,"mis_target":"M3-2-u5-X05"},{"t":"소율 — 「1050 g은 1 kg 50 g이야」","mis":"M3-2-u5-X20"},{"t":"채원 — 「1 kg 200 g + 1 kg 50 g = 2 kg 250 g이야」","mis":"M3-2-u5-X20"},{"t":"도윤 — 「g끼리 200 + 50 = 250이야」","mis":"M3-2-u5-X20"}],"explanation":["1 kg = 1000 g이에요.","1050 g = 1000 g + 50 g = 1 kg 50 g.","준우는 0을 빠뜨렸어요 — 1 kg 200 g + 1 kg 50 g = 2 kg 250 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_challenge#6','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',3,'mc','auto','지아는 밀가루 1 kg 200 g과 쌀가루 1050 g을 섞어서 빵을 만들었어요. 사용한 밀가루와 쌀가루의 무게의 합은 몇 kg 몇 g인가요?',ARRAY['M3-2-u5-X05','M3-2-u5-X11','M3-2-u5-X14']::text[],true,'{"seq":6,"concept":"M3-2-u5-C9","difficulty":3,"kind":"mc","stem":"지아는 밀가루 1 kg 200 g과 쌀가루 1050 g을 섞어서 빵을 만들었어요. 사용한 밀가루와 쌀가루의 무게의 합은 몇 kg 몇 g인가요?","options":[{"t":"2 kg 250 g","correct":true},{"t":"2 kg 700 g","mis":"M3-2-u5-X05"},{"t":"1 kg 1250 g","mis":"M3-2-u5-X11"},{"t":"150 g","mis":"M3-2-u5-X14"}],"explanation":["두 가루의 무게를 더해요 — 식은 1 kg 200 g + 1 kg 50 g.","1050 g = 1 kg 50 g — 바꾸어서 g끼리 200 + 50 = 250, kg끼리 1 + 1 = 2.","1 kg 200 g + 1 kg 50 g = 2 kg 250 g — 무게의 합은 2 kg 250 g이에요."],"variant_rule":{"alt":[{"stem":"장난감을 정리함에 담아 무게를 재었더니 3850 g이었어요. 정리함만의 무게는 1600 g이에요. 장난감의 무게는 몇 kg 몇 g인가요?","options":[{"t":"2 kg 250 g","correct":true},{"t":"2 kg 25 g","mis":"M3-2-u5-X05"},{"t":"5 kg 450 g","mis":"M3-2-u5-X14"},{"t":"22 kg 50 g","mis":"M3-2-u5-X04"}],"explanation":["전체 무게에서 정리함의 무게를 빼요 — 식은 3 kg 850 g − 1 kg 600 g.","3850 g = 3 kg 850 g, 1600 g = 1 kg 600 g — 바꾸어서 g끼리 850 − 600 = 250, kg끼리 3 − 1 = 2.","3 kg 850 g − 1 kg 600 g = 2 kg 250 g — 장난감은 2 kg 250 g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_challenge#7','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',3,'ox','auto','8 kg 650 g − 4 kg 300 g을 계산할 때 g 단위의 수끼리 빼고, kg 단위의 수끼리 빼요.',ARRAY['M3-2-u5-X11']::text[],true,'{"seq":7,"concept":"M3-2-u5-C9","difficulty":3,"kind":"ox","stem":"8 kg 650 g − 4 kg 300 g을 계산할 때 g 단위의 수끼리 빼고, kg 단위의 수끼리 빼요.","answer":"O","reason_options":[{"t":"같은 단위의 수끼리 계산해야 해서","correct":true},{"t":"단위와 상관없이 앞의 수부터 모두 빼면 되어서","mis":"M3-2-u5-X11"}],"mis":"M3-2-u5-X11","explanation":["g은 g끼리, kg은 kg끼리 빼요.","g끼리 650 − 300 = 350, kg끼리 8 − 4 = 4.","8 kg 650 g − 4 kg 300 g = 4 kg 350 g — 맞아요."],"variant_rule":{"alt":[{"stem":"5 kg 450 g + 4 kg 200 g을 계산할 때 g 단위의 수끼리, kg 단위의 수끼리 더해요.","answer":"O","reason_options":[{"t":"같은 단위의 수끼리 계산해야 해서","correct":true},{"t":"단위와 상관없이 앞의 수부터 모두 더하면 되어서","mis":"M3-2-u5-X11"}],"explanation":["g은 g끼리, kg은 kg끼리 더해요.","g끼리 450 + 200 = 650, kg끼리 5 + 4 = 9.","5 kg 450 g + 4 kg 200 g = 9 kg 650 g — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_challenge#8','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',4,'essay','teacher','채소 상자가 3개 있어요. 오이 상자는 5 kg 650 g, 양파 상자는 5 kg 605 g, 당근 상자는 3 kg 120 g이에요. 가장 무거운 상자와 가장 가벼운 상자의 무게의 차는 몇 g인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u5-C9","difficulty":4,"kind":"essay","stem":"채소 상자가 3개 있어요. 오이 상자는 5 kg 650 g, 양파 상자는 5 kg 605 g, 당근 상자는 3 kg 120 g이에요. 가장 무거운 상자와 가장 가벼운 상자의 무게의 차는 몇 g인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 오이 5 kg 650 g과 양파 5 kg 605 g은 kg이 같고 650 g > 605 g이므로 오이 상자가 가장 무겁다. 가장 가벼운 상자는 당근 3 kg 120 g이다. 5 kg 650 g − 3 kg 120 g = 2 kg 530 g = 2530 g이다. 답: 2530 g","scoring_points":["가장 무거운 상자(오이)와 가장 가벼운 상자(당근)를 찾았는가","5 kg 650 g − 3 kg 120 g = 2 kg 530 g을 구했는가","2530 g으로 나타냈는가"]},"explanation":["650 g > 605 g — 오이 상자가 가장 무거워요.","5 kg 650 g − 3 kg 120 g = 2 kg 530 g.","2 kg 530 g = 2530 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_challenge#9','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',4,'essay','teacher','친구가 준우(4 kg 100 g)와 소율이(5 kg 800 g)가 캔 당근의 무게의 차를 「5 kg 800 g − 4 kg 100 g = 1 kg 900 g」이라고 구했어요. 무엇이 잘못되었는지 찾아 바르게 계산하고, 확인하는 방법도 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u5-C9","difficulty":4,"kind":"essay","stem":"친구가 준우(4 kg 100 g)와 소율이(5 kg 800 g)가 캔 당근의 무게의 차를 「5 kg 800 g − 4 kg 100 g = 1 kg 900 g」이라고 구했어요. 무엇이 잘못되었는지 찾아 바르게 계산하고, 확인하는 방법도 써 보세요.","answer_guide":{"answer":"예: 식은 바르게 세웠지만 g끼리 800 − 100 = 700인데 900으로 잘못 계산했다. 바르게 계산하면 1 kg 700 g이다. 4 kg 100 g + 1 kg 700 g = 5 kg 800 g이 되는지 덧셈으로 확인할 수 있다.","scoring_points":["g끼리의 셈이 틀렸다고 찾았는가","1 kg 700 g을 구했는가","덧셈으로 확인했는가"]},"explanation":["g끼리 800 − 100 = 700, kg끼리 5 − 4 = 1.","5 kg 800 g − 4 kg 100 g = 1 kg 700 g.","4 kg 100 g + 1 kg 700 g = 5 kg 800 g으로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L08_challenge#10','math',3,2,'u5','L08','tb_g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',4,'essay','teacher','9 kg 500 g까지 담을 수 있는 상자에 6 kg짜리 수박 1통과 200 g짜리 사과 2개가 들어 있어요. 상자에 더 담을 수 있는 과일의 무게는 몇 kg 몇 g인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u5-C9","difficulty":4,"kind":"essay","stem":"9 kg 500 g까지 담을 수 있는 상자에 6 kg짜리 수박 1통과 200 g짜리 사과 2개가 들어 있어요. 상자에 더 담을 수 있는 과일의 무게는 몇 kg 몇 g인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 상자에 담은 과일의 무게는 6 kg + 200 g + 200 g = 6 kg 400 g이다. 상자에는 9 kg 500 g까지 담을 수 있으므로 9 kg 500 g − 6 kg 400 g = 3 kg 100 g을 더 담을 수 있다. 답: 3 kg 100 g","scoring_points":["담은 과일의 무게 6 kg 400 g을 구했는가","9 kg 500 g에서 빼야 한다고 했는가","3 kg 100 g을 구했는가"]},"explanation":["6 kg + 200 g + 200 g = 6 kg 400 g.","9 kg 500 g − 6 kg 400 g = 3 kg 100 g.","3 kg 100 g을 더 담을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_basic#1','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',1,'sa','auto','초록 목장에서 우유 90 L를 나누어 담으려고 해요. 우유를 10 L 통 7개, 5 L 통 4개에 나누어 담으면 모두 몇 L 담을 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M3-2-u5-C10","difficulty":1,"kind":"sa","stem":"초록 목장에서 우유 90 L를 나누어 담으려고 해요. 우유를 10 L 통 7개, 5 L 통 4개에 나누어 담으면 모두 몇 L 담을 수 있나요? 숫자로 쓰세요.","answer":["90"],"explanation":["통마다 담는 양을 구해요 — 10 L 통 7개는 70 L, 5 L 통 4개는 20 L.","모두 더해요: 70 L + 20 L = 90 L.","90 L — 남김없이 담을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_basic#2','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',1,'sa','auto','초록 목장에서 우유 90 L를 10 L, 6 L, 5 L 통에 남김없이 나누어 담으려고 해요. 6 L 통 5개를 사용한다면 10 L 통은 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M3-2-u5-C10","difficulty":1,"kind":"sa","stem":"초록 목장에서 우유 90 L를 10 L, 6 L, 5 L 통에 남김없이 나누어 담으려고 해요. 6 L 통 5개를 사용한다면 10 L 통은 몇 개 필요한가요? 숫자로 쓰세요.","answer":["6"],"explanation":["6 L 통 5개에 담는 양: 30 L.","남은 양: 90 L − 30 L = 60 L.","60 ÷ 10 = 6 — 10 L 통 6개가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_basic#3','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',1,'sa','auto','수족관 용품 가게에서 영양제 40 L를 나누어 담으려고 해요. 영양제를 10 L 통 3개, 5 L 통 2개에 나누어 담으면 모두 몇 L 담을 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u5-C10","difficulty":1,"kind":"sa","stem":"수족관 용품 가게에서 영양제 40 L를 나누어 담으려고 해요. 영양제를 10 L 통 3개, 5 L 통 2개에 나누어 담으면 모두 몇 L 담을 수 있나요? 숫자로 쓰세요.","answer":["40"],"explanation":["통마다 담는 양을 구해요 — 10 L 통 3개는 30 L, 5 L 통 2개는 10 L.","모두 더해요: 30 L + 10 L = 40 L.","40 L — 남김없이 담을 수 있어요."],"variant_rule":{"alt":[{"stem":"수족관 용품 가게에서 먹이 20 kg을 나누어 담으려고 해요. 먹이를 4 kg 봉지 3개, 2 kg 봉지 4개에 나누어 담으면 모두 몇 kg 담을 수 있나요? 숫자로 쓰세요.","answer":["20"],"explanation":["봉지마다 담는 양을 구해요 — 4 kg 봉지 3개는 12 kg, 2 kg 봉지 4개는 8 kg.","모두 더해요: 12 kg + 8 kg = 20 kg.","20 kg — 남김없이 담을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_basic#4','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',1,'sa','auto','수족관 용품 가게에서 먹이 20 kg을 나누어 담으려고 해요. 먹이를 4 kg 봉지 4개, 2 kg 봉지 2개에 나누어 담으면 모두 몇 kg 담을 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u5-C10","difficulty":1,"kind":"sa","stem":"수족관 용품 가게에서 먹이 20 kg을 나누어 담으려고 해요. 먹이를 4 kg 봉지 4개, 2 kg 봉지 2개에 나누어 담으면 모두 몇 kg 담을 수 있나요? 숫자로 쓰세요.","answer":["20"],"explanation":["봉지마다 담는 양을 구해요 — 4 kg 봉지 4개는 16 kg, 2 kg 봉지 2개는 4 kg.","모두 더해요: 16 kg + 4 kg = 20 kg.","20 kg — 남김없이 담을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_basic#5','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',2,'sa','auto','초록 목장에서 우유 90 L를 10 L, 6 L, 5 L 통에 남김없이 나누어 담으려고 해요. 10 L 통 5개, 6 L 통 5개를 사용한다면 5 L 통은 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M3-2-u5-C10","difficulty":2,"kind":"sa","stem":"초록 목장에서 우유 90 L를 10 L, 6 L, 5 L 통에 남김없이 나누어 담으려고 해요. 10 L 통 5개, 6 L 통 5개를 사용한다면 5 L 통은 몇 개 필요한가요? 숫자로 쓰세요.","answer":["2"],"explanation":["10 L 통 5개, 6 L 통 5개에 담는 양: 50 L + 30 L = 80 L.","남은 양: 90 L − 80 L = 10 L.","10 ÷ 5 = 2 — 5 L 통 2개가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_basic#6','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',2,'sa','auto','반려동물 용품 가게에서 강아지 사료 50 kg을 5 kg, 4 kg, 2 kg 담을 수 있는 봉지에 나누어 담으려고 해요. 5 kg짜리 봉지 6개를 사용하면 남은 사료는 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M3-2-u5-C10","difficulty":2,"kind":"sa","stem":"반려동물 용품 가게에서 강아지 사료 50 kg을 5 kg, 4 kg, 2 kg 담을 수 있는 봉지에 나누어 담으려고 해요. 5 kg짜리 봉지 6개를 사용하면 남은 사료는 몇 kg인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["5 kg짜리 봉지 6개에는 5 × 6 = 30, 30 kg을 담아요.","50 kg − 30 kg = 20 kg.","남은 사료 20 kg은 4 kg짜리 봉지 5개에 담을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_basic#7','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',2,'mc','auto','우유 90 L를 10 L, 6 L, 5 L 담을 수 있는 통(각각 7개)에 남김없이 나누어 담는 방법은 어느 것인가요?',ARRAY['M3-2-u5-X18','M3-2-u5-X19']::text[],false,'{"seq":7,"concept":"M3-2-u5-C10","difficulty":2,"kind":"mc","stem":"우유 90 L를 10 L, 6 L, 5 L 담을 수 있는 통(각각 7개)에 남김없이 나누어 담는 방법은 어느 것인가요?","options":[{"t":"10 L 통 4개, 6 L 통 5개, 5 L 통 4개","correct":true},{"t":"10 L 통 4개, 6 L 통 5개, 5 L 통 5개","mis":"M3-2-u5-X18"},{"t":"10 L 통 6개, 6 L 통 5개, 5 L 통 2개","mis":"M3-2-u5-X18"},{"t":"10 L 통 9개","mis":"M3-2-u5-X19"}],"explanation":["방법마다 담은 양을 모두 더해 90 L와 견주어요.","10 L 통 4개, 6 L 통 5개, 5 L 통 4개 → 40 L + 30 L + 20 L = 90 L.","95 L, 100 L는 남김없이가 아니고, 10 L 통은 7개뿐이라 9개는 쓸 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_basic#8','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',2,'sa','auto','반려동물 용품 가게에서 강아지 사료 50 kg을 5 kg, 4 kg, 2 kg 봉지에 남김없이 나누어 담으려고 해요. 5 kg 봉지 4개, 4 kg 봉지 5개를 사용한다면 2 kg 봉지는 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u5-C10","difficulty":2,"kind":"sa","stem":"반려동물 용품 가게에서 강아지 사료 50 kg을 5 kg, 4 kg, 2 kg 봉지에 남김없이 나누어 담으려고 해요. 5 kg 봉지 4개, 4 kg 봉지 5개를 사용한다면 2 kg 봉지는 몇 개 필요한가요? 숫자로 쓰세요.","answer":["5"],"explanation":["5 kg 봉지 4개, 4 kg 봉지 5개에 담는 양: 20 kg + 20 kg = 40 kg.","남은 양: 50 kg − 40 kg = 10 kg.","10 ÷ 2 = 5 — 2 kg 봉지 5개가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_basic#9','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',2,'sa','auto','수족관 용품 가게에서 먹이 20 kg을 4 kg, 2 kg 봉지에 남김없이 나누어 담으려고 해요. 4 kg 봉지 4개를 사용한다면 2 kg 봉지는 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u5-C10","difficulty":2,"kind":"sa","stem":"수족관 용품 가게에서 먹이 20 kg을 4 kg, 2 kg 봉지에 남김없이 나누어 담으려고 해요. 4 kg 봉지 4개를 사용한다면 2 kg 봉지는 몇 개 필요한가요? 숫자로 쓰세요.","answer":["2"],"explanation":["4 kg 봉지 4개에 담는 양: 16 kg.","남은 양: 20 kg − 16 kg = 4 kg.","4 ÷ 2 = 2 — 2 kg 봉지 2개가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_basic#10','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',3,'mc','auto','우유 90 L를 10 L, 6 L, 5 L 담을 수 있는 통(각각 7개)에 남김없이 나누어 담으려고 해요. 6 L짜리 통은 몇 개 사용할 수 있나요?',ARRAY['M3-2-u5-X18','M3-2-u5-X19']::text[],false,'{"seq":10,"concept":"M3-2-u5-C10","difficulty":3,"kind":"mc","stem":"우유 90 L를 10 L, 6 L, 5 L 담을 수 있는 통(각각 7개)에 남김없이 나누어 담으려고 해요. 6 L짜리 통은 몇 개 사용할 수 있나요?","options":[{"t":"사용하지 않거나 5개","correct":true},{"t":"1개나 2개","mis":"M3-2-u5-X18"},{"t":"7개 모두","mis":"M3-2-u5-X19"},{"t":"3개","mis":"M3-2-u5-X18"}],"explanation":["10 L 통과 5 L 통으로 담은 양은 일의 자리 숫자가 0이나 5예요.","6 L 통 5개는 30 L — 더했을 때 일의 자리 숫자가 0이 돼요.","6 L 통은 사용하지 않거나 5개를 사용해요(10개는 통이 모자라요)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_challenge#1','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_challenge','lesson_challenge','M3-2-u5-C10',2,'sa','auto','수족관 용품 가게에서 영양제 40 L를 10 L와 5 L 담을 수 있는 통(각각 4개)에 나누어 담으려고 해요. 10 L짜리 통만 사용한다면 몇 개가 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M3-2-u5-C10","difficulty":2,"kind":"sa","stem":"수족관 용품 가게에서 영양제 40 L를 10 L와 5 L 담을 수 있는 통(각각 4개)에 나누어 담으려고 해요. 10 L짜리 통만 사용한다면 몇 개가 필요한가요? 숫자로 쓰세요.","answer":["4"],"explanation":["10 L짜리 통으로만 40 L를 담아요.","40 ÷ 10 = 4.","10 L짜리 통 4개 — 4개가 있으니 담을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_challenge#2','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_challenge','lesson_challenge','M3-2-u5-C10',2,'mc','auto','강아지 사료 50 kg을 5 kg, 4 kg, 2 kg 담을 수 있는 봉지(각각 6개)에 남김없이 나누어 담는 방법은 어느 것인가요?',ARRAY['M3-2-u5-X18','M3-2-u5-X19']::text[],false,'{"seq":2,"concept":"M3-2-u5-C10","difficulty":2,"kind":"mc","stem":"강아지 사료 50 kg을 5 kg, 4 kg, 2 kg 담을 수 있는 봉지(각각 6개)에 남김없이 나누어 담는 방법은 어느 것인가요?","options":[{"t":"5 kg 봉지 4개, 4 kg 봉지 6개, 2 kg 봉지 3개","correct":true},{"t":"5 kg 봉지 4개, 4 kg 봉지 6개, 2 kg 봉지 4개","mis":"M3-2-u5-X18"},{"t":"5 kg 봉지 6개, 4 kg 봉지 6개","mis":"M3-2-u5-X18"},{"t":"5 kg 봉지 10개","mis":"M3-2-u5-X19"}],"explanation":["방법마다 담은 양을 모두 더해 50 kg과 견주어요.","5 kg 봉지 4개, 4 kg 봉지 6개, 2 kg 봉지 3개 → 20 kg + 24 kg + 6 kg = 50 kg.","52 kg, 54 kg은 남김없이가 아니고, 5 kg 봉지는 6개뿐이라 10개는 쓸 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_challenge#3','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_challenge','lesson_challenge','M3-2-u5-C10',3,'sa','auto','우유 90 L를 10 L, 6 L, 5 L 담을 수 있는 통(각각 7개)에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 사용하지 않는 통이 있어도 돼요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u5-C10","difficulty":3,"kind":"sa","stem":"우유 90 L를 10 L, 6 L, 5 L 담을 수 있는 통(각각 7개)에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 사용하지 않는 통이 있어도 돼요. 숫자로 쓰세요.","answer":["6"],"explanation":["6 L 통은 사용하지 않거나 5개를 사용해요.","표로 정리하면 (10 L, 6 L, 5 L) = (7, 0, 4), (6, 5, 0), (6, 0, 6), (5, 5, 2), (4, 5, 4), (3, 5, 6).","모두 6가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_challenge#4','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_challenge','lesson_challenge','M3-2-u5-C10',3,'ox','auto','우유 90 L를 10 L 통 7개와 5 L 통 4개에 나누어 담았어요. 친구가 「통을 모두 11개 사용했으니 90 L를 남김없이 담았는지 알 수 있어.」라고 말했어요. 바르게 말했어요.',ARRAY['M3-2-u5-X18']::text[],false,'{"seq":4,"concept":"M3-2-u5-C10","difficulty":3,"kind":"ox","stem":"우유 90 L를 10 L 통 7개와 5 L 통 4개에 나누어 담았어요. 친구가 「통을 모두 11개 사용했으니 90 L를 남김없이 담았는지 알 수 있어.」라고 말했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"통마다 담은 양을 모두 더해 90 L인지 확인해야 해서","correct":true},{"t":"통의 개수만 세면 남김없이 담았는지 알 수 있어서","mis":"M3-2-u5-X18"}],"mis":"M3-2-u5-X18","explanation":["통의 개수만으로는 담은 양을 알 수 없어요.","10 L 통 7개는 70 L, 5 L 통 4개는 20 L — 70 L + 20 L = 90 L.","담은 양을 모두 더해 확인해야 해요 — 바르지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_challenge#5','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_challenge','lesson_challenge','M3-2-u5-C10',3,'sa','auto','10 L, 5 L, 4 L 담을 수 있는 물통이 각각 6개씩 있어요. 물 80 L를 10 L, 5 L, 4 L 통에 남김없이 나누어 담으려고 해요. 10 L 통 6개를 사용한다면 5 L 통은 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M3-2-u5-C10","difficulty":3,"kind":"sa","stem":"10 L, 5 L, 4 L 담을 수 있는 물통이 각각 6개씩 있어요. 물 80 L를 10 L, 5 L, 4 L 통에 남김없이 나누어 담으려고 해요. 10 L 통 6개를 사용한다면 5 L 통은 몇 개 필요한가요? 숫자로 쓰세요.","answer":["4"],"explanation":["10 L 통 6개에 담는 양: 60 L.","남은 양: 80 L − 60 L = 20 L.","20 ÷ 5 = 4 — 5 L 통 4개가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_challenge#6','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_challenge','lesson_challenge','M3-2-u5-C10',3,'sa','auto','5 kg, 4 kg, 2 kg 담을 수 있는 봉지가 각각 5개씩 있어요. 쌀 30 kg을 5 kg, 4 kg, 2 kg 봉지에 남김없이 나누어 담으려고 해요. 5 kg 봉지 2개, 4 kg 봉지 4개를 사용한다면 2 kg 봉지는 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M3-2-u5-C10","difficulty":3,"kind":"sa","stem":"5 kg, 4 kg, 2 kg 담을 수 있는 봉지가 각각 5개씩 있어요. 쌀 30 kg을 5 kg, 4 kg, 2 kg 봉지에 남김없이 나누어 담으려고 해요. 5 kg 봉지 2개, 4 kg 봉지 4개를 사용한다면 2 kg 봉지는 몇 개 필요한가요? 숫자로 쓰세요.","answer":["2"],"explanation":["5 kg 봉지 2개, 4 kg 봉지 4개에 담는 양: 10 kg + 16 kg = 26 kg.","남은 양: 30 kg − 26 kg = 4 kg.","4 ÷ 2 = 2 — 2 kg 봉지 2개가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_challenge#7','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_challenge','lesson_challenge','M3-2-u5-C10',3,'mc','auto','먹이 20 kg을 4 kg과 2 kg 담을 수 있는 봉지(각각 4개)에 남김없이 나누어 담으려고 해요. 바르게 말한 친구는 누구인가요?',ARRAY['M3-2-u5-X19','M3-2-u5-X18']::text[],false,'{"seq":7,"concept":"M3-2-u5-C10","difficulty":3,"kind":"mc","stem":"먹이 20 kg을 4 kg과 2 kg 담을 수 있는 봉지(각각 4개)에 남김없이 나누어 담으려고 해요. 바르게 말한 친구는 누구인가요?","options":[{"t":"민준 — 「4 kg 봉지 3개와 2 kg 봉지 4개면 12 kg + 8 kg = 20 kg이야」","correct":true},{"t":"지아 — 「4 kg 봉지 5개면 20 kg이야」","mis":"M3-2-u5-X19"},{"t":"서윤 — 「4 kg 봉지 4개와 2 kg 봉지 4개면 20 kg이야」","mis":"M3-2-u5-X18"},{"t":"정후 — 「2 kg 봉지 10개면 20 kg이야」","mis":"M3-2-u5-X19"}],"explanation":["봉지는 각각 4개뿐이고, 담은 양을 모두 더해 20 kg인지 확인해요.","4 kg 봉지 4개와 2 kg 봉지 4개는 16 kg + 8 kg = 24 kg — 넘쳐요.","4 kg 봉지 5개, 2 kg 봉지 10개는 있는 봉지보다 많아요 — 민준이가 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_challenge#8','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_challenge','lesson_challenge','M3-2-u5-C10',4,'essay','teacher','초록 목장에서 우유 90 L를 10 L, 6 L, 5 L 담을 수 있는 통(각각 7개)에 나누어 담으려고 해요. 「10 L 통 7개와 5 L 통 4개」가 아닌 다른 방법을 하나 예상하고, 들이를 계산하여 확인해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u5-C10","difficulty":4,"kind":"essay","stem":"초록 목장에서 우유 90 L를 10 L, 6 L, 5 L 담을 수 있는 통(각각 7개)에 나누어 담으려고 해요. 「10 L 통 7개와 5 L 통 4개」가 아닌 다른 방법을 하나 예상하고, 들이를 계산하여 확인해 보세요.","answer_guide":{"answer":"예: 10 L 통 5개, 6 L 통 5개, 5 L 통 2개에 나누어 담는다고 예상한다. 50 L + 30 L + 10 L = 90 L이므로 예상이 맞다. (다른 방법: 10 L 통 6개와 6 L 통 5개, 10 L 통 6개와 5 L 통 6개, 10 L 통 4개·6 L 통 5개·5 L 통 4개, 10 L 통 3개·6 L 통 5개·5 L 통 6개)","scoring_points":["통의 개수가 각각 7개 이하인 방법을 예상했는가","통마다 담은 양을 더해 90 L가 되는지 확인했는가","예상이 맞는지 판단했는가"]},"explanation":["예상하기 — 6 L 통 5개를 쓰면 30 L.","확인하기 — 50 L + 30 L + 10 L = 90 L.","통의 개수가 7개를 넘지 않는지도 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_challenge#9','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_challenge','lesson_challenge','M3-2-u5-C10',4,'essay','teacher','반려동물 용품 가게에서 강아지 사료 50 kg을 5 kg, 4 kg, 2 kg 담을 수 있는 봉지(각각 6개)에 나누어 담으려고 해요. 사료를 남김없이 나누어 담는 방법 두 가지를 예상하고 확인해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u5-C10","difficulty":4,"kind":"essay","stem":"반려동물 용품 가게에서 강아지 사료 50 kg을 5 kg, 4 kg, 2 kg 담을 수 있는 봉지(각각 6개)에 나누어 담으려고 해요. 사료를 남김없이 나누어 담는 방법 두 가지를 예상하고 확인해 보세요.","answer_guide":{"answer":"예: ① 5 kg 봉지 6개와 4 kg 봉지 5개 → 30 kg + 20 kg = 50 kg. ② 5 kg 봉지 4개, 4 kg 봉지 5개, 2 kg 봉지 5개 → 20 kg + 20 kg + 10 kg = 50 kg. (다른 방법: 5 kg 6개·4 kg 4개·2 kg 2개, 5 kg 6개·4 kg 3개·2 kg 4개, 5 kg 4개·4 kg 6개·2 kg 3개 등)","scoring_points":["봉지 수가 각각 6개 이하인 방법 두 가지를 썼는가","각 방법의 무게를 더해 50 kg인지 확인했는가","서로 다른 두 방법인가"]},"explanation":["5 kg 봉지 6개는 30 kg — 남은 20 kg을 4 kg, 2 kg 봉지로 담아요.","20 kg + 20 kg + 10 kg = 50 kg처럼 모두 더해 확인해요.","봉지 수가 6개를 넘지 않게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_L09_challenge#10','math',3,2,'u5','L09','tb_g3_2_math_u5_L09_challenge','lesson_challenge','M3-2-u5-C10',4,'essay','teacher','우유 90 L를 10 L, 6 L, 5 L 담을 수 있는 통(각각 7개)에 남김없이 나누어 담을 때, 6 L짜리 통은 사용하지 않거나 5개를 사용해야 해요. 그 까닭을 「합의 일의 자리 숫자」를 이용하여 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u5-C10","difficulty":4,"kind":"essay","stem":"우유 90 L를 10 L, 6 L, 5 L 담을 수 있는 통(각각 7개)에 남김없이 나누어 담을 때, 6 L짜리 통은 사용하지 않거나 5개를 사용해야 해요. 그 까닭을 「합의 일의 자리 숫자」를 이용하여 설명해 보세요.","answer_guide":{"answer":"예: 10 L 통과 5 L 통으로 담은 양은 일의 자리 숫자가 0이나 5이다. 90 L는 일의 자리 숫자가 0이므로 6 L 통으로 담은 양도 일의 자리 숫자가 0이나 5가 되어야 하는데, 6 L 통 1~4개는 6, 12, 18, 24 L로 맞지 않고 5개일 때 30 L로 맞는다. 6 L 통은 7개뿐이라 10개는 쓸 수 없다.","scoring_points":["10 L, 5 L 통으로 담은 양의 일의 자리 숫자가 0이나 5라고 썼는가","6 L 통 5개면 30 L로 일의 자리가 0이 된다고 썼는가","1~4개는 맞지 않고 통이 7개뿐임을 썼는가"]},"explanation":["10 L, 5 L 통 → 일의 자리 숫자 0이나 5.","6 L 통 5개 = 30 L.","그래서 6 L 통은 사용하지 않거나 5개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#1','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C3',1,'sa','auto','물을 비커에 담았어요. 비커의 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있고, 물이 0에서부터 2칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M3-2-u5-C3","difficulty":1,"kind":"sa","stem":"물을 비커에 담았어요. 비커의 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있고, 물이 0에서부터 2칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["200"],"explanation":["한 칸의 크기부터: 0~1000 mL 사이 10칸 → 1000 ÷ 10 = 100, 한 칸은 100 mL예요.","2칸 → 100 × 2 = 200.","200 mL예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#2','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C6',1,'sa','auto','물건을 저울에 올렸어요. 저울의 1 kg과 2 kg 사이가 똑같이 10칸으로 나뉘어 있고, 바늘이 1 kg에서 5칸 더 간 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M3-2-u5-C6","difficulty":1,"kind":"sa","stem":"물건을 저울에 올렸어요. 저울의 1 kg과 2 kg 사이가 똑같이 10칸으로 나뉘어 있고, 바늘이 1 kg에서 5칸 더 간 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["1500"],"explanation":["한 칸의 크기부터: 1 kg~2 kg 사이 10칸 → 1000 ÷ 10 = 100, 한 칸은 100 g이에요.","1 kg에서 5칸 더 → 1000 + 100 × 5 = 1500.","1500 g = 1 kg 500 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#3','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C2',1,'sa','auto','3 L 400 mL는 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u5-C2","difficulty":1,"kind":"sa","stem":"3 L 400 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["3400"],"explanation":["1 L = 1000 mL — 3 L = 3000 mL.","3000 mL + 400 mL = 3400 mL.","3 L 400 mL = 3400 mL."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#4','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C6',1,'sa','auto','5780 g은 몇 kg 몇 g인가요? g 앞에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u5-C6","difficulty":1,"kind":"sa","stem":"5780 g은 몇 kg 몇 g인가요? g 앞에 알맞은 수를 쓰세요.","answer":["780"],"explanation":["1000 g = 1 kg이에요.","5780 g = 5000 g + 780 g.","5780 g = 5 kg 780 g — g 앞의 수는 780이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#5','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C7',1,'sa','auto','4 t은 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M3-2-u5-C7","difficulty":1,"kind":"sa","stem":"4 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["4000"],"explanation":["1 t = 1000 kg이에요.","4 t은 1000 kg이 4번이에요.","4 t = 4000 kg."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#6','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C3',1,'mc','auto','식용유병의 들이는 약 2 ○예요. ○에 알맞은 단위는 어느 것인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],false,'{"seq":6,"concept":"M3-2-u5-C3","difficulty":1,"kind":"mc","stem":"식용유병의 들이는 약 2 ○예요. ○에 알맞은 단위는 어느 것인가요?","options":[{"t":"L","correct":true},{"t":"mL","mis":"M3-2-u5-X09"},{"t":"g","mis":"M3-2-u5-X10"},{"t":"kg","mis":"M3-2-u5-X10"}],"explanation":["식용유병을 아는 들이와 견주어 보아요.","들이에 쓰는 단위는 mL·L이에요.","식용유병의 들이는 약 2 L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#7','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C4',1,'mc','auto','계산해 보세요. 5 L 700 mL + 3 L 200 mL',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],false,'{"seq":7,"concept":"M3-2-u5-C4","difficulty":1,"kind":"mc","stem":"계산해 보세요. 5 L 700 mL + 3 L 200 mL","options":[{"t":"8 L 900 mL","correct":true},{"t":"2 L 500 mL","mis":"M3-2-u5-X14"},{"t":"9 L","mis":"M3-2-u5-X24"},{"t":"8 L 800 mL","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","mL끼리 700 + 200 = 900, L끼리 5 + 3 = 8.","5 L 700 mL + 3 L 200 mL = 8 L 900 mL."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#8','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C9',1,'mc','auto','계산해 보세요. 2 kg 200 g + 5 kg 400 g',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],false,'{"seq":8,"concept":"M3-2-u5-C9","difficulty":1,"kind":"mc","stem":"계산해 보세요. 2 kg 200 g + 5 kg 400 g","options":[{"t":"7 kg 600 g","correct":true},{"t":"3 kg 200 g","mis":"M3-2-u5-X14"},{"t":"7 kg 700 g","mis":"M3-2-u5-X24"},{"t":"7 kg 500 g","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","g끼리 200 + 400 = 600, kg끼리 2 + 5 = 7.","2 kg 200 g + 5 kg 400 g = 7 kg 600 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#9','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C9',2,'mc','auto','장난감을 정리함에 담아 무게를 재었더니 3850 g이었어요. 정리함만의 무게는 1600 g이에요. 장난감의 무게는 몇 kg 몇 g인가요?',ARRAY['M3-2-u5-X05','M3-2-u5-X14','M3-2-u5-X04']::text[],false,'{"seq":9,"concept":"M3-2-u5-C9","difficulty":2,"kind":"mc","stem":"장난감을 정리함에 담아 무게를 재었더니 3850 g이었어요. 정리함만의 무게는 1600 g이에요. 장난감의 무게는 몇 kg 몇 g인가요?","options":[{"t":"2 kg 250 g","correct":true},{"t":"2 kg 25 g","mis":"M3-2-u5-X05"},{"t":"5 kg 450 g","mis":"M3-2-u5-X14"},{"t":"22 kg 50 g","mis":"M3-2-u5-X04"}],"explanation":["전체 무게에서 정리함의 무게를 빼요 — 식은 3 kg 850 g − 1 kg 600 g.","3850 g = 3 kg 850 g, 1600 g = 1 kg 600 g — 바꾸어서 g끼리 850 − 600 = 250, kg끼리 3 − 1 = 2.","3 kg 850 g − 1 kg 600 g = 2 kg 250 g — 장난감은 2 kg 250 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#10','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C9',2,'mc','auto','무게가 1500 g인 가방에 짐을 19 kg 200 g 넣었어요. 짐을 넣은 가방의 무게는 몇 kg 몇 g인가요?',ARRAY['M3-2-u5-X04','M3-2-u5-X11','M3-2-u5-X14']::text[],false,'{"seq":10,"concept":"M3-2-u5-C9","difficulty":2,"kind":"mc","stem":"무게가 1500 g인 가방에 짐을 19 kg 200 g 넣었어요. 짐을 넣은 가방의 무게는 몇 kg 몇 g인가요?","options":[{"t":"20 kg 700 g","correct":true},{"t":"34 kg 200 g","mis":"M3-2-u5-X04"},{"t":"19 kg 1700 g","mis":"M3-2-u5-X11"},{"t":"17 kg 700 g","mis":"M3-2-u5-X14"}],"explanation":["가방의 무게와 짐의 무게를 더해요 — 식은 1 kg 500 g + 19 kg 200 g.","1500 g = 1 kg 500 g — 바꾸어서 g끼리 500 + 200 = 700, kg끼리 1 + 19 = 20.","1 kg 500 g + 19 kg 200 g = 20 kg 700 g — 짐을 넣은 가방은 20 kg 700 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#11','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C4',2,'sa','auto','사과주스 2병의 들이는 각각 1 L 300 mL와 650 mL이고, 당근주스 2병의 들이는 각각 1 L 150 mL와 700 mL예요. 사과주스는 당근주스보다 몇 mL 더 많은가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M3-2-u5-C4","difficulty":2,"kind":"sa","stem":"사과주스 2병의 들이는 각각 1 L 300 mL와 650 mL이고, 당근주스 2병의 들이는 각각 1 L 150 mL와 700 mL예요. 사과주스는 당근주스보다 몇 mL 더 많은가요? 숫자로 쓰세요.","answer":["100"],"explanation":["사과주스: 1 L 300 mL + 650 mL = 1 L 950 mL.","당근주스: 1 L 150 mL + 700 mL = 1 L 850 mL.","1 L 950 mL − 1 L 850 mL = 100 mL — 사과주스가 100 mL 더 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#12','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C8',2,'sa','auto','약 100 g인 물건 5개의 무게는 약 몇 g인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M3-2-u5-C8","difficulty":2,"kind":"sa","stem":"약 100 g인 물건 5개의 무게는 약 몇 g인가요? 숫자로 쓰세요.","answer":["500"],"explanation":["약 100 g이 5개예요.","100 × 5 = 500.","약 500 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#13','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C2',2,'mc','auto','재활용품 교환권 1장으로 1 L짜리 음료수 1병 또는 500 mL짜리 음료수 2병으로 바꿀 수 있어요. 친구가 「2병이면 더 많이 마실 수 있어!」라고 했어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M3-2-u5-X21']::text[],false,'{"seq":13,"concept":"M3-2-u5-C2","difficulty":2,"kind":"mc","stem":"재활용품 교환권 1장으로 1 L짜리 음료수 1병 또는 500 mL짜리 음료수 2병으로 바꿀 수 있어요. 친구가 「2병이면 더 많이 마실 수 있어!」라고 했어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"500 mL짜리 2병과 1 L짜리 1병의 들이는 같아요","correct":true},{"t":"500 mL짜리 2병이 더 많아요","mis":"M3-2-u5-X21"},{"t":"1 L짜리 1병이 더 많아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 비교할 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["500 mL + 500 mL = 1000 mL예요.","1000 mL = 1 L예요.","500 mL짜리 2병과 1 L짜리 1병의 들이는 같아요 — 병의 수가 많다고 더 많은 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#14','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C6',2,'mc','auto','재활용품 1 kg당 알뜰 시장 교환권 1장으로 바꾸어 줘요. 승우의 재활용품은 1300 g, 연아의 재활용품은 1100 g이에요. 바르게 말한 것은 어느 것인가요?',ARRAY['M3-2-u5-X21','M3-2-u5-X04','M3-2-u5-X23']::text[],false,'{"seq":14,"concept":"M3-2-u5-C6","difficulty":2,"kind":"mc","stem":"재활용품 1 kg당 알뜰 시장 교환권 1장으로 바꾸어 줘요. 승우의 재활용품은 1300 g, 연아의 재활용품은 1100 g이에요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"두 사람 모두 교환권을 1장씩 받아요","correct":true},{"t":"승우가 교환권을 더 많이 받아요","mis":"M3-2-u5-X21"},{"t":"승우는 13장, 연아는 11장을 받아요","mis":"M3-2-u5-X04"},{"t":"두 사람 모두 받을 수 없어요","mis":"M3-2-u5-X23"}],"explanation":["1300 g = 1 kg 300 g, 1100 g = 1 kg 100 g이에요.","두 사람 모두 1 kg보다 무겁고 2 kg보다 가벼워요.","1 kg당 1장이라 두 사람 모두 1장씩 받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#15','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C7',2,'mc','auto','1300 kg인 물건과 1 t인 물건이 있어요. 더 무거운 것은 어느 것인가요?',ARRAY['M3-2-u5-X23','M3-2-u5-X21']::text[],false,'{"seq":15,"concept":"M3-2-u5-C7","difficulty":2,"kind":"mc","stem":"1300 kg인 물건과 1 t인 물건이 있어요. 더 무거운 것은 어느 것인가요?","options":[{"t":"1300 kg인 물건","correct":true},{"t":"1 t인 물건 — t은 kg보다 큰 단위라서","mis":"M3-2-u5-X23"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 비교할 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["1 t = 1000 kg이에요.","1000 kg < 1300 kg.","1300 kg인 물건이 더 무거워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#16','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C10',2,'sa','auto','영양제 40 L를 나누어 담으려고 해요. 영양제를 10 L 통 3개, 5 L 통 2개에 나누어 담으면 모두 몇 L 담을 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"M3-2-u5-C10","difficulty":2,"kind":"sa","stem":"영양제 40 L를 나누어 담으려고 해요. 영양제를 10 L 통 3개, 5 L 통 2개에 나누어 담으면 모두 몇 L 담을 수 있나요? 숫자로 쓰세요.","answer":["40"],"explanation":["통마다 담는 양을 구해요 — 10 L 통 3개는 30 L, 5 L 통 2개는 10 L.","모두 더해요: 30 L + 10 L = 40 L.","40 L — 남김없이 담을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#17','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C6',3,'mc','auto','정후는 감자를 3 kg 40 g 캤고, 지아는 감자를 3400 g 캤어요. 캔 감자의 무게가 더 무거운 사람은 누구인가요?',ARRAY['M3-2-u5-X23','M3-2-u5-X05','M3-2-u5-X21']::text[],false,'{"seq":17,"concept":"M3-2-u5-C6","difficulty":3,"kind":"mc","stem":"정후는 감자를 3 kg 40 g 캤고, 지아는 감자를 3400 g 캤어요. 캔 감자의 무게가 더 무거운 사람은 누구인가요?","options":[{"t":"지아","correct":true},{"t":"정후","mis":"M3-2-u5-X23"},{"t":"두 사람이 같아요","mis":"M3-2-u5-X05"},{"t":"단위가 달라서 비교할 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["3400 g = 3 kg 400 g이에요.","3 kg 40 g < 3 kg 400 g.","지아가 캔 감자가 더 무거워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#18','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C5',3,'mc','auto','구슬 6개 가운데 5개의 무게는 같고 1개만 가벼워요. 2개씩 묶어 양팔저울로 비교했어요. 가벼운 구슬이 있는 묶음의 번호는 어느 것인가요?',ARRAY['M3-2-u5-X15','M3-2-u5-X21']::text[],false,'{"seq":18,"concept":"M3-2-u5-C5","difficulty":3,"kind":"mc","stem":"구슬 6개 가운데 5개의 무게는 같고 1개만 가벼워요. 2개씩 묶어 양팔저울로 비교했어요. 가벼운 구슬이 있는 묶음의 번호는 어느 것인가요?","options":[{"t":"5번, 6번","correct":true},{"t":"1번, 2번","mis":"M3-2-u5-X15"},{"t":"3번, 4번","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["첫째 저울은 수평 — 1·2번과 3·4번의 무게가 같아요.","둘째 저울은 5·6번 쪽이 올라갔어요.","가벼운 구슬은 5번, 6번 묶음에 있어요."],"asset":{"type":"balance","scales":[{"l":{"name":"1·2번 구슬","icon":"🔮"},"r":{"name":"3·4번 구슬","icon":"🔮"},"down":"eq"},{"l":{"name":"3·4번 구슬","icon":"🔮"},"r":{"name":"5·6번 구슬","icon":"🔮"},"down":"l"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#19','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C3',3,'mc','auto','주스병의 들이를 어림했어요. 가장 알맞게 어림한 친구는 누구인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X05','M3-2-u5-X21']::text[],false,'{"seq":19,"concept":"M3-2-u5-C3","difficulty":3,"kind":"mc","stem":"주스병의 들이를 어림했어요. 가장 알맞게 어림한 친구는 누구인가요?","options":[{"t":"민준","correct":true},{"t":"지아","mis":"M3-2-u5-X09"},{"t":"정후","mis":"M3-2-u5-X05"},{"t":"모두 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["지아 — 500 mL 2개는 1 L예요. 100 L가 아니에요.","정후 — 500 mL와 1 L를 합하면 1 L 500 mL예요. 15 L가 아니에요.","민준 — 1 L보다 약간 적어 약 950 mL — 가장 알맞아요."],"asset":{"type":"speech","turns":[{"who":"지아","text":"500 mL 우유갑이 2개 있는 들이와 비슷해서 약 100 L야."},{"who":"민준","text":"1 L 우유갑보다 약간 적을 것 같아서 약 950 mL야."},{"who":"정후","text":"500 mL 우유갑 1개와 1 L 우유갑 1개를 합한 들이와 비슷할 것 같아서 약 15 L야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#20','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C10',3,'mc','auto','우유 90 L를 10 L, 6 L, 5 L 담을 수 있는 통(각각 7개)에 남김없이 나누어 담으려고 해요. 6 L짜리 통은 몇 개 사용할 수 있나요?',ARRAY['M3-2-u5-X18','M3-2-u5-X19']::text[],false,'{"seq":20,"concept":"M3-2-u5-C10","difficulty":3,"kind":"mc","stem":"우유 90 L를 10 L, 6 L, 5 L 담을 수 있는 통(각각 7개)에 남김없이 나누어 담으려고 해요. 6 L짜리 통은 몇 개 사용할 수 있나요?","options":[{"t":"사용하지 않거나 5개","correct":true},{"t":"1개나 2개","mis":"M3-2-u5-X18"},{"t":"7개 모두","mis":"M3-2-u5-X19"},{"t":"3개","mis":"M3-2-u5-X18"}],"explanation":["10 L 통과 5 L 통으로 담은 양은 일의 자리 숫자가 0이나 5예요.","6 L 통 5개는 30 L예요.","6 L 통은 사용하지 않거나 5개를 사용해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#21','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C4',3,'sa','auto','물통의 들이는 1 L 900 mL예요. 들이가 1 L 300 mL인 병 가와 500 mL인 병 나에 물을 가득 채워 빈 물통에 모두 부었어요. 물통에 물을 몇 mL 더 채울 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M3-2-u5-C4","difficulty":3,"kind":"sa","stem":"물통의 들이는 1 L 900 mL예요. 들이가 1 L 300 mL인 병 가와 500 mL인 병 나에 물을 가득 채워 빈 물통에 모두 부었어요. 물통에 물을 몇 mL 더 채울 수 있나요? 숫자로 쓰세요.","answer":["100"],"explanation":["1 L 300 mL + 500 mL = 1 L 800 mL.","1 L 900 mL − 1 L 800 mL = 100 mL.","100 mL를 더 채울 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#22','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C9',3,'sa','auto','9 kg 500 g까지 담을 수 있는 상자에 6 kg짜리 수박 1통과 200 g짜리 사과 2개가 들어 있어요. 상자에 더 담을 수 있는 과일의 무게는 몇 g인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M3-2-u5-C9","difficulty":3,"kind":"sa","stem":"9 kg 500 g까지 담을 수 있는 상자에 6 kg짜리 수박 1통과 200 g짜리 사과 2개가 들어 있어요. 상자에 더 담을 수 있는 과일의 무게는 몇 g인가요? 숫자로 쓰세요.","answer":["3100"],"explanation":["6 kg + 200 g + 200 g = 6 kg 400 g.","9 kg 500 g − 6 kg 400 g = 3 kg 100 g.","3100 g을 더 담을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#23','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C9',4,'essay','teacher','장난감을 정리함에 담아 무게를 재었더니 3850 g이었어요. 정리함만의 무게가 1600 g일 때 장난감은 몇 kg 몇 g인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u5-C9","difficulty":4,"kind":"essay","stem":"장난감을 정리함에 담아 무게를 재었더니 3850 g이었어요. 정리함만의 무게가 1600 g일 때 장난감은 몇 kg 몇 g인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 3850 g은 3 kg 850 g, 1600 g은 1 kg 600 g이므로 3 kg 850 g − 1 kg 600 g = 2 kg 250 g이다. 답: 2 kg 250 g","scoring_points":["3850 g, 1600 g을 몇 kg 몇 g으로 나타냈는가","전체 무게에서 정리함의 무게를 뺐는가","2 kg 250 g을 구했는가"]},"explanation":["3850 g = 3 kg 850 g, 1600 g = 1 kg 600 g.","3 kg 850 g − 1 kg 600 g = 2 kg 250 g.","장난감은 2 kg 250 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#24','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C8',4,'essay','teacher','단원 핵심 질문 「들이와 무게를 어림하고 재어 볼까요?」에 답해 보세요. 들이나 무게를 어림하는 방법과 정확하게 재는 방법을 생활 속 예를 들어 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u5-C8","difficulty":4,"kind":"essay","stem":"단원 핵심 질문 「들이와 무게를 어림하고 재어 볼까요?」에 답해 보세요. 들이나 무게를 어림하는 방법과 정확하게 재는 방법을 생활 속 예를 들어 설명해 보세요.","answer_guide":{"answer":"예: 어림할 때는 들이나 무게를 알고 있는 물건과 견주거나, 그 물건이 몇 번 들어가는지, 두 물건을 합하면 비슷한지 생각하고 「약」을 붙인다. 예를 들어 빨랫비누 봉지는 약 100 g인 비누가 10개라 약 1 kg이다. 정확하게 잴 때는 비커·계량컵 같은 도구나 저울을 사용하고 눈금 한 칸의 크기를 확인하여 읽는다. 재활용품 1 kg당 교환권을 받을 때처럼 정확한 값이 필요하면 저울로 잰다.","scoring_points":["어림하는 방법(견주기·몇 번·합하기)과 「약」을 썼는가","정확하게 재는 도구와 눈금 읽기를 썼는가","생활 속 예를 들었는가"]},"explanation":["어림 — 아는 양과 견주어 「약 ○○」.","재기 — 비커·저울로, 눈금 한 칸의 크기부터.","어림해도 되는 상황과 정확히 재야 하는 상황을 구분해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_a#25','math',3,2,'u5','','tb_g3_2_math_u5_review_a','unit_review','M3-2-u5-C2',4,'essay','teacher','재활용품 교환권 1장으로 1 L짜리 음료수 1병 또는 500 mL짜리 음료수 2병으로 바꿀 수 있어요. 승우는 「2병으로 바꾸면 더 많이 마실 수 있어!」라고 했어요. 승우의 생각이 왜 틀렸는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u5-C2","difficulty":4,"kind":"essay","stem":"재활용품 교환권 1장으로 1 L짜리 음료수 1병 또는 500 mL짜리 음료수 2병으로 바꿀 수 있어요. 승우는 「2병으로 바꾸면 더 많이 마실 수 있어!」라고 했어요. 승우의 생각이 왜 틀렸는지 설명해 보세요.","answer_guide":{"answer":"예: 500 mL짜리 2병은 500 mL + 500 mL = 1000 mL이고 1000 mL는 1 L와 같다. 그래서 1 L짜리 1병과 들이가 같으므로 2병으로 바꾸어도 더 많이 마실 수 없다.","scoring_points":["500 mL + 500 mL = 1000 mL를 구했는가","1000 mL = 1 L라고 했는가","들이가 같아서 더 많이 마실 수 없다고 했는가"]},"explanation":["500 mL + 500 mL = 1000 mL.","1000 mL = 1 L.","병의 수가 아니라 들이를 견주어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#1','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C3',1,'sa','auto','컵에 물을 가득 채운 후 비커에 모두 옮겨 담았어요. 비커의 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있고, 물이 0에서부터 3칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M3-2-u5-C3","difficulty":1,"kind":"sa","stem":"컵에 물을 가득 채운 후 비커에 모두 옮겨 담았어요. 비커의 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있고, 물이 0에서부터 3칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["300"],"explanation":["한 칸의 크기부터: 0~1000 mL 사이 10칸 → 1000 ÷ 10 = 100, 한 칸은 100 mL예요.","3칸 → 100 × 3 = 300.","300 mL예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#2','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C6',1,'sa','auto','저울에 설탕 1 kg을 올려놓고 설탕 300 g을 더 올렸어요. 저울의 1 kg과 2 kg 사이가 똑같이 10칸으로 나뉘어 있고, 바늘이 1 kg에서 3칸 더 간 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M3-2-u5-C6","difficulty":1,"kind":"sa","stem":"저울에 설탕 1 kg을 올려놓고 설탕 300 g을 더 올렸어요. 저울의 1 kg과 2 kg 사이가 똑같이 10칸으로 나뉘어 있고, 바늘이 1 kg에서 3칸 더 간 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["1300"],"explanation":["한 칸의 크기부터: 1 kg~2 kg 사이 10칸 → 1000 ÷ 10 = 100, 한 칸은 100 g이에요.","1 kg에서 3칸 더 → 1000 + 100 × 3 = 1300.","1300 g = 1 kg 300 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#3','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C2',1,'sa','auto','6850 mL는 몇 L 몇 mL인가요? mL 앞에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u5-C2","difficulty":1,"kind":"sa","stem":"6850 mL는 몇 L 몇 mL인가요? mL 앞에 알맞은 수를 쓰세요.","answer":["850"],"explanation":["1000 mL = 1 L예요.","6850 mL = 6000 mL + 850 mL.","6850 mL = 6 L 850 mL — mL 앞의 수는 850이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#4','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C6',1,'sa','auto','9 kg 270 g은 몇 g인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u5-C6","difficulty":1,"kind":"sa","stem":"9 kg 270 g은 몇 g인가요? 숫자로 쓰세요.","answer":["9270"],"explanation":["1 kg = 1000 g — 9 kg = 9000 g.","9000 g + 270 g = 9270 g.","9 kg 270 g = 9270 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#5','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C7',1,'mc','auto','7000 kg은 몇 t인가요?',ARRAY['M3-2-u5-X17','M3-2-u5-X06']::text[],false,'{"seq":5,"concept":"M3-2-u5-C7","difficulty":1,"kind":"mc","stem":"7000 kg은 몇 t인가요?","options":[{"t":"7 t","correct":true},{"t":"70 t","mis":"M3-2-u5-X17"},{"t":"700 t","mis":"M3-2-u5-X17"},{"t":"7000 t","mis":"M3-2-u5-X06"}],"explanation":["1000 kg = 1 t이에요.","7000 kg은 1000 kg이 7번이에요.","7000 kg = 7 t."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#6','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C3',1,'mc','auto','물병의 들이는 약 1500 ○예요. ○에 알맞은 단위는 어느 것인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],false,'{"seq":6,"concept":"M3-2-u5-C3","difficulty":1,"kind":"mc","stem":"물병의 들이는 약 1500 ○예요. ○에 알맞은 단위는 어느 것인가요?","options":[{"t":"mL","correct":true},{"t":"L","mis":"M3-2-u5-X09"},{"t":"g","mis":"M3-2-u5-X10"},{"t":"kg","mis":"M3-2-u5-X10"}],"explanation":["물병을 아는 들이와 견주어 보아요.","들이에 쓰는 단위는 mL·L이에요.","물병의 들이는 약 1500 mL예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#7','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C4',1,'mc','auto','계산해 보세요. 9 L 400 mL − 2 L 300 mL',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],false,'{"seq":7,"concept":"M3-2-u5-C4","difficulty":1,"kind":"mc","stem":"계산해 보세요. 9 L 400 mL − 2 L 300 mL","options":[{"t":"7 L 100 mL","correct":true},{"t":"11 L 700 mL","mis":"M3-2-u5-X14"},{"t":"7 L 200 mL","mis":"M3-2-u5-X24"},{"t":"8 L 100 mL","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","mL끼리 400 − 300 = 100, L끼리 9 − 2 = 7.","9 L 400 mL − 2 L 300 mL = 7 L 100 mL."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#8','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C9',1,'mc','auto','계산해 보세요. 6 kg 900 g − 4 kg 600 g',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],false,'{"seq":8,"concept":"M3-2-u5-C9","difficulty":1,"kind":"mc","stem":"계산해 보세요. 6 kg 900 g − 4 kg 600 g","options":[{"t":"2 kg 300 g","correct":true},{"t":"11 kg 500 g","mis":"M3-2-u5-X14"},{"t":"2 kg 400 g","mis":"M3-2-u5-X24"},{"t":"2 kg 200 g","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","g끼리 900 − 600 = 300, kg끼리 6 − 4 = 2.","6 kg 900 g − 4 kg 600 g = 2 kg 300 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#9','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C9',2,'mc','auto','민준이는 화분에 나무를 심기 위해 흙 8 kg 650 g 중에서 4 kg 300 g을 사용했어요. 남은 흙의 무게는 얼마인가요?',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],false,'{"seq":9,"concept":"M3-2-u5-C9","difficulty":2,"kind":"mc","stem":"민준이는 화분에 나무를 심기 위해 흙 8 kg 650 g 중에서 4 kg 300 g을 사용했어요. 남은 흙의 무게는 얼마인가요?","options":[{"t":"4 kg 350 g","correct":true},{"t":"12 kg 950 g","mis":"M3-2-u5-X14"},{"t":"4 kg 450 g","mis":"M3-2-u5-X24"},{"t":"4 kg 250 g","mis":"M3-2-u5-X24"}],"explanation":["처음 흙의 무게에서 사용한 흙의 무게를 빼요 — 식은 8 kg 650 g − 4 kg 300 g.","g끼리 650 − 300 = 350, kg끼리 8 − 4 = 4.","8 kg 650 g − 4 kg 300 g = 4 kg 350 g — 남은 흙은 4 kg 350 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#10','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C9',2,'mc','auto','지아는 밀가루 1 kg 200 g과 쌀가루 1050 g을 섞어서 빵을 만들었어요. 사용한 밀가루와 쌀가루의 무게의 합은 몇 kg 몇 g인가요?',ARRAY['M3-2-u5-X05','M3-2-u5-X11','M3-2-u5-X14']::text[],false,'{"seq":10,"concept":"M3-2-u5-C9","difficulty":2,"kind":"mc","stem":"지아는 밀가루 1 kg 200 g과 쌀가루 1050 g을 섞어서 빵을 만들었어요. 사용한 밀가루와 쌀가루의 무게의 합은 몇 kg 몇 g인가요?","options":[{"t":"2 kg 250 g","correct":true},{"t":"2 kg 700 g","mis":"M3-2-u5-X05"},{"t":"1 kg 1250 g","mis":"M3-2-u5-X11"},{"t":"150 g","mis":"M3-2-u5-X14"}],"explanation":["두 가루의 무게를 더해요 — 식은 1 kg 200 g + 1 kg 50 g.","1050 g = 1 kg 50 g — 바꾸어서 g끼리 200 + 50 = 250, kg끼리 1 + 1 = 2.","1 kg 200 g + 1 kg 50 g = 2 kg 250 g — 무게의 합은 2 kg 250 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#11','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C4',2,'sa','auto','은비가 심부름으로 사 온 간장병의 들이는 1 L 300 mL, 주스병의 들이는 1 L 400 mL예요. 간장병과 주스병의 들이의 차는 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M3-2-u5-C4","difficulty":2,"kind":"sa","stem":"은비가 심부름으로 사 온 간장병의 들이는 1 L 300 mL, 주스병의 들이는 1 L 400 mL예요. 간장병과 주스병의 들이의 차는 몇 mL인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["큰 들이에서 작은 들이를 빼요 — 식은 1 L 400 mL − 1 L 300 mL.","mL끼리 400 − 300 = 100, L끼리 1 − 1 = 0.","1 L 400 mL − 1 L 300 mL = 100 mL — 들이의 차는 100 mL예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#12','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C8',2,'sa','auto','빨랫비누 한 봉지에 약 100 g인 비누가 10개 들어 있어요. 한 봉지의 무게는 약 몇 g인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M3-2-u5-C8","difficulty":2,"kind":"sa","stem":"빨랫비누 한 봉지에 약 100 g인 비누가 10개 들어 있어요. 한 봉지의 무게는 약 몇 g인가요? 숫자로 쓰세요.","answer":["1000"],"explanation":["약 100 g이 10개예요.","100 × 10 = 1000.","약 1000 g — 약 1 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#13','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C2',2,'mc','auto','지아는 주스병의 들이가 500 mL 우유갑 2개를 합한 들이와 비슷하다고 했어요. 500 mL 우유갑 2개의 들이를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u5-X04','M3-2-u5-X06']::text[],false,'{"seq":13,"concept":"M3-2-u5-C2","difficulty":2,"kind":"mc","stem":"지아는 주스병의 들이가 500 mL 우유갑 2개를 합한 들이와 비슷하다고 했어요. 500 mL 우유갑 2개의 들이를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1 L","correct":true},{"t":"100 L","mis":"M3-2-u5-X04"},{"t":"10 L","mis":"M3-2-u5-X04"},{"t":"1000 L","mis":"M3-2-u5-X06"}],"explanation":["500 mL + 500 mL = 1000 mL.","1000 mL = 1 L.","500 mL 우유갑 2개는 1 L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#14','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C6',2,'sa','auto','승우의 재활용품은 1300 g, 연아의 재활용품은 1100 g이에요. 승우의 재활용품은 연아의 재활용품보다 몇 g 더 무거운가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M3-2-u5-C6","difficulty":2,"kind":"sa","stem":"승우의 재활용품은 1300 g, 연아의 재활용품은 1100 g이에요. 승우의 재활용품은 연아의 재활용품보다 몇 g 더 무거운가요? 숫자로 쓰세요.","answer":["200"],"explanation":["같은 g 단위라 바로 견줄 수 있어요.","1300 − 1100 = 200.","승우의 재활용품이 200 g 더 무거워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#15','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C7',2,'sa','auto','10 kg인 소금이 몇 포대 있어야 1 t이 될까요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M3-2-u5-C7","difficulty":2,"kind":"sa","stem":"10 kg인 소금이 몇 포대 있어야 1 t이 될까요? 숫자로 쓰세요.","answer":["100"],"explanation":["1 t = 1000 kg이에요.","10 × 100 = 1000.","10 kg인 소금 100포대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#16','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C10',2,'sa','auto','먹이 20 kg을 나누어 담으려고 해요. 먹이를 4 kg 봉지 3개, 2 kg 봉지 4개에 나누어 담으면 모두 몇 kg 담을 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"M3-2-u5-C10","difficulty":2,"kind":"sa","stem":"먹이 20 kg을 나누어 담으려고 해요. 먹이를 4 kg 봉지 3개, 2 kg 봉지 4개에 나누어 담으면 모두 몇 kg 담을 수 있나요? 숫자로 쓰세요.","answer":["20"],"explanation":["봉지마다 담는 양을 구해요 — 4 kg 봉지 3개는 12 kg, 2 kg 봉지 4개는 8 kg.","모두 더해요: 12 kg + 8 kg = 20 kg.","20 kg — 남김없이 담을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#17','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C2',3,'mc','auto','우유병의 들이는 1 L 100 mL, 꽃병의 들이는 1200 mL예요. 들이가 더 많은 것은 어느 것인가요?',ARRAY['M3-2-u5-X23','M3-2-u5-X21']::text[],false,'{"seq":17,"concept":"M3-2-u5-C2","difficulty":3,"kind":"mc","stem":"우유병의 들이는 1 L 100 mL, 꽃병의 들이는 1200 mL예요. 들이가 더 많은 것은 어느 것인가요?","options":[{"t":"꽃병","correct":true},{"t":"우유병","mis":"M3-2-u5-X23"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 비교할 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["1 L 100 mL = 1100 mL예요.","1100 mL < 1200 mL.","꽃병의 들이가 더 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#18','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C5',3,'sa','auto','양팔저울과 쌓기나무를 사용하여 무게를 비교했어요. 지우개의 무게는 쌓기나무 7개, 풀의 무게는 쌓기나무 11개의 무게와 같아요. 지우개는 풀보다 쌓기나무 몇 개만큼 더 가벼운가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M3-2-u5-C5","difficulty":3,"kind":"sa","stem":"양팔저울과 쌓기나무를 사용하여 무게를 비교했어요. 지우개의 무게는 쌓기나무 7개, 풀의 무게는 쌓기나무 11개의 무게와 같아요. 지우개는 풀보다 쌓기나무 몇 개만큼 더 가벼운가요? 숫자로 쓰세요.","answer":["4"],"explanation":["같은 쌓기나무로 재었으니 개수로 견줄 수 있어요.","지우개 7개, 풀 11개 — 개수가 많을수록 더 무거워요.","11 − 7 = 4 — 쌓기나무 4개만큼 더 가벼워요."],"asset":{"type":"balance","scales":[{"l":{"name":"지우개","icon":"🧽"},"r":{"name":"쌓기나무 7개","icon":"🟫"},"down":"eq"},{"l":{"name":"풀","icon":"🧴"},"r":{"name":"쌓기나무 11개","icon":"🟫"},"down":"eq"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#19','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C8',3,'mc','auto','무게를 잘못 어림한 사람은 누구인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X08']::text[],false,'{"seq":19,"concept":"M3-2-u5-C8","difficulty":3,"kind":"mc","stem":"무게를 잘못 어림한 사람은 누구인가요?","options":[{"t":"정후","correct":true},{"t":"민준","mis":"M3-2-u5-X20"},{"t":"서윤","mis":"M3-2-u5-X20"},{"t":"모두 바르게 어림했어요","mis":"M3-2-u5-X08"}],"explanation":["정후 — 50 g 공책 10권은 500 g, 약 500 g이에요.","민준 — 밀가루 1 kg과 비슷해 약 1 kg — 알맞아요.","서윤 — 200 + 200 + 100 = 500, 약 500 g — 알맞아요."],"asset":{"type":"speech","turns":[{"who":"정후","text":"위인전의 무게는 50 g인 공책 10권의 무게와 비슷해서 약 5 kg이야."},{"who":"민준","text":"설탕의 무게는 밀가루 1 kg의 무게와 비슷해서 약 1 kg이야."},{"who":"서윤","text":"배의 무게는 200 g인 사과 2개와 100 g인 귤 1개를 합한 무게와 비슷해서 약 500 g이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#20','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C10',3,'sa','auto','초록 목장에서 우유 90 L를 10 L, 6 L, 5 L 통에 남김없이 나누어 담으려고 해요. 6 L 통 5개를 사용한다면 10 L 통은 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M3-2-u5-C10","difficulty":3,"kind":"sa","stem":"초록 목장에서 우유 90 L를 10 L, 6 L, 5 L 통에 남김없이 나누어 담으려고 해요. 6 L 통 5개를 사용한다면 10 L 통은 몇 개 필요한가요? 숫자로 쓰세요.","answer":["6"],"explanation":["6 L 통 5개에 담는 양: 30 L.","남은 양: 90 L − 30 L = 60 L.","60 ÷ 10 = 6 — 10 L 통 6개가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#21','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C4',3,'sa','auto','물통의 들이는 1 L 900 mL예요. 들이가 1 L 300 mL인 병 가와 300 mL인 병 다에 물을 가득 채워 빈 물통에 모두 부었어요. 물통에 물을 몇 mL 더 채울 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M3-2-u5-C4","difficulty":3,"kind":"sa","stem":"물통의 들이는 1 L 900 mL예요. 들이가 1 L 300 mL인 병 가와 300 mL인 병 다에 물을 가득 채워 빈 물통에 모두 부었어요. 물통에 물을 몇 mL 더 채울 수 있나요? 숫자로 쓰세요.","answer":["300"],"explanation":["1 L 300 mL + 300 mL = 1 L 600 mL.","1 L 900 mL − 1 L 600 mL = 300 mL.","300 mL를 더 채울 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#22','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C9',3,'sa','auto','친구 3명의 가방 무게는 각각 4 kg 100 g, 1 kg 500 g, 3 kg 200 g이에요. 세 가방의 무게를 모두 더하면 몇 g인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M3-2-u5-C9","difficulty":3,"kind":"sa","stem":"친구 3명의 가방 무게는 각각 4 kg 100 g, 1 kg 500 g, 3 kg 200 g이에요. 세 가방의 무게를 모두 더하면 몇 g인가요? 숫자로 쓰세요.","answer":["8800"],"explanation":["g끼리 100 + 500 + 200 = 800.","kg끼리 4 + 1 + 3 = 8.","8 kg 800 g = 8800 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#23','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C4',4,'essay','teacher','사과주스 2병의 들이는 1 L 300 mL와 650 mL이고, 당근주스 2병의 들이는 1 L 150 mL와 700 mL예요. 어느 주스가 몇 mL 더 많은지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u5-C4","difficulty":4,"kind":"essay","stem":"사과주스 2병의 들이는 1 L 300 mL와 650 mL이고, 당근주스 2병의 들이는 1 L 150 mL와 700 mL예요. 어느 주스가 몇 mL 더 많은지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 사과주스는 1 L 300 mL + 650 mL = 1 L 950 mL, 당근주스는 1 L 150 mL + 700 mL = 1 L 850 mL이다. 1 L 950 mL − 1 L 850 mL = 100 mL이므로 사과주스가 100 mL 더 많다.","scoring_points":["사과주스 들이의 합 1 L 950 mL를 구했는가","당근주스 들이의 합 1 L 850 mL를 구했는가","사과주스가 100 mL 더 많다고 답했는가"]},"explanation":["1 L 300 mL + 650 mL = 1 L 950 mL.","1 L 150 mL + 700 mL = 1 L 850 mL.","1 L 950 mL − 1 L 850 mL = 100 mL."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#24','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C10',4,'essay','teacher','초록 목장에서 우유 90 L를 10 L, 6 L, 5 L 담을 수 있는 통(각각 7개)에 남김없이 나누어 담으려고 해요. 6 L 통을 5개 사용한다고 할 때 10 L 통과 5 L 통은 각각 몇 개 사용하면 되는지 한 가지를 예상하고 확인해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u5-C10","difficulty":4,"kind":"essay","stem":"초록 목장에서 우유 90 L를 10 L, 6 L, 5 L 담을 수 있는 통(각각 7개)에 남김없이 나누어 담으려고 해요. 6 L 통을 5개 사용한다고 할 때 10 L 통과 5 L 통은 각각 몇 개 사용하면 되는지 한 가지를 예상하고 확인해 보세요.","answer_guide":{"answer":"예: 6 L 통 5개는 30 L이므로 남은 60 L를 담아야 한다. 10 L 통 6개를 사용하면 60 L이므로 5 L 통은 사용하지 않는다. 30 L + 60 L = 90 L로 예상이 맞다. (10 L 5개·5 L 2개, 10 L 4개·5 L 4개, 10 L 3개·5 L 6개도 가능)","scoring_points":["6 L 통 5개가 30 L임을 구했는가","남은 60 L를 10 L·5 L 통으로 나누어 담는 방법을 예상했는가","모두 더해 90 L인지 확인했는가"]},"explanation":["6 × 5 = 30 — 남은 양은 90 − 30 = 60.","10 L 통 6개 = 60 L.","30 L + 60 L = 90 L."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_b#25','math',3,2,'u5','','tb_g3_2_math_u5_review_b','unit_review','M3-2-u5-C5',4,'essay','teacher','공깃돌로 지우개, 자, 연필의 무게를 재었더니 지우개는 10개, 자는 9개, 연필은 8개와 무게가 같았어요. 「연필이 가장 무겁다.」는 생각이 틀린 까닭을 쓰고, 무거운 것부터 차례대로 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u5-C5","difficulty":4,"kind":"essay","stem":"공깃돌로 지우개, 자, 연필의 무게를 재었더니 지우개는 10개, 자는 9개, 연필은 8개와 무게가 같았어요. 「연필이 가장 무겁다.」는 생각이 틀린 까닭을 쓰고, 무거운 것부터 차례대로 써 보세요.","answer_guide":{"answer":"예: 같은 공깃돌로 재면 공깃돌이 많이 필요할수록 더 무겁다. 연필은 공깃돌이 가장 적게 필요하므로 가장 가볍다. 무거운 것부터 지우개, 자, 연필이다.","scoring_points":["개수가 많을수록 무겁다고 썼는가","연필이 가장 가볍다고 했는가","지우개, 자, 연필 차례로 썼는가"]},"explanation":["같은 단위 — 개수가 많을수록 무거워요.","10개 > 9개 > 8개.","지우개, 자, 연필."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#1','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C3',1,'sa','auto','물을 비커에 담았어요. 비커의 0과 500 mL 사이가 똑같이 5칸으로 나뉘어 있고, 물이 0에서부터 4칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M3-2-u5-C3","difficulty":1,"kind":"sa","stem":"물을 비커에 담았어요. 비커의 0과 500 mL 사이가 똑같이 5칸으로 나뉘어 있고, 물이 0에서부터 4칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["400"],"explanation":["한 칸의 크기부터: 0~500 mL 사이 5칸 → 500 ÷ 5 = 100, 한 칸은 100 mL예요.","4칸 → 100 × 4 = 400.","400 mL예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#2','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C6',1,'sa','auto','저울에 현미를 올렸어요. 저울의 3 kg과 4 kg 사이가 똑같이 10칸으로 나뉘어 있고, 바늘이 3 kg에서 4칸 더 간 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M3-2-u5-C6","difficulty":1,"kind":"sa","stem":"저울에 현미를 올렸어요. 저울의 3 kg과 4 kg 사이가 똑같이 10칸으로 나뉘어 있고, 바늘이 3 kg에서 4칸 더 간 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["3400"],"explanation":["한 칸의 크기부터: 3 kg~4 kg 사이 10칸 → 1000 ÷ 10 = 100, 한 칸은 100 g이에요.","3 kg에서 4칸 더 → 3000 + 100 × 4 = 3400.","3400 g = 3 kg 400 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#3','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C2',1,'sa','auto','1 L 800 mL는 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u5-C2","difficulty":1,"kind":"sa","stem":"1 L 800 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["1800"],"explanation":["1 L = 1000 mL예요.","1000 mL + 800 mL = 1800 mL.","1 L 800 mL = 1800 mL."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#4','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C6',1,'sa','auto','4900 g은 몇 kg 몇 g인가요? g 앞에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u5-C6","difficulty":1,"kind":"sa","stem":"4900 g은 몇 kg 몇 g인가요? g 앞에 알맞은 수를 쓰세요.","answer":["900"],"explanation":["1000 g = 1 kg이에요.","4900 g = 4000 g + 900 g.","4900 g = 4 kg 900 g — g 앞의 수는 900이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#5','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C7',1,'sa','auto','6 t은 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M3-2-u5-C7","difficulty":1,"kind":"sa","stem":"6 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["6000"],"explanation":["1 t = 1000 kg이에요.","6 t은 1000 kg이 6번이에요.","6 t = 6000 kg."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#6','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C8',1,'mc','auto','판다의 무게는 약 130 ○예요. ○에 알맞은 단위는 어느 것인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],false,'{"seq":6,"concept":"M3-2-u5-C8","difficulty":1,"kind":"mc","stem":"판다의 무게는 약 130 ○예요. ○에 알맞은 단위는 어느 것인가요?","options":[{"t":"kg","correct":true},{"t":"g","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["판다를 아는 무게와 견주어 보아요.","무게에 쓰는 단위는 g·kg·t이에요.","판다의 무게는 약 130 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#7','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C4',1,'mc','auto','계산해 보세요. 2 L 400 mL + 1 L 200 mL',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],false,'{"seq":7,"concept":"M3-2-u5-C4","difficulty":1,"kind":"mc","stem":"계산해 보세요. 2 L 400 mL + 1 L 200 mL","options":[{"t":"3 L 600 mL","correct":true},{"t":"1 L 200 mL","mis":"M3-2-u5-X14"},{"t":"3 L 700 mL","mis":"M3-2-u5-X24"},{"t":"3 L 500 mL","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","mL끼리 400 + 200 = 600, L끼리 2 + 1 = 3.","2 L 400 mL + 1 L 200 mL = 3 L 600 mL."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#8','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C9',1,'mc','auto','계산해 보세요. 5 kg 400 g + 4 kg 300 g',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],false,'{"seq":8,"concept":"M3-2-u5-C9","difficulty":1,"kind":"mc","stem":"계산해 보세요. 5 kg 400 g + 4 kg 300 g","options":[{"t":"9 kg 700 g","correct":true},{"t":"1 kg 100 g","mis":"M3-2-u5-X14"},{"t":"9 kg 800 g","mis":"M3-2-u5-X24"},{"t":"9 kg 600 g","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","g끼리 400 + 300 = 700, kg끼리 5 + 4 = 9.","5 kg 400 g + 4 kg 300 g = 9 kg 700 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#9','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C9',2,'mc','auto','쌀 3 kg 800 g 중에서 1 kg 400 g을 사용하여 떡을 만들었어요. 떡을 만들고 남은 쌀의 무게는 얼마인가요?',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],false,'{"seq":9,"concept":"M3-2-u5-C9","difficulty":2,"kind":"mc","stem":"쌀 3 kg 800 g 중에서 1 kg 400 g을 사용하여 떡을 만들었어요. 떡을 만들고 남은 쌀의 무게는 얼마인가요?","options":[{"t":"2 kg 400 g","correct":true},{"t":"5 kg 200 g","mis":"M3-2-u5-X14"},{"t":"2 kg 500 g","mis":"M3-2-u5-X24"},{"t":"2 kg 300 g","mis":"M3-2-u5-X24"}],"explanation":["처음에 있던 쌀의 무게에서 사용한 쌀의 무게를 빼요 — 식은 3 kg 800 g − 1 kg 400 g.","g끼리 800 − 400 = 400, kg끼리 3 − 1 = 2.","3 kg 800 g − 1 kg 400 g = 2 kg 400 g — 남은 쌀은 2 kg 400 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#10','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C9',2,'mc','auto','채원이와 도윤이는 작아진 옷을 모아 함께 기부하려고 해요. 채원이는 1 kg 500 g, 도윤이는 2 kg 300 g의 옷을 모았어요. 모은 옷의 무게는 모두 얼마인가요?',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],false,'{"seq":10,"concept":"M3-2-u5-C9","difficulty":2,"kind":"mc","stem":"채원이와 도윤이는 작아진 옷을 모아 함께 기부하려고 해요. 채원이는 1 kg 500 g, 도윤이는 2 kg 300 g의 옷을 모았어요. 모은 옷의 무게는 모두 얼마인가요?","options":[{"t":"3 kg 800 g","correct":true},{"t":"800 g","mis":"M3-2-u5-X14"},{"t":"3 kg 900 g","mis":"M3-2-u5-X24"},{"t":"3 kg 700 g","mis":"M3-2-u5-X24"}],"explanation":["채원이가 모은 옷의 무게와 도윤이가 모은 옷의 무게를 더해요 — 식은 1 kg 500 g + 2 kg 300 g.","g끼리 500 + 300 = 800, kg끼리 1 + 2 = 3.","1 kg 500 g + 2 kg 300 g = 3 kg 800 g — 모은 옷은 모두 3 kg 800 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#11','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C4',2,'sa','auto','물통의 들이는 1 L 900 mL예요. 들이가 1 L 300 mL인 병 가와 400 mL인 병 라에 물을 가득 채워 빈 물통에 모두 부었어요. 물통에 물을 몇 mL 더 채울 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M3-2-u5-C4","difficulty":2,"kind":"sa","stem":"물통의 들이는 1 L 900 mL예요. 들이가 1 L 300 mL인 병 가와 400 mL인 병 라에 물을 가득 채워 빈 물통에 모두 부었어요. 물통에 물을 몇 mL 더 채울 수 있나요? 숫자로 쓰세요.","answer":["200"],"explanation":["두 병의 들이의 합: 1 L 300 mL + 400 mL = 1 L 700 mL.","1 L 900 mL − 1 L 700 mL = 200 mL.","200 mL를 더 채울 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#12','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C8',2,'sa','auto','위인전의 무게는 50 g인 공책 10권의 무게와 비슷해요. 위인전의 무게는 약 몇 g인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M3-2-u5-C8","difficulty":2,"kind":"sa","stem":"위인전의 무게는 50 g인 공책 10권의 무게와 비슷해요. 위인전의 무게는 약 몇 g인가요? 숫자로 쓰세요.","answer":["500"],"explanation":["50 g이 10권이에요.","50 × 10 = 500.","약 500 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#13','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C2',2,'mc','auto','500 mL 우유갑 1개와 1 L 우유갑 1개를 합한 들이를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u5-X05','M3-2-u5-X11']::text[],false,'{"seq":13,"concept":"M3-2-u5-C2","difficulty":2,"kind":"mc","stem":"500 mL 우유갑 1개와 1 L 우유갑 1개를 합한 들이를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1 L 500 mL","correct":true},{"t":"15 L","mis":"M3-2-u5-X05"},{"t":"501 mL","mis":"M3-2-u5-X11"},{"t":"1 L 50 mL","mis":"M3-2-u5-X05"}],"explanation":["1 L 우유갑에 500 mL가 더 있어요.","1 L보다 500 mL 더 많은 들이는 1 L 500 mL예요.","1 L 500 mL = 1500 mL — 15 L가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#14','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C6',2,'mc','auto','1300 g은 몇 kg 몇 g인가요?',ARRAY['M3-2-u5-X04','M3-2-u5-X05','M3-2-u5-X06']::text[],false,'{"seq":14,"concept":"M3-2-u5-C6","difficulty":2,"kind":"mc","stem":"1300 g은 몇 kg 몇 g인가요?","options":[{"t":"1 kg 300 g","correct":true},{"t":"13 kg","mis":"M3-2-u5-X04"},{"t":"1 kg 30 g","mis":"M3-2-u5-X05"},{"t":"1 g 300 kg","mis":"M3-2-u5-X06"}],"explanation":["1000 g = 1 kg이에요.","1300 g = 1000 g + 300 g.","1300 g = 1 kg 300 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#15','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C7',2,'sa','auto','1 kg인 설탕이 몇 봉지 있어야 1 t이 될까요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M3-2-u5-C7","difficulty":2,"kind":"sa","stem":"1 kg인 설탕이 몇 봉지 있어야 1 t이 될까요? 숫자로 쓰세요.","answer":["1000"],"explanation":["1 t = 1000 kg이에요.","1 × 1000 = 1000.","1 kg인 설탕 1000봉지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#16','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C10',2,'sa','auto','물 80 L를 옮겨 담으려고 해요. 물을 10 L 통 6개, 5 L 통 4개에 나누어 담으면 모두 몇 L 담을 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"M3-2-u5-C10","difficulty":2,"kind":"sa","stem":"물 80 L를 옮겨 담으려고 해요. 물을 10 L 통 6개, 5 L 통 4개에 나누어 담으면 모두 몇 L 담을 수 있나요? 숫자로 쓰세요.","answer":["80"],"explanation":["통마다 담는 양을 구해요 — 10 L 통 6개는 60 L, 5 L 통 4개는 20 L.","모두 더해요: 60 L + 20 L = 80 L.","80 L — 남김없이 담을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#17','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C2',3,'mc','auto','대접의 들이는 1150 mL, 우유병의 들이는 1 L 100 mL예요. 들이가 더 많은 것은 어느 것인가요?',ARRAY['M3-2-u5-X23','M3-2-u5-X21']::text[],false,'{"seq":17,"concept":"M3-2-u5-C2","difficulty":3,"kind":"mc","stem":"대접의 들이는 1150 mL, 우유병의 들이는 1 L 100 mL예요. 들이가 더 많은 것은 어느 것인가요?","options":[{"t":"대접","correct":true},{"t":"우유병","mis":"M3-2-u5-X23"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 비교할 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["1 L 100 mL = 1100 mL예요.","1100 mL < 1150 mL.","대접의 들이가 더 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#18','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C5',3,'ox','auto','양파는 500원짜리 동전 20개, 감자는 100원짜리 동전 20개와 무게가 같아요. 양파와 감자의 무게는 같아요.',ARRAY['M3-2-u5-X16']::text[],false,'{"seq":18,"concept":"M3-2-u5-C5","difficulty":3,"kind":"ox","stem":"양파는 500원짜리 동전 20개, 감자는 100원짜리 동전 20개와 무게가 같아요. 양파와 감자의 무게는 같아요.","answer":"X","reason_options":[{"t":"500원짜리와 100원짜리 동전 한 개의 무게가 달라서","correct":true},{"t":"동전의 개수만 같으면 무게가 같아서","mis":"M3-2-u5-X16"}],"mis":"M3-2-u5-X16","explanation":["개수는 20개로 같아요.","동전 한 개의 무게가 달라요.","양파와 감자의 무게는 달라요 — 바르지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#19','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C3',3,'mc','auto','단위를 잘못 사용한 것은 어느 것인가요? ㉠ 참기름병의 들이는 약 330 mL입니다. ㉡ 요구르트병의 들이는 약 65 L입니다. ㉢ 간장병의 들이는 약 2 L입니다.',ARRAY['M3-2-u5-X09','M3-2-u5-X21']::text[],false,'{"seq":19,"concept":"M3-2-u5-C3","difficulty":3,"kind":"mc","stem":"단위를 잘못 사용한 것은 어느 것인가요? ㉠ 참기름병의 들이는 약 330 mL입니다. ㉡ 요구르트병의 들이는 약 65 L입니다. ㉢ 간장병의 들이는 약 2 L입니다.","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M3-2-u5-X09"},{"t":"㉢","mis":"M3-2-u5-X09"},{"t":"없어요","mis":"M3-2-u5-X21"}],"explanation":["요구르트병은 작은 병이에요.","65 L는 아주 많은 양이라 알맞지 않아요.","㉡이 잘못 — 요구르트병의 들이는 약 65 mL예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#20','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C10',3,'sa','auto','반려동물 용품 가게에서 강아지 사료 50 kg을 5 kg, 4 kg, 2 kg 봉지에 남김없이 나누어 담으려고 해요. 5 kg 봉지 6개를 사용한다면 4 kg 봉지는 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M3-2-u5-C10","difficulty":3,"kind":"sa","stem":"반려동물 용품 가게에서 강아지 사료 50 kg을 5 kg, 4 kg, 2 kg 봉지에 남김없이 나누어 담으려고 해요. 5 kg 봉지 6개를 사용한다면 4 kg 봉지는 몇 개 필요한가요? 숫자로 쓰세요.","answer":["5"],"explanation":["5 kg 봉지 6개에 담는 양: 30 kg.","남은 양: 50 kg − 30 kg = 20 kg.","20 ÷ 4 = 5 — 4 kg 봉지 5개가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#21','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C4',3,'sa','auto','물통의 들이는 1 L 900 mL예요. 들이가 500 mL인 병 나와 400 mL인 병 라에 물을 가득 채워 빈 물통에 모두 부었어요. 물통에 물을 몇 mL 더 채울 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M3-2-u5-C4","difficulty":3,"kind":"sa","stem":"물통의 들이는 1 L 900 mL예요. 들이가 500 mL인 병 나와 400 mL인 병 라에 물을 가득 채워 빈 물통에 모두 부었어요. 물통에 물을 몇 mL 더 채울 수 있나요? 숫자로 쓰세요.","answer":["1000"],"explanation":["500 mL + 400 mL = 900 mL.","1 L 900 mL − 900 mL = 1 L.","1 L = 1000 mL를 더 채울 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#22','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C9',3,'sa','auto','오이 상자는 5 kg 650 g, 양파 상자는 5 kg 605 g, 당근 상자는 3 kg 120 g이에요. 가장 무거운 상자와 가장 가벼운 상자의 무게의 차는 몇 g인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M3-2-u5-C9","difficulty":3,"kind":"sa","stem":"오이 상자는 5 kg 650 g, 양파 상자는 5 kg 605 g, 당근 상자는 3 kg 120 g이에요. 가장 무거운 상자와 가장 가벼운 상자의 무게의 차는 몇 g인가요? 숫자로 쓰세요.","answer":["2530"],"explanation":["가장 무거운 오이 5 kg 650 g, 가장 가벼운 당근 3 kg 120 g.","5 kg 650 g − 3 kg 120 g = 2 kg 530 g.","2530 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#23','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C4',4,'essay','teacher','들이가 1 L 200 mL인 물병과 250 mL인 컵에 물이 가득 담겨 있었어요. 이 물을 빈 주전자에 모두 부었더니 400 mL가 넘쳤어요. 주전자의 들이는 몇 L 몇 mL인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u5-C4","difficulty":4,"kind":"essay","stem":"들이가 1 L 200 mL인 물병과 250 mL인 컵에 물이 가득 담겨 있었어요. 이 물을 빈 주전자에 모두 부었더니 400 mL가 넘쳤어요. 주전자의 들이는 몇 L 몇 mL인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 1 L 200 mL + 250 mL = 1 L 450 mL이고, 400 mL가 넘쳤으므로 주전자의 들이는 1 L 450 mL − 400 mL = 1 L 50 mL이다. 답: 1 L 50 mL","scoring_points":["물병과 컵의 들이의 합을 구했는가","넘친 400 mL를 뺐는가","1 L 50 mL를 구했는가"]},"explanation":["1 L 200 mL + 250 mL = 1 L 450 mL.","넘친 양을 빼요.","1 L 450 mL − 400 mL = 1 L 50 mL."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#24','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C3',4,'essay','teacher','정후는 주스병의 들이를 「500 mL 우유갑 1개와 1 L 우유갑 1개를 합한 들이와 비슷할 것 같아서 약 15 L야.」라고 어림했어요. 잘못된 곳을 바르게 고치고, 들이를 어림할 때 주의할 점을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u5-C3","difficulty":4,"kind":"essay","stem":"정후는 주스병의 들이를 「500 mL 우유갑 1개와 1 L 우유갑 1개를 합한 들이와 비슷할 것 같아서 약 15 L야.」라고 어림했어요. 잘못된 곳을 바르게 고치고, 들이를 어림할 때 주의할 점을 써 보세요.","answer_guide":{"answer":"예: 500 mL와 1 L를 합하면 1 L 500 mL(1500 mL)이므로 「약 1 L 500 mL야」라고 고친다. 들이를 어림할 때는 아는 들이와 견주어 생각하고, 물건에 알맞은 단위를 쓰며, 어림한 값 앞에 「약」을 붙인다.","scoring_points":["약 1 L 500 mL(약 1500 mL)로 고쳤는가","알맞은 단위를 써야 한다고 했는가","「약」을 붙인다고 했는가"]},"explanation":["1 L + 500 mL = 1 L 500 mL.","1 L 500 mL = 1500 mL.","알맞은 단위와 「약」을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_c#25','math',3,2,'u5','','tb_g3_2_math_u5_review_c','unit_review','M3-2-u5-C8',4,'essay','teacher','필통의 무게를 약 400 g으로 어림하고 저울로 재어 보니 360 g이었어요. 어림한 무게와 잰 무게가 다르면 어림을 잘못한 것인지 판단하고, 어림을 잘하려면 어떻게 해야 하는지 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u5-C8","difficulty":4,"kind":"essay","stem":"필통의 무게를 약 400 g으로 어림하고 저울로 재어 보니 360 g이었어요. 어림한 무게와 잰 무게가 다르면 어림을 잘못한 것인지 판단하고, 어림을 잘하려면 어떻게 해야 하는지 써 보세요.","answer_guide":{"answer":"예: 잘못한 것이 아니다. 어림은 저울 없이 얼마쯤인지 생각하는 것이라 잰 무게와 다를 수 있다. 어림을 잘하려면 약 400 g인 물통처럼 무게를 알고 있는 물건과 견주거나, 알고 있는 물건 몇 개와 비슷한지 생각한다.","scoring_points":["어림한 값과 잰 값이 달라도 된다고 했는가","어림의 뜻을 썼는가","아는 무게와 견주는 등 방법을 썼는가"]},"explanation":["어림 = 얼마쯤인지 생각하기.","400 g과 360 g의 차는 40 g이에요.","아는 무게와 견주면 더 잘 어림할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#1','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C3',1,'sa','auto','컵에 물을 가득 채운 후 비커에 모두 옮겨 담았어요. 비커의 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있고, 물이 0에서부터 10칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M3-2-u5-C3","difficulty":1,"kind":"sa","stem":"컵에 물을 가득 채운 후 비커에 모두 옮겨 담았어요. 비커의 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있고, 물이 0에서부터 10칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["1000"],"explanation":["한 칸의 크기부터: 0~1000 mL 사이 10칸 → 1000 ÷ 10 = 100, 한 칸은 100 mL예요.","10칸 → 100 × 10 = 1000.","1 L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#2','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C6',1,'sa','auto','서준이가 모은 재활용품을 저울에 올렸어요. 저울의 2 kg과 3 kg 사이가 똑같이 10칸으로 나뉘어 있고, 바늘이 2 kg에서 3칸 더 간 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M3-2-u5-C6","difficulty":1,"kind":"sa","stem":"서준이가 모은 재활용품을 저울에 올렸어요. 저울의 2 kg과 3 kg 사이가 똑같이 10칸으로 나뉘어 있고, 바늘이 2 kg에서 3칸 더 간 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["2300"],"explanation":["한 칸의 크기부터: 2 kg~3 kg 사이 10칸 → 1000 ÷ 10 = 100, 한 칸은 100 g이에요.","2 kg에서 3칸 더 → 2000 + 100 × 3 = 2300.","2300 g = 2 kg 300 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#3','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C2',1,'sa','auto','5800 mL는 몇 L 몇 mL인가요? L 앞에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u5-C2","difficulty":1,"kind":"sa","stem":"5800 mL는 몇 L 몇 mL인가요? L 앞에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["1000 mL = 1 L예요.","5800 mL = 5000 mL + 800 mL.","5800 mL = 5 L 800 mL — L 앞의 수는 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#4','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C6',1,'sa','auto','3 kg 600 g은 몇 g인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u5-C6","difficulty":1,"kind":"sa","stem":"3 kg 600 g은 몇 g인가요? 숫자로 쓰세요.","answer":["3600"],"explanation":["1 kg = 1000 g — 3 kg = 3000 g.","3000 g + 600 g = 3600 g.","3 kg 600 g = 3600 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#5','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C7',1,'mc','auto','8000 kg은 몇 t인가요?',ARRAY['M3-2-u5-X17','M3-2-u5-X06']::text[],false,'{"seq":5,"concept":"M3-2-u5-C7","difficulty":1,"kind":"mc","stem":"8000 kg은 몇 t인가요?","options":[{"t":"8 t","correct":true},{"t":"80 t","mis":"M3-2-u5-X17"},{"t":"800 t","mis":"M3-2-u5-X17"},{"t":"8000 t","mis":"M3-2-u5-X06"}],"explanation":["1000 kg = 1 t이에요.","8000 kg은 1000 kg이 8번이에요.","8000 kg = 8 t."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#6','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C8',1,'mc','auto','사과의 무게는 약 300 ○예요. ○에 알맞은 단위는 어느 것인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],false,'{"seq":6,"concept":"M3-2-u5-C8","difficulty":1,"kind":"mc","stem":"사과의 무게는 약 300 ○예요. ○에 알맞은 단위는 어느 것인가요?","options":[{"t":"g","correct":true},{"t":"kg","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["사과를 아는 무게와 견주어 보아요.","무게에 쓰는 단위는 g·kg·t이에요.","사과의 무게는 약 300 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#7','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C4',1,'mc','auto','계산해 보세요. 5 L 500 mL − 3 L 100 mL',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],false,'{"seq":7,"concept":"M3-2-u5-C4","difficulty":1,"kind":"mc","stem":"계산해 보세요. 5 L 500 mL − 3 L 100 mL","options":[{"t":"2 L 400 mL","correct":true},{"t":"8 L 600 mL","mis":"M3-2-u5-X14"},{"t":"2 L 500 mL","mis":"M3-2-u5-X24"},{"t":"2 L 300 mL","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","mL끼리 500 − 100 = 400, L끼리 5 − 3 = 2.","5 L 500 mL − 3 L 100 mL = 2 L 400 mL."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#8','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C9',1,'mc','auto','계산해 보세요. 9 kg 800 g − 6 kg 600 g',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],false,'{"seq":8,"concept":"M3-2-u5-C9","difficulty":1,"kind":"mc","stem":"계산해 보세요. 9 kg 800 g − 6 kg 600 g","options":[{"t":"3 kg 200 g","correct":true},{"t":"16 kg 400 g","mis":"M3-2-u5-X14"},{"t":"3 kg 300 g","mis":"M3-2-u5-X24"},{"t":"3 kg 100 g","mis":"M3-2-u5-X24"}],"explanation":["같은 단위의 수끼리 계산해요.","g끼리 800 − 600 = 200, kg끼리 9 − 6 = 3.","9 kg 800 g − 6 kg 600 g = 3 kg 200 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#9','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C9',2,'mc','auto','텃밭에서 준우는 당근을 4 kg 100 g 캤고, 소율이는 당근을 5 kg 800 g 캤어요. 준우와 소율이가 캔 당근의 무게의 차는 얼마인가요?',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],false,'{"seq":9,"concept":"M3-2-u5-C9","difficulty":2,"kind":"mc","stem":"텃밭에서 준우는 당근을 4 kg 100 g 캤고, 소율이는 당근을 5 kg 800 g 캤어요. 준우와 소율이가 캔 당근의 무게의 차는 얼마인가요?","options":[{"t":"1 kg 700 g","correct":true},{"t":"9 kg 900 g","mis":"M3-2-u5-X14"},{"t":"1 kg 800 g","mis":"M3-2-u5-X24"},{"t":"1 kg 600 g","mis":"M3-2-u5-X24"}],"explanation":["무거운 쪽에서 가벼운 쪽을 빼요 — 식은 5 kg 800 g − 4 kg 100 g.","g끼리 800 − 100 = 700, kg끼리 5 − 4 = 1.","5 kg 800 g − 4 kg 100 g = 1 kg 700 g — 당근의 무게의 차는 1 kg 700 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#10','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C9',2,'mc','auto','텃밭에서 준우는 당근을 4 kg 100 g 캤고, 소율이는 당근을 5 kg 800 g 캤어요. 준우와 소율이가 캔 당근의 무게의 합은 얼마인가요?',ARRAY['M3-2-u5-X14','M3-2-u5-X24']::text[],false,'{"seq":10,"concept":"M3-2-u5-C9","difficulty":2,"kind":"mc","stem":"텃밭에서 준우는 당근을 4 kg 100 g 캤고, 소율이는 당근을 5 kg 800 g 캤어요. 준우와 소율이가 캔 당근의 무게의 합은 얼마인가요?","options":[{"t":"9 kg 900 g","correct":true},{"t":"1 kg 700 g","mis":"M3-2-u5-X14"},{"t":"10 kg","mis":"M3-2-u5-X24"},{"t":"9 kg 800 g","mis":"M3-2-u5-X24"}],"explanation":["두 사람이 캔 당근의 무게를 더해요 — 식은 4 kg 100 g + 5 kg 800 g.","g끼리 100 + 800 = 900, kg끼리 4 + 5 = 9.","4 kg 100 g + 5 kg 800 g = 9 kg 900 g — 당근의 무게의 합은 9 kg 900 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#11','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C4',2,'sa','auto','지아는 우유 2 L 550 mL 중에서 300 mL를 마셨어요. 지아가 마시고 남은 우유의 양은 2 L □ mL예요. □ 안에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M3-2-u5-C4","difficulty":2,"kind":"sa","stem":"지아는 우유 2 L 550 mL 중에서 300 mL를 마셨어요. 지아가 마시고 남은 우유의 양은 2 L □ mL예요. □ 안에 알맞은 수를 쓰세요.","answer":["250"],"explanation":["처음 우유의 양에서 마신 양을 빼요 — 식은 2 L 550 mL − 300 mL.","mL끼리 550 − 300 = 250, L끼리 2 − 0 = 2.","2 L 550 mL − 300 mL = 2 L 250 mL — 남은 우유는 2 L 250 mL예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#12','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C8',2,'sa','auto','배의 무게는 200 g인 사과 2개와 100 g인 귤 1개를 합한 무게와 비슷해요. 배의 무게는 약 몇 g인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M3-2-u5-C8","difficulty":2,"kind":"sa","stem":"배의 무게는 200 g인 사과 2개와 100 g인 귤 1개를 합한 무게와 비슷해요. 배의 무게는 약 몇 g인가요? 숫자로 쓰세요.","answer":["500"],"explanation":["사과 2개: 200 + 200 = 400.","귤 1개를 더해요: 400 + 100 = 500.","약 500 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#13','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C2',2,'mc','auto','음료수가 500 mL 정도 들어가는 컵이 있어요. 이 컵의 들이를 바르게 말한 것은 어느 것인가요?',ARRAY['M3-2-u5-X04','M3-2-u5-X09']::text[],false,'{"seq":13,"concept":"M3-2-u5-C2","difficulty":2,"kind":"mc","stem":"음료수가 500 mL 정도 들어가는 컵이 있어요. 이 컵의 들이를 바르게 말한 것은 어느 것인가요?","options":[{"t":"약 100 mL인 물건 5개의 들이와 비슷해요","correct":true},{"t":"약 100 mL인 물건 50개의 들이와 비슷해요","mis":"M3-2-u5-X04"},{"t":"약 500 L인 물건 1개의 들이와 비슷해요","mis":"M3-2-u5-X09"},{"t":"약 5 L인 물건 1개의 들이와 비슷해요","mis":"M3-2-u5-X04"}],"explanation":["약 100 mL가 몇 번이면 약 500 mL인지 생각해요.","100 × 5 = 500.","약 100 mL인 물건 5개의 들이와 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#14','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C6',2,'mc','auto','1100 g은 몇 kg 몇 g인가요?',ARRAY['M3-2-u5-X04','M3-2-u5-X05','M3-2-u5-X06']::text[],false,'{"seq":14,"concept":"M3-2-u5-C6","difficulty":2,"kind":"mc","stem":"1100 g은 몇 kg 몇 g인가요?","options":[{"t":"1 kg 100 g","correct":true},{"t":"11 kg","mis":"M3-2-u5-X04"},{"t":"1 kg 10 g","mis":"M3-2-u5-X05"},{"t":"1 g 100 kg","mis":"M3-2-u5-X06"}],"explanation":["1000 g = 1 kg이에요.","1100 g = 1000 g + 100 g.","1100 g = 1 kg 100 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#15','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C7',2,'mc','auto','3000 kg은 몇 t인가요?',ARRAY['M3-2-u5-X17','M3-2-u5-X06']::text[],false,'{"seq":15,"concept":"M3-2-u5-C7","difficulty":2,"kind":"mc","stem":"3000 kg은 몇 t인가요?","options":[{"t":"3 t","correct":true},{"t":"30 t","mis":"M3-2-u5-X17"},{"t":"300 t","mis":"M3-2-u5-X17"},{"t":"3000 t","mis":"M3-2-u5-X06"}],"explanation":["1000 kg = 1 t이에요.","3000 kg은 1000 kg이 3번이에요.","3000 kg = 3 t."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#16','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C10',2,'sa','auto','쌀 30 kg을 옮겨 담으려고 해요. 쌀을 5 kg 봉지 2개, 4 kg 봉지 4개, 2 kg 봉지 2개에 나누어 담으면 모두 몇 kg 담을 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"M3-2-u5-C10","difficulty":2,"kind":"sa","stem":"쌀 30 kg을 옮겨 담으려고 해요. 쌀을 5 kg 봉지 2개, 4 kg 봉지 4개, 2 kg 봉지 2개에 나누어 담으면 모두 몇 kg 담을 수 있나요? 숫자로 쓰세요.","answer":["30"],"explanation":["봉지마다 담는 양을 구해요 — 5 kg 봉지 2개는 10 kg, 4 kg 봉지 4개는 16 kg, 2 kg 봉지 2개는 4 kg.","모두 더해요: 10 kg + 16 kg + 4 kg = 30 kg.","30 kg — 남김없이 담을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#17','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C6',3,'mc','auto','무게가 5 kg 850 g인 상자와 5700 g인 상자가 있어요. 더 무거운 상자는 어느 것인가요?',ARRAY['M3-2-u5-X05','M3-2-u5-X21']::text[],false,'{"seq":17,"concept":"M3-2-u5-C6","difficulty":3,"kind":"mc","stem":"무게가 5 kg 850 g인 상자와 5700 g인 상자가 있어요. 더 무거운 상자는 어느 것인가요?","options":[{"t":"5 kg 850 g인 상자","correct":true},{"t":"5700 g인 상자","mis":"M3-2-u5-X05"},{"t":"두 상자의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 비교할 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["5700 g = 5 kg 700 g이에요.","5 kg 850 g > 5 kg 700 g.","5 kg 850 g인 상자가 더 무거워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#18','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C5',3,'mc','auto','공깃돌로 지우개, 자, 연필의 무게를 재었더니 지우개는 공깃돌 10개, 자는 9개, 연필은 8개와 무게가 같았어요. 가장 무거운 것은 어느 것인가요?',ARRAY['M3-2-u5-X22','M3-2-u5-X21']::text[],false,'{"seq":18,"concept":"M3-2-u5-C5","difficulty":3,"kind":"mc","stem":"공깃돌로 지우개, 자, 연필의 무게를 재었더니 지우개는 공깃돌 10개, 자는 9개, 연필은 8개와 무게가 같았어요. 가장 무거운 것은 어느 것인가요?","options":[{"t":"지우개","correct":true},{"t":"연필","mis":"M3-2-u5-X22"},{"t":"자","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["같은 공깃돌로 재면 개수가 많을수록 무거워요.","지우개 10개 > 자 9개 > 연필 8개.","가장 무거운 것은 지우개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#19','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C8',3,'mc','auto','배, 버스, 유모차, 자전거 가운데 무게가 1 t보다 더 무거운 것을 모두 고른 것은 어느 것인가요?',ARRAY['M3-2-u5-X09']::text[],false,'{"seq":19,"concept":"M3-2-u5-C8","difficulty":3,"kind":"mc","stem":"배, 버스, 유모차, 자전거 가운데 무게가 1 t보다 더 무거운 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"배, 버스","correct":true},{"t":"유모차, 자전거","mis":"M3-2-u5-X09"},{"t":"배, 자전거","mis":"M3-2-u5-X09"},{"t":"버스, 유모차","mis":"M3-2-u5-X09"}],"explanation":["1 t = 1000 kg이에요.","배와 버스는 1000 kg보다 훨씬 무거워요.","유모차와 자전거는 1 t보다 가벼워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#20','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C10',3,'sa','auto','반려동물 용품 가게에서 강아지 사료 50 kg을 5 kg, 4 kg, 2 kg 봉지에 남김없이 나누어 담으려고 해요. 5 kg 봉지 4개, 4 kg 봉지 5개를 사용한다면 2 kg 봉지는 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M3-2-u5-C10","difficulty":3,"kind":"sa","stem":"반려동물 용품 가게에서 강아지 사료 50 kg을 5 kg, 4 kg, 2 kg 봉지에 남김없이 나누어 담으려고 해요. 5 kg 봉지 4개, 4 kg 봉지 5개를 사용한다면 2 kg 봉지는 몇 개 필요한가요? 숫자로 쓰세요.","answer":["5"],"explanation":["5 kg 봉지 4개, 4 kg 봉지 5개에 담는 양: 20 kg + 20 kg = 40 kg.","남은 양: 50 kg − 40 kg = 10 kg.","10 ÷ 2 = 5 — 2 kg 봉지 5개가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#21','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C4',3,'sa','auto','들이가 1 L 200 mL인 물병과 250 mL인 컵에 물이 가득 담겨 있었어요. 이 물을 빈 주전자에 모두 부었더니 400 mL가 넘쳤어요. 주전자의 들이는 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M3-2-u5-C4","difficulty":3,"kind":"sa","stem":"들이가 1 L 200 mL인 물병과 250 mL인 컵에 물이 가득 담겨 있었어요. 이 물을 빈 주전자에 모두 부었더니 400 mL가 넘쳤어요. 주전자의 들이는 몇 mL인가요? 숫자로 쓰세요.","answer":["1050"],"explanation":["1 L 200 mL + 250 mL = 1 L 450 mL.","1 L 450 mL − 400 mL = 1 L 50 mL.","주전자의 들이는 1050 mL예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#22','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C9',3,'sa','auto','지아는 밀가루 1 kg 200 g과 쌀가루 1050 g을 섞어서 빵을 만들었어요. 사용한 밀가루와 쌀가루의 무게의 합은 몇 g인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M3-2-u5-C9","difficulty":3,"kind":"sa","stem":"지아는 밀가루 1 kg 200 g과 쌀가루 1050 g을 섞어서 빵을 만들었어요. 사용한 밀가루와 쌀가루의 무게의 합은 몇 g인가요? 숫자로 쓰세요.","answer":["2250"],"explanation":["1050 g = 1 kg 50 g이에요 — 1 kg 500 g이 아니에요.","1 kg 200 g + 1 kg 50 g = 2 kg 250 g.","2 kg 250 g = 2250 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#23','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C9',4,'essay','teacher','무게가 1500 g인 가방에 짐을 19 kg 200 g 넣었어요. 짐을 넣은 가방의 무게는 몇 kg 몇 g인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u5-C9","difficulty":4,"kind":"essay","stem":"무게가 1500 g인 가방에 짐을 19 kg 200 g 넣었어요. 짐을 넣은 가방의 무게는 몇 kg 몇 g인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 1500 g은 1 kg 500 g이므로 1 kg 500 g + 19 kg 200 g = 20 kg 700 g이다. 답: 20 kg 700 g","scoring_points":["1500 g을 1 kg 500 g으로 나타냈는가","가방의 무게와 짐의 무게를 더했는가","20 kg 700 g을 구했는가"]},"explanation":["1500 g = 1 kg 500 g.","g끼리 500 + 200 = 700, kg끼리 1 + 19 = 20.","1 kg 500 g + 19 kg 200 g = 20 kg 700 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#24','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C7',4,'essay','teacher','친구가 「1 t은 1300 kg보다 무거워. t은 kg보다 큰 단위니까.」라고 말했어요. 친구의 생각이 바른지 판단하고 까닭을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u5-C7","difficulty":4,"kind":"essay","stem":"친구가 「1 t은 1300 kg보다 무거워. t은 kg보다 큰 단위니까.」라고 말했어요. 친구의 생각이 바른지 판단하고 까닭을 써 보세요.","answer_guide":{"answer":"예: 바르지 않다. 1 t은 1000 kg이므로 1300 kg보다 300 kg 가볍다. 단위만 보고 판단하지 말고 같은 단위로 바꾸어 수를 견주어야 한다.","scoring_points":["바르지 않다고 판단했는가","1 t = 1000 kg으로 바꾸어 견주었는가","단위만 보고 판단하면 안 된다고 썼는가"]},"explanation":["1 t = 1000 kg.","1000 kg < 1300 kg.","t이 붙었다고 항상 더 무거운 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u5_review_d#25','math',3,2,'u5','','tb_g3_2_math_u5_review_d','unit_review','M3-2-u5-C8',4,'essay','teacher','가정용 저울에 빈 페트병을 올리고 1 kg이 될 때까지 물을 부었어요. 이렇게 1 kg을 만들어 보는 활동이 무게를 어림하는 데 어떻게 도움이 되는지, 무게가 약 1 g인 물건도 함께 들어 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u5-C8","difficulty":4,"kind":"essay","stem":"가정용 저울에 빈 페트병을 올리고 1 kg이 될 때까지 물을 부었어요. 이렇게 1 kg을 만들어 보는 활동이 무게를 어림하는 데 어떻게 도움이 되는지, 무게가 약 1 g인 물건도 함께 들어 설명해 보세요.","answer_guide":{"answer":"예: 1 kg을 직접 만들어 들어 보면 1 kg이 얼마나 무거운지 느낄 수 있어 다른 물건의 무게를 1 kg과 견주어 어림할 수 있다. 클립 1개는 약 1 g이므로 아주 가벼운 물건은 클립과 견주어 어림할 수 있다.","scoring_points":["1 kg의 양감을 느낄 수 있다고 했는가","1 kg과 견주어 어림한다고 했는가","약 1 g인 물건(클립 1개)을 들었는가"]},"explanation":["직접 만들어 들어 보면 1 kg의 양감이 생겨요.","클립 1개는 약 1 g이에요.","기준이 되는 무게와 견주어 어림해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
